local function introReopen()
    reopenScale.Scale=0.88
    pcall(function() game:GetService("TweenService"):Create(reopenScale,TweenInfo.new(0.25,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Scale=1}):Play() end)
end
