        showToggle(hitsButton,"HIT LOG",hudState.hits,hudState.hits and not (state.hitReady or (state.feedbackEvents and state.feedbackEvents.HitReady)))
    end

    -- Радар из stage_7: тот же круг, сетка, стрелка, расчёт и ограничение маркеров по краю.
    local LocalPlayer=localPlayer
    local stageRadar={Radar={Dots={}},Settings={Radar=false,RadarRange=250,RadarSize=120,TeamCheck=true,
        FriendColor=Color3.fromRGB(135,205,155),EnemyColor=Color3.fromRGB(245,116,108)},Targets={}}
    local function new(class,props)
        local object=Instance.new(class)
        local parent=props.Parent
        for key,value in pairs(props) do if key~="Parent" then object[key]=value end end
        object.Parent=parent
        return object
    end
    stageRadar.New=new
    stageRadar.EnsureGui=function() return gui end
    function stageRadar.Scan()
        local chars=Workspace:FindFirstChild("Characters")
        local own=(chars and chars:FindFirstChild(localPlayer.Name)) or localPlayer.Character
        local myTeam=localPlayer:GetAttribute("Team") or teamOf(own)
        local ffa=string.find(tostring(Workspace:GetAttribute("Gamemode")),"Deathmatch",1,true)~=nil
        local list,seen={},{}
        local function add(model,player)
            if not model or not model:IsA("Model") or model==own or model.Name==localPlayer.Name or seen[player or model] then return end
            local hp=tonumber(model:GetAttribute("Health"))
            local hum=model:FindFirstChildOfClass("Humanoid")
            if not hp and hum then hp=hum.Health end
            if tostring(model:GetAttribute("Dead"))=="true" or (hp and hp<=0) or (not player and hp==nil) then return end
            seen[player or model]=true
            local t=(player and player:GetAttribute("Team")) or teamOf(model)
            local mine=myTeam
            if mine==nil and localPlayer.Team then mine=localPlayer.Team.Name end
            if t==nil and player and player.Team then t=player.Team.Name end
            local known=mine~=nil and t~=nil
            table.insert(list,{Model=model,Root=model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Head") or model.PrimaryPart,
                Friendly=not ffa and known and tostring(mine)==tostring(t),
                Color=(not ffa and not known) and Color3.fromRGB(190,200,192) or nil})
        end
        if chars then for _,model in ipairs(chars:GetChildren()) do add(model,Players:FindFirstChild(model.Name)) end end
        for _,player in ipairs(Players:GetPlayers()) do add(player.Character,player) end
        stageRadar.Targets=list
    end
function stageRadar.RadarBuild()
    local visuals = stageRadar
    local radar = visuals.Radar
    if radar.Frame and radar.Frame.Parent then return radar end
    local new = visuals.New
    local frame = new("Frame", { Name = "Radar", Position = UDim2.fromOffset(24, 180), BackgroundColor3 = Color3.fromRGB(16, 16, 22), BackgroundTransparency = 0.25, Active = true, Visible = false, ZIndex = 5, Parent = visuals.EnsureGui() })
    new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = frame })
    new("UIStroke", { Thickness = 2, Color = Color3.fromRGB(140, 204, 155), Transparency = 0.2, Parent = frame })
    for _, horizontal in ipairs({ true, false }) do
        new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
            Size = horizontal and UDim2.new(1, -12, 0, 1) or UDim2.new(0, 1, 1, -12),
            BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.8, BorderSizePixel = 0, Parent = frame,
        })
    end
    local ring = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.5, 0.5), BackgroundTransparency = 1, Parent = frame })
    new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = ring })
    new("UIStroke", { Thickness = 1, Color = Color3.new(1, 1, 1), Transparency = 0.75, Parent = ring })
    new("TextLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(16, 16), BackgroundTransparency = 1, Text = "▲", TextSize = 14, Font = Enum.Font.GothamBold, TextColor3 = Color3.new(1, 1, 1), ZIndex = 3, Parent = frame })

    local dragStart, startPos, dragInput
    frame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragStart, startPos, dragInput = input.Position, frame.Position, input
            local release
            release = input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragStart, dragInput = nil, nil
                    release:Disconnect()
                end
            end)
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if not dragStart or not frame.Parent then return end
        if input == dragInput or (dragInput.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement) then
            local delta = input.Position - dragStart
            frame.Position = startPos + UDim2.fromOffset(delta.X, delta.Y)
        end
    end)
    radar.Frame = frame
    return radar
end

function stageRadar.RadarDot(index)
    local radar = stageRadar.Radar
    local dot = radar.Dots[index]
    if not dot then
        dot = stageRadar.New("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(7, 7), BorderSizePixel = 0, ZIndex = 2, Parent = radar.Frame })
        stageRadar.New("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = dot })
        radar.Dots[index] = dot
    end
    return dot
end

function stageRadar.RadarRender()
    local visuals = stageRadar
    local settings, radar = visuals.Settings, visuals.Radar
    if not settings.Radar then
        if radar.Frame then radar.Frame.Visible = false end
        return
    end
    visuals.RadarBuild()
    visuals.Scan()
    local cam = Workspace.CurrentCamera
    local chars = Workspace:FindFirstChild("Characters")
    local char = (chars and chars:FindFirstChild(LocalPlayer.Name)) or LocalPlayer.Character
    local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head") or char.PrimaryPart)
    local size = settings.RadarSize
    radar.Frame.Size = UDim2.fromOffset(size, size)
    radar.Frame.Visible = cam ~= nil and root ~= nil
    if not radar.Frame.Visible then return end

    local look = cam.CFrame.LookVector * Vector3.new(1, 0, 1)
    look = look.Magnitude > 0 and look.Unit or Vector3.new(0, 0, -1)
    local right = Vector3.new(-look.Z, 0, look.X)
    local radius = size / 2 - 6
    local used = 0
    for _, info in ipairs(visuals.Targets) do
        local model = info.Model
        local part = info.Root or (typeof(model) == "Instance" and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart))
        if not part or (settings.TeamCheck and info.Friendly) then continue end
        local rel = part.Position - root.Position
        local offset = Vector2.new(rel:Dot(right), -rel:Dot(look)) / settings.RadarRange * radius
        local outside = offset.Magnitude > radius
        if outside then offset = offset.Unit * radius end
        used += 1
        local dot = visuals.RadarDot(used)
        dot.Position = UDim2.new(0.5, offset.X, 0.5, offset.Y)
        dot.BackgroundColor3 = info.Color or (info.Friendly and settings.FriendColor or settings.EnemyColor)
        dot.BackgroundTransparency = outside and 0.55 or 0
        dot.Visible = true
    end
    for index = used + 1, #radar.Dots do radar.Dots[index].Visible = false end
end

    state.stageRadar=stageRadar
    local function clearRadar()
        local radar=stageRadar.Radar
        if radar.Frame then radar.Frame.Visible=false end
        for _,dot in ipairs(radar.Dots) do dot.Visible=false end
    end
    bindClick(radarButton,function()
        hudState.radar=not hudState.radar
        if not hudState.radar then clearRadar() end
        refreshHud()
    end)
    local function updateRadar()
        stageRadar.Settings.Radar=hudState.radar
        stageRadar.Settings.TeamCheck=config.teamCheck
        stageRadar.RadarRender()
    end

    local pending, notes = {}, {}
    local function healthOf(model)
        if not model then return nil end
        local hp=tonumber(model:GetAttribute("Health"))
        if hp then return hp end
        local human=model:FindFirstChildOfClass("Humanoid")
        return human and tonumber(human.Health) or nil
    end
    local function clearNotes()
        for _,item in ipairs(notes) do item:Destroy() end
        table.clear(notes);table.clear(pending)
    end
    bindClick(hitsButton,function()
        hudState.hits=not hudState.hits
        if not hudState.hits then clearNotes() end
        refreshHud()
    end)
    local function arrange()
        for index,item in ipairs(notes) do item.Position=UDim2.new(1,-222,0,90+(index-1)*35) end
    end
    local function notifyText(message)
        if not hudState.hits or not gui.Parent then return end
        local card=Instance.new("Frame")
        card.Name,card.Size= "NoirHitNotice",UDim2.fromOffset(206,30)
        card.BackgroundColor3,card.BackgroundTransparency,card.BorderSizePixel,card.ZIndex,card.Parent=Color3.fromRGB(14,25,17),0.08,0,7,gui
        round(card,7)
        local edge=Instance.new("UIStroke")
        edge.Color,edge.Transparency,edge.Parent=Color3.fromRGB(110,157,119),0.3,card
        local text=label(card,message,UDim2.new(1,-16,1,0),UDim2.fromOffset(8,0),10)
        text.TextColor3,text.ZIndex=Color3.fromRGB(212,238,219),8
        table.insert(notes,1,card)
        while #notes>4 do table.remove(notes):Destroy() end
        arrange()
        task.delay(3,function()
            for i,item in ipairs(notes) do if item==card then table.remove(notes,i);break end end
            card:Destroy();arrange()
        end)
    end
    local function clean(value,default,limit)
        if type(value)~="string" then value=default end
        return (value:gsub("[%c<>]", "?"):sub(1,limit))
    end
    local function notify(model,before,after)
        notifyText(string.format("HP Δ / %s · -%d · %d HP",clean(model.Name,"?",24),math.floor(before-after+0.5),math.max(0,math.floor(after+0.5))))
    end
    state.noteGameHit=function(player,packet)
        local name=clean(player and (player.DisplayName or player.Name),"?",24)
        local part=clean(packet.HitPartName,"body",18)
        notifyText("HIT / "..name.." · "..part)
    end
    state.noteGameKill=function(player,packet)
        local name=clean(player and (player.DisplayName or player.Name),"player "..tostring(packet.Victim),24)
        local weapon=clean(packet.Weapon,"?",18)
        notifyText("KILL / "..name.." · "..weapon..(packet.Headshot==true and " · HEAD" or ""))
    end
    -- Сопоставляем локальный луч и последующее уменьшение HP; автор урона не подтверждён сервером.
    state.noteLocalRay=function(result)
        if not (hudState.hits or (state.feedbackEnabled and state.feedbackEnabled())) or type(result)~="table" or type(result.Hits)~="table" then return end
        local characters=Workspace:FindFirstChild("Characters")
        if not characters then return end
        local own=characters:FindFirstChild(localPlayer.Name) or localPlayer.Character
        local myTeam=localPlayer:GetAttribute("Team") or teamOf(own)
        local ffa=string.find(tostring(Workspace:GetAttribute("Gamemode")),"Deathmatch",1,true)~=nil
        for _,hit in ipairs(result.Hits) do
            local part=type(hit)=="table" and hit.Instance
            if part and not hit.Exit then
                for _,model in ipairs(characters:GetChildren()) do
                    if isEnemy(model,own,ffa,myTeam) and part:IsDescendantOf(model) then
                        local hp=healthOf(model)
                        if hp and not pending[model] then pending[model]={hp=hp,at=os.clock()} end
                        break
                    end
                end
            end
        end
    end
    local lastRadar,lastHud,lastScope=0,0,0
    RunService.Heartbeat:Connect(function()
        local now=os.clock()
        if now-lastHud>1 then lastHud=now; refreshHud() end
        if now-lastRadar>0.12 then
            lastRadar=now
            local radarOk,radarError=pcall(updateRadar)
            if not radarOk and hudState.radar then
                if now-(state.lastRadarWarning or 0)>5 then
                    state.lastRadarWarning=now
                    warn("[Noir Radar] "..tostring(radarError))
                end
            end
            if hudState.hits or (state.feedbackEnabled and state.feedbackEnabled()) then
                for model,shot in pairs(pending) do
                    local hp=model.Parent and healthOf(model)
                    if hp and hp<shot.hp then
                        local events=state.feedbackEvents
                        local useGameEvent=events and (hp<=0 and events.KillReady or hp>0 and events.HitReady)
                        if not useGameEvent then notify(model,shot.hp,hp) end
                        if state.showHitFeedback and not useGameEvent then pcall(state.showHitFeedback,model,shot.hp,hp) end
                        pending[model]=nil
                    elseif not model.Parent or now-shot.at>1.5 then pending[model]=nil end
                end
            end
        end
        if extras.autoScope and now-lastScope>0.35 then
            lastScope=now
            local target=state.target
            if not target or not target.Parent then local ok,v=pcall(selectTarget); if ok then target=v end end
            if target and target.Parent then
                local controller=state.rapid and state.rapid.controller
                local getter=controller and controller.peekCurrentEquippedForMovement
                if type(getter)=="function" then
                    local ok,weapon=pcall(getter)
                    local props=ok and type(weapon)=="table" and weapon.Properties
                    if props and (props.HasScope or props.AimingOptions=="SniperScope") and weapon.Player==localPlayer
                        and not weapon.IsAiming and not weapon.IsDestroyed and not weapon.IsReloading and type(weapon.scope)=="function" then
                        requestScope(weapon,now)
                    end
                end
            end
        end
    end)
    refreshHud()
end


-- Movement: прыжковая команда игры и камера от третьего лица.
do
    local movement = {bhop=false, autoStrafe=false, slowWalk=false, third=false, collision=true, distance=8, bhopReady=false, thirdReady=false}
    state.movement = movement
    local bhopButton = makeToggle("BHOP", 30)
    local thirdButton = makeToggle("THIRD PERSON", 31)
    local function refreshMovement()
        showToggle(bhopButton, "BHOP", movement.bhop, movement.bhop and not movement.bhopReady)
        showToggle(thirdButton, "THIRD PERSON", movement.third, movement.third and not movement.thirdReady)
    end
    state.thirdButton=thirdButton
    bindClick(bhopButton,function()
        movement.bhop=not movement.bhop
        refreshMovement()
    end)
    bindClick(thirdButton,function() movement.third=not movement.third; refreshMovement() end)
    refreshMovement()

    -- MovementV2 input: сохраняем штатную логику Bhop и изменяем только нужные поля команды.
    local lastGroundPulse,lastStrafeYaw,strafeSide = false,nil,1
    local context={alive=false,character=nil,blocked=true};movement.context=context
    local lastMovementContext=0;local movementContextConnection
    movementContextConnection=RunService.Heartbeat:Connect(function()
        if not gui.Parent then context.alive=false;context.blocked=true;movementContextConnection:Disconnect();return end
        local now=os.clock();if now-lastMovementContext<0.05 then return end;lastMovementContext=now
        local ok=pcall(function()
            context.character=localPlayer.Character;context.alive=true
            context.blocked=not context.character or localPlayer:GetAttribute("IsDefusingBomb")==true or localPlayer:GetAttribute("IsLocallyDefusingBomb")==true or localPlayer:GetAttribute("IsPlantingBomb")==true
        end)
        if not ok then context.blocked=true end
    end)
    local function editCommand(character, command)
        if type(character)~="table" or type(command)~="table" or not context.alive or context.blocked then lastGroundPulse=false;lastStrafeYaw=nil;return end
        if character.Player and character.Player~=localPlayer then return end
        if character.Character and context.character and character.Character~=context.character then return end
        local ms=type(character.MovementState)=="table" and character.MovementState or nil
        local grounded=ms and ms.OnGround
        if type(grounded)~="boolean" then grounded=character.OnGround end
        local walking=not ms or ms.MovementMode==nil or ms.MovementMode=="Walking"
        if movement.slowWalk and walking and grounded==true and type(command.Buttons)=="number" then
            command.Buttons=bit32.bor(command.Buttons,4) -- стандартный Walk MovementV2
        end
        if movement.autoStrafe and walking and grounded==false and typeof(command.Move)=="Vector2" then
            local velocity=ms and ms.Velocity or character.GlobalVelocity
            local yaw=tonumber(command.LookYaw) or (ms and tonumber(ms.LookYaw))
            if typeof(velocity)=="Vector3" and yaw then
                local vx,vz=velocity.X,velocity.Z
                local speed=math.sqrt(vx*vx+vz*vz)
                if speed>0.05 then
                    local nx,nz=vz/speed,-vx/speed
                    local sy,cy=math.sin(yaw),math.cos(yaw)
                    local m=command.Move
                    local wishX,wishZ=cy*m.X+sy*m.Y,-sy*m.X+cy*m.Y
                    local side=wishX*nx+wishZ*nz
                    if math.abs(side)>0.01 then strafeSide=side>0 and 1 or -1
                    elseif lastStrafeYaw then
                        local delta=math.atan2(math.sin(yaw-lastStrafeYaw),math.cos(yaw-lastStrafeYaw))
                        if math.abs(delta)>0.0001 then strafeSide=delta>0 and 1 or -1 else strafeSide=-strafeSide end
                    else strafeSide=-strafeSide end
                    command.Move=Vector2.new((cy*nx-sy*nz)*strafeSide,(sy*nx+cy*nz)*strafeSide)
                elseif command.Move.Magnitude<0.001 then
                    strafeSide=-strafeSide;command.Move=Vector2.new(strafeSide,0)
                end
                lastStrafeYaw=yaw
            end
        else lastStrafeYaw=nil end
        if not movement.bhop or character.JumpInputDown~=true then lastGroundPulse=false;return end
        if type(command.Buttons)~="number" or type(character.OnGround)~="boolean" then return end
        local pulse=character.OnGround and not lastGroundPulse
        lastGroundPulse=pulse
        command.Buttons=pulse and bit32.bor(command.Buttons,1) or bit32.band(command.Buttons,bit32.bnot(1))
    end
    local function installBhop(class)
        local original = class and class.SampleInput
        if type(original)~="function" then return false end
        local function wrap(old, character, ...)
            local results=table.pack(old(character,...))
            if not movement.hookActive then return table.unpack(results,1,results.n) end
            movement.lastInputAt=os.clock()
            pcall(editCommand,character,results[1])
            if state.applyMovementPrediction then pcall(state.applyMovementPrediction,character,select(1,...),results[1]) end
            if state.applyAntiAim then
                local ok,err=pcall(state.applyAntiAim,character,results[1])
                if not ok and state.antiAim then state.antiAim.LastError=tostring(err);state.antiAim.LastErrorAt=os.clock() end
            end
            return table.unpack(results,1,results.n)
        end
        -- Shitaro использует замену поля. Сначала пробуем её, затем hookfunction.
        local replacement=function(character, ...) return wrap(original,character,...) end
        local ok=pcall(function() class.SampleInput=replacement end)
        if ok and class.SampleInput==replacement then
            movement.hookActive=true;movement.hookKind="field"
            movement.hookClass=class;movement.hookOriginal=original;movement.hookWrapper=replacement
            return true
        end
        local hookFn=hookfunction or replaceclosure
        if type(hookFn)=="function" then
            local previous
            local worked,old=pcall(function()return hookFn(original,function(character,...)return wrap(previous,character,...)end)end)
            if worked and type(old)=="function" then previous=old;movement.hookActive=true;movement.hookKind="closure";return true end
        end
        return false
    end
    task.spawn(function()
        while gui.Parent and not movement.bhopReady do
            local class=getModule("Classes","Character")
            if class then movement.bhopReady=installBhop(class) end
            refreshMovement()
            if not movement.bhopReady then task.wait(2) end
        end
    end)

    local hookCleanup
    hookCleanup=RunService.Heartbeat:Connect(function()
        if gui.Parent then return end
        movement.hookActive=false
        if movement.hookClass then
            pcall(function()if movement.hookClass.SampleInput==movement.hookWrapper then movement.hookClass.SampleInput=movement.hookOriginal end end)
        end
        hookCleanup:Disconnect()
    end)

    -- Ползунок расстояния камеры (5–18 studs).
    local slider=Instance.new("Frame")
    slider.Name, slider.BackgroundColor3, slider.BorderSizePixel = "ThirdDistanceSlider", Color3.fromRGB(16,26,19), 0
