            tw(veil,0.4,{BackgroundTransparency=1})
            tw(introScale,0.4,{Scale=introScale.Scale*1.08})
            task.wait(0.42)
        end)
        if not ok then warn("[Intro] "..tostring(err)) end
        finish()
    end)
end



state.gunMods={NoSpread=false,NoRecoil=false,SpreadReady=false,RecoilReady=false}
local hook = hookfunction or replaceclosure
if type(hook) ~= "function" or type(getgc) ~= "function" then
    state.message = "Нет hookfunction/getgc"
    refreshButton()
    warn("[Silent Aim] Executor не поддерживает hookfunction или getgc; остальные функции доступны")
end

local function lookupNetworkSend()
    local database = ReplicatedStorage:FindFirstChild("Database")
    local security = database and database:FindFirstChild("Security")
    local module = security and security:FindFirstChild("Remotes")
    if not module or not module:IsA("ModuleScript") then return nil end
    local ok, net = pcall(require, module)
    if not ok or type(net) ~= "table" then return nil end
    state.net = net
    local packet = net.Inventory and net.Inventory.ShootWeapon
    return packet and type(packet.Send) == "function" and packet.Send or nil
end

local function findBulletClass()
    local ok, objects = pcall(getgc, true)
    if not ok or type(objects) ~= "table" then return nil end
    for _, item in ipairs(objects) do
        if type(item) == "table"
            and type(rawget(item, "create")) == "function"
            and type(rawget(item, "getTrueSpread")) == "function"
            and type(rawget(item, "getSpreadForConfig")) == "function"
        then
            return item
        end
    end
    return nil
end

local function redirectCamera()
    if state.closeRangeShot then return end
    -- Перед расчётом выстрела возвращаем реальную точку глаза после third person.
    if state.restoreThirdEye then pcall(state.restoreThirdEye) end
    local target, camera = state.target, Workspace.CurrentCamera
    if not config.enabled or not target or not target.Parent or not camera then return end
    local ok, position = pcall(predictedPoint, target)
    if not ok then return end
    local origin = camera.CFrame.Position
    if (position - origin).Magnitude < 0.001 then return end
    if not state.savedView then
        state.camera = camera
        state.savedView = camera.CFrame
    end
    camera.CFrame = CFrame.lookAt(origin, position)
    state.redirected = true
end

-- No Spread stage 7 shares the same hooks as Silent Aim: no duplicate patching.
local spreadHooks={}
local function ensureSpread(bullet)
    if type(hook)~="function" or type(bullet)~="table" then return false end
    local count=0
    for _,name in ipairs({"getTrueSpread","getSpreadForConfig","getMovementSpreadForConfig","getBaseSpreadForConfig","getBaseSpread"}) do
        local fn=rawget(bullet,name)
        if type(fn)=="function" then
            if spreadHooks[fn] then count+=1 else
                local previous
                local ok,original=pcall(function()
                    return hook(fn,function(...)
                        local result=table.pack(previous(...))
                        if (state.redirected or state.gunMods.NoSpread) and type(result[1])=="number" then result[1]=0 end
                        return table.unpack(result,1,result.n)
                    end)
                end)
                if ok and type(original)=="function" then previous=original;spreadHooks[fn]=true;count+=1 end
            end
        end
    end
    state.gunMods.SpreadReady=count>0
    return count>0
end

local function install(bullet, sendFunction)
    -- Сначала ставим возврат вида; до полного завершения установки enabled=false.
    local previousSend
    local ok, result = pcall(function()
        return hook(sendFunction, function(...)
            restoreCamera()
            return previousSend(...)
        end)
    end)
    if not ok or type(result) ~= "function" then return false, "Не удалось перехватить Send" end
    previousSend = result

    local previousCreate
    ok, result = pcall(function()
        return hook(bullet.create, function(...)
            if config.enabled then pcall(redirectCamera) end
            local resultPack = table.pack(pcall(previousCreate, ...))
            if not resultPack[1] then
                restoreCamera()
                error(resultPack[2], 0)
            end
            return table.unpack(resultPack, 2, resultPack.n)
        end)
    end)
    if not ok or type(result) ~= "function" then return false, "Не удалось перехватить create" end
    previousCreate = result

    -- Force Origin: проверяем локальную точку и траекторию заново непосредственно при выстреле.
    if type(bullet._performRaycast) == "function" then
        local previousRay
        local good, old = pcall(function()
            return hook(bullet._performRaycast, function(...)
                local function calculate(...)
                local camera, target = Workspace.CurrentCamera, state.target
                if not (extras.forceOrigin and config.enabled and state.redirected and camera and target and target.Parent) then
                    return previousRay(...)
                end
                local oldView = camera.CFrame
                local okPoint, aim = pcall(predictedPoint, target)
                if not okPoint then return previousRay(...) end
                local origin = oldView.Position
                local blocked = Workspace:Raycast(origin, target.Position-origin, losParams)
                if not blocked then return previousRay(...) end
                local shifted = findShiftedOrigin(origin, target, camera)
                if not shifted or (aim-shifted).Magnitude < 0.01 then return previousRay(...) end
                if Workspace:Raycast(shifted, aim-shifted, losParams) then return previousRay(...) end
                local moved = pcall(function() camera.CFrame = CFrame.lookAt(shifted, aim) end)
                if not moved then return previousRay(...) end
                local resultPack = table.pack(pcall(previousRay, ...))
                pcall(function() camera.CFrame = oldView end)
                if not resultPack[1] then error(resultPack[2], 0) end
                return table.unpack(resultPack, 2, resultPack.n)
                end
                local resultPack=table.pack(calculate(...))
                local bulletObject=select(1,...)
                if state.noteLocalRay and type(bulletObject)=="table" then
                    local weapon=bulletObject.Weapon
                    if type(weapon)=="table" and weapon.Player==localPlayer then pcall(state.noteLocalRay,resultPack[1]) end
                end
                return table.unpack(resultPack,1,resultPack.n)
            end)
        end)
        if good and type(old) == "function" then previousRay = old; state.forceReady = true; state.hitReady=true end
    end
    state.forceFailed = not state.forceReady
    refreshExtras()

    ensureSpread(bullet)
    return true
end

task.spawn(function()
    -- Классы могут появиться только после загрузки матча/оружия.
    while gui.Parent do
        local okBullet, bullet = pcall(findBulletClass)
        local okSend, send = pcall(lookupNetworkSend)
        if okBullet and bullet and okSend and send then
            local installed, why = install(bullet, send)
            state.ready = installed
            state.message = installed and "Готово" or why
            refreshButton()
            if not installed then warn("[Silent Aim] " .. tostring(why)) end
            return
        end
        task.wait(0.5)
    end
    state.message = "Функции не найдены"
    refreshButton()
    warn("[Silent Aim] Не найдены bullet.create или Remotes.Inventory.ShootWeapon.Send; версия игры либо возможности executor могут отличаться")
end)



-- Повторный поиск контроллера камеры и таблицы пули после входа в матч.
do
    local hooked={}
    task.spawn(function()
        local lastWarn=0
        while gui.Parent do
            local gm=state.gunMods
            if gm.NoSpread and not gm.SpreadReady then
                local ok,bullet=pcall(findBulletClass)
                if ok and bullet then pcall(ensureSpread,bullet) end
            end
            if gm.NoRecoil and type(hook)=="function" then
                local camera=getModule("Controllers","CameraController")
                if type(camera)=="table" then
                    for _,name in ipairs({"weaponKick","setWeaponRecoil","getWeaponKickRotation"}) do
                        local fn=rawget(camera,name)
                        if type(fn)=="function" and not hooked[fn] then
                            local previous
                            local good,old=pcall(function()
                                return hook(fn,function(...)
                                    if gm.NoRecoil then
                                        if name=="getWeaponKickRotation" then return Vector3.zero end
                                        return
                                    end
                                    return previous(...)
                                end)
                            end)
                            if good and type(old)=="function" then previous=old;hooked[fn]=true end
                        end
                    end
                    local count=0
                    for _,name in ipairs({"weaponKick","setWeaponRecoil","getWeaponKickRotation"}) do
                        local fn=rawget(camera,name);if type(fn)=="function" and hooked[fn] then count+=1 end
                    end
                    gm.RecoilReady=count>0
                end
            end
            local now=os.clock()
            if now-lastWarn>15 and ((gm.NoSpread and not gm.SpreadReady) or (gm.NoRecoil and not gm.RecoilReady)) then
                lastWarn=now
                warn("[NOIR] No Recoil / No Spread: ищем методы игры; требуется поддержка executor")
            end
            task.wait(1.5)
        end
    end)
end

-- Дополнительный ESP из stage 7. Он независим от исходного Noir ESP.
do
    local LocalPlayer=localPlayer
    local osClock=os.clock
    local vector2New=Vector2.new
    local xDTaraZ={
        State={Alive=true},Panic={Panicked=false},GameLib={},Caps={Upvalues=type(getupvalues)=="function"},
        Config={SeeThrough={"Characters","Debris","ThirdPersonWeaponStash"},EspCacheMax=256,SoundSelfRange=6,
            GhostSnap=45,SoundMaxMarks=24,SoundColor=Color3.fromRGB(255,196,64)},
        Options={SoundEsp=false,SoundEspLife=3,EspMemory=0},
        Target={},Player={},Util={},
    }
    function xDTaraZ.Util.Decode(raw)
        local ok,data=pcall(game:GetService("HttpService").JSONDecode,game:GetService("HttpService"),raw)
        return ok and data or nil
    end
    function xDTaraZ.Util.Try(name,fn,...)
        local ok,result=pcall(fn,...)
        if not ok then warn("[NOIR / "..name.."] "..tostring(result)) end
        return ok,result
    end
    function xDTaraZ.Player.Character()
        local chars=Workspace:FindFirstChild("Characters")
        return (chars and chars:FindFirstChild(LocalPlayer.Name)) or LocalPlayer.Character
    end
    function xDTaraZ.Target.Candidates()
        local folder=Workspace:FindFirstChild("Characters");local result={}
        if folder then for _,m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") and m.Name~=LocalPlayer.Name then table.insert(result,m) end
        end end
        return result
    end
    function xDTaraZ.Target.Owner(model) return Players:FindFirstChild(model.Name) end
    function xDTaraZ.Target.TeamOf(model) return teamOf(model) end
    function xDTaraZ.Target.MyTeam() return LocalPlayer:GetAttribute("Team") or teamOf(xDTaraZ.Player.Character()) end
    function xDTaraZ.Target.FreeForAll() return string.find(tostring(Workspace:GetAttribute("Gamemode")),"Deathmatch",1,true)~=nil end
    function xDTaraZ.Target.IsEnemy(model)
        if tostring(model:GetAttribute("Dead"))=="true" then return false end
        if xDTaraZ.Target.FreeForAll() then return true end
        local my,other=xDTaraZ.Target.MyTeam(),teamOf(model)
        return my==nil or other==nil or my~=other
    end
    local sight=RaycastParams.new()
    sight.FilterType=Enum.RaycastFilterType.Exclude
    function xDTaraZ.Target.Visible(from,model,point)
        local skip={Workspace.CurrentCamera}
        if model then table.insert(skip,model) end
        for _,name in ipairs(xDTaraZ.Config.SeeThrough) do
            local folder=Workspace:FindFirstChild(name);if folder then table.insert(skip,folder) end
        end
        sight.FilterDescendantsInstances=skip
        return Workspace:Raycast(from,point-from,sight)==nil
    end
xDTaraZ.Esp = { Count = 0, Decoded = {}, CacheSize = 0, Ghosts = {}, Folder = nil }

---@return table?  JSON attribute decoded once per distinct raw string
function xDTaraZ.Esp.Attr(owner, key)
    local raw = owner:GetAttribute(key)
    if type(raw) ~= "string" then return nil end
    local esp = xDTaraZ.Esp
    if esp.Decoded[raw] == nil then
        esp.CacheSize += 1
        if esp.CacheSize > xDTaraZ.Config.EspCacheMax then table.clear(esp.Decoded) esp.CacheSize = 1 end
        esp.Decoded[raw] = xDTaraZ.Util.Decode(raw) or false
    end
    return esp.Decoded[raw] or nil
end

---@return string  " C4 Kit Helmet Scoped" style tags, "" when none
function xDTaraZ.Esp.Flags(owner)
    if not owner then return "" end
    local flags = {}
    local armor = xDTaraZ.Esp.Attr(owner, "Armor")
    local bomb = xDTaraZ.Esp.Attr(owner, "Slot5")
    if bomb and bomb.Weapon == "C4" then flags[#flags + 1] = "C4" end
    if owner:GetAttribute("HasDefuseKit") == true then table.insert(flags, "Kit") end
    if armor and type(armor.Type) == "string" and armor.Type:find("Helmet") then flags[#flags + 1] = "Helmet" end
    if owner:GetAttribute("IsSniperScoped") == true then flags[#flags + 1] = "Scoped" end
    return #flags > 0 and " " .. table.concat(flags, " ") or ""
end

---@return Model?  whatever aimbot, silent aim or ragebot is locked on
function xDTaraZ.Esp.Focus()
    return nil -- Не подменяем выбранную пользователем цветовую палитру.
end

---@return table  one lasting stand-in per player, so a body that blinks in and out of view never rebuilds its box
function xDTaraZ.Esp.Ghost(name)
    local esp = xDTaraZ.Esp
    local ghost = esp.Ghosts[name]
    if ghost and ghost.Model.Parent then return ghost end
    if not (esp.Folder and esp.Folder.Parent) then
        esp.Folder = Instance.new("Folder")
        esp.Folder.Name = "xDTaraZGhosts"
        esp.Folder.Parent = Workspace.CurrentCamera
    end
    local model = Instance.new("Model")
    model.Name = name
    local root = Instance.new("Part")
    root.Name, root.Size, root.Transparency = "HumanoidRootPart", Vector3.new(2, 2, 1), 1
    root.Anchored, root.CanCollide, root.CanQuery, root.CanTouch = true, false, false, false
    root.Parent = model
    model.PrimaryPart = root
    model.Parent = esp.Folder
    ghost = { Model = model, Root = root, Seen = 0, Heard = 0 }
    esp.Ghosts[name] = ghost
    return ghost
end

---@return table  xDTaraZ.Visuals row for one player, live body or last known spot
function xDTaraZ.Esp.Row(ghost, model, owner, mine, focus)
    local equipped = owner and xDTaraZ.Esp.Attr(owner, "CurrentEquipped")
    local label = owner and owner.DisplayName or ghost.Model.Name
    if equipped and equipped.Name then label = label .. " [" .. equipped.Name .. "]" end
    local live = model and model:FindFirstChild("HumanoidRootPart")
    if not live then label = label .. " ?" end
    return {
        Model = ghost.Model,
        Root = live or ghost.Root,
        Adornee = model or false,
        Name = label .. xDTaraZ.Esp.Flags(owner),
        Health = tonumber(owner and owner:GetAttribute("Health")) or tonumber(model and model:GetAttribute("Health")) or 100,
        MaxHealth = tonumber(model and model:GetAttribute("MaxHealth")) or 100,
        Friendly = ghost.Friendly,
        Color = model ~= nil and model == focus and xDTaraZ.Config.EspFocusColor or nil,
    }
end

---@return table[]  targets in the shape xDTaraZ.Visuals expects; bots count as enemies
function xDTaraZ.Esp.Targets()
    local esp, now = xDTaraZ.Esp, osClock()
    local list = {}
    if not Workspace.CurrentCamera then return list end
    local mine = xDTaraZ.Target.MyTeam()
    local ffa = xDTaraZ.Target.FreeForAll()
    local focus = xDTaraZ.Esp.Focus()
    if xDTaraZ.Options.SoundEsp or xDTaraZ.Options.EspMemory>0 then pcall(xDTaraZ.Sound.Install) end
    local live = {}
    for _, model in ipairs(xDTaraZ.Target.Candidates()) do
        if xDTaraZ.Esp.IsDead(model, xDTaraZ.Target.Owner(model)) then
            xDTaraZ.Esp.Forget(model.Name)
            continue
        end
        local hrp = model:FindFirstChild("HumanoidRootPart")
        if not hrp then continue end
        local ghost = esp.Ghost(model.Name)
        ghost.Root.CFrame, ghost.Seen = hrp.CFrame, now
        ghost.Friendly = not ffa and mine ~= nil and xDTaraZ.Target.TeamOf(model) == mine
        live[model.Name] = true
        list[#list + 1] = esp.Row(ghost, model, xDTaraZ.Target.Owner(model), mine, focus)
    end
    local memory = xDTaraZ.Options.EspMemory
    for name, ghost in pairs(esp.Ghosts) do
        if live[name] then continue end
        local owner = Players:FindFirstChild(name)
        if owner and xDTaraZ.Esp.IsDead(nil, owner) then
            xDTaraZ.Esp.Forget(name)
            continue
        end
        local gone = not ghost.Model.Parent or (not owner and now - ghost.Seen > memory)
        if gone or now - math.max(ghost.Seen, ghost.Heard) > memory then
            if gone and not owner then
                ghost.Model:Destroy()
                esp.Ghosts[name] = nil
            end
            continue
        end
        list[#list + 1] = esp.Row(ghost, nil, owner, mine, focus)
    end
    esp.Count = #list
    return list
end

---@return boolean  true once a player or bot is dead, by body flag or 0 health
function xDTaraZ.Esp.IsDead(model, owner)
    if model and (tostring(model:GetAttribute("Dead")) == "true" or (tonumber(model:GetAttribute("Health")) or 1) <= 0) then return true end
    if owner and (owner:GetAttribute("Dead") == true or (tonumber(owner:GetAttribute("Health")) or 1) <= 0) then return true end
    return false
end

---Drops the remembered spot of someone who died, so no box stays where they fell.
function xDTaraZ.Esp.Forget(name)
    local ghost = xDTaraZ.Esp.Ghosts[name]
    if ghost then ghost.Seen, ghost.Heard = 0, 0 end
end

---Moves the stand-in of the hidden enemy closest to a footstep or shot, so hidden players keep a box.
function xDTaraZ.Esp.Hear(pos, weapon)
    local esp, now = xDTaraZ.Esp, osClock()
    local best, bestDist = nil, xDTaraZ.Config.GhostSnap
    for name, ghost in pairs(esp.Ghosts) do
        if ghost.Friendly or now - ghost.Seen < 0.3 then continue end
        local owner = Players:FindFirstChild(name)
        local equipped = owner and xDTaraZ.Esp.Attr(owner, "CurrentEquipped")
        if weapon and equipped and equipped.Name and equipped.Name ~= weapon then continue end
        local dist = (ghost.Root.Position - pos).Magnitude
        if dist < bestDist then best, bestDist = ghost, dist end
    end
    if not best then return end
    best.Root.CFrame = CFrame.new(pos + Vector3.new(0, 2.5, 0))
    best.Heard = now
end

xDTaraZ.Sound = { Marks = {}, Entry = nil, Original = nil, Folder = nil }

---Hooks into the game's own sound listener: every footstep and shot of every player arrives with its position, even behind walls.
function xDTaraZ.Sound.Install()
    local sound = xDTaraZ.Sound
    if sound.Entry then return true end
    local net = xDTaraZ.GameLib.Net
    local packet = net and net.Sound and net.Sound.ReplicateSound
    if not (packet and xDTaraZ.Caps.Upvalues) then return false end
    local ok, listeners = pcall(function() return getupvalues(packet.Listen)[1] end)
    if not ok or type(listeners) ~= "table" then return false end
    for _, entry in ipairs(listeners) do
        if type(entry) == "table" and type(entry.callback) == "function" then
            local previous=entry.callback
            local wrapped
            wrapped=function(info, ...)
                if xDTaraZ.Options.SoundEsp or xDTaraZ.Options.EspMemory>0 then
                    state.enqueueGameEvent(xDTaraZ.Sound.Heard,info,function()return xDTaraZ.Sound.Wrapper==wrapped end)
                end
                return previous(info, ...)
            end
            local changed=pcall(function() entry.callback=wrapped end)
            if not changed or entry.callback~=wrapped then return false end
            sound.Entry, sound.Original, sound.Wrapper = entry, previous, wrapped
            return true
        end
    end
    return false
end

function xDTaraZ.Sound.Uninstall()
    local sound = xDTaraZ.Sound
    if sound.Entry and sound.Entry.callback == sound.Wrapper then
        pcall(function() sound.Entry.callback = sound.Original end)
    end
    sound.Entry, sound.Original, sound.Wrapper = nil, nil, nil
    for _, mark in ipairs(sound.Marks) do mark.Gui:Destroy() end
    table.clear(sound.Marks)
end

---@return boolean  true when the sound came from you or a teammate you can see
function xDTaraZ.Sound.Friendly(pos)
    local range = xDTaraZ.Config.SoundSelfRange
    local me = xDTaraZ.Player.Character()
    if me and (me:GetPivot().Position - pos).Magnitude < range then return true end
    if xDTaraZ.Target.FreeForAll() then return false end
    for _, model in ipairs(xDTaraZ.Target.Candidates()) do
        if not xDTaraZ.Target.IsEnemy(model) and (model:GetPivot().Position - pos).Magnitude < range then return true end
    end
    return false
end

function xDTaraZ.Sound.Heard(info)
    if type(info) ~= "table" or typeof(info.Position) ~= "Vector3" then return end
    local floor = info.Class == "FloorSounds"
    if not floor and info.Name ~= "Shoot" then return end
    if xDTaraZ.Sound.Friendly(info.Position) then return end
    xDTaraZ.Esp.Hear(info.Position, not floor and tostring(info.Class) or nil)
    if xDTaraZ.Options.SoundEsp then xDTaraZ.Sound.Mark(info.Position, floor and "Steps" or tostring(info.Class)) end
end

function xDTaraZ.Sound.Mark(pos, label)
    local sound = xDTaraZ.Sound
    if not (sound.Folder and sound.Folder.Parent) then
        sound.Folder = Instance.new("Folder")
        sound.Folder.Name = "xDTaraZSounds"
        sound.Folder.Parent = Workspace.Terrain
    end
    if #sound.Marks >= xDTaraZ.Config.SoundMaxMarks then
        table.remove(sound.Marks, 1).Gui:Destroy()
    end
    local holder = Instance.new("Attachment")
    holder.Parent = Workspace.Terrain
    holder.WorldPosition = pos
    local gui = Instance.new("BillboardGui")
    gui.AlwaysOnTop, gui.Size, gui.LightInfluence = true, UDim2.fromOffset(120, 34), 0
    local text = Instance.new("TextLabel")
    text.BackgroundTransparency, text.Size, text.Font, text.TextSize = 1, UDim2.fromScale(1, 1), Enum.Font.GothamBold, 13
    text.TextColor3, text.TextStrokeTransparency = xDTaraZ.Config.SoundColor, 0.3
    text.Parent = gui
    gui.Parent = holder
    holder.Parent = Workspace.Terrain
    gui.Adornee = holder
    sound.Marks[#sound.Marks + 1] = { Gui = holder, Text = text, Label = label, Born = osClock() }
end

---Fades markers and keeps their distance fresh.
function xDTaraZ.Sound.Step()
    local sound, life = xDTaraZ.Sound, xDTaraZ.Options.SoundEspLife
    local cam = Workspace.CurrentCamera
    for index = #sound.Marks, 1, -1 do
        local mark = sound.Marks[index]
        local age = osClock() - mark.Born
        if age > life or not xDTaraZ.Options.SoundEsp then
            mark.Gui:Destroy()
            table.remove(sound.Marks, index)
        else
            local dist = cam and math.floor((mark.Gui.WorldPosition - cam.CFrame.Position).Magnitude) or 0
            mark.Text.Text = ("%s\n%dm"):format(mark.Label, dist)
            mark.Text.TextTransparency = age / life * 0.8
        end
    end
end

xDTaraZ.Visuals = {
    Settings = {
        Enabled = false,
        Box = false,
        BoxStyle = "Full",
        BoxFill = false,
        Name = false,
        Health = false,
        HealthText = false,
        Distance = false,
        Tracer = false,
        TracerOrigin = "Bottom",
        HeadDot = false,
        Chams = false,
        Arrows = false,
        Radar = false,
        RadarRange = 250,
        RadarSize = 180,
        TeamCheck = true,
        MaxDistance = 2000,
        TextSize = 13,
        EnemyColor = Color3.fromRGB(232, 88, 76),
        FriendColor = Color3.fromRGB(96, 196, 120),
    },
    Entries = {},
    Targets = {},
    LastScan = 0,
    ScanInterval = 0.2,
    Radar = { Dots = {} },
}

function xDTaraZ.Visuals.New(class, props)
    local object = Instance.new(class)
    local parent = props.Parent
    props.Parent = nil
    for key, value in pairs(props) do object[key] = value end
    if parent then object.Parent = parent end
    return object
end

function xDTaraZ.Visuals.EnsureGui()
    local visuals = xDTaraZ.Visuals
    if visuals.Gui and visuals.Gui.Parent then return visuals.Gui end
    local screen = visuals.New("ScreenGui", { Name = "CybrionVisuals", IgnoreGuiInset = true, ResetOnSpawn = false, DisplayOrder = 5, ZIndexBehavior = Enum.ZIndexBehavior.Sibling })
    local function Mount(parent) screen.Parent = parent end
    local okHui, hui = pcall(gethui)
    local mounted = okHui and hui ~= nil and pcall(Mount, hui)
    if not mounted then mounted = pcall(Mount, game:GetService("CoreGui")) end
    if not mounted then Mount(LocalPlayer:FindFirstChildOfClass("PlayerGui")) end
    visuals.Gui = screen
    return screen
end

function xDTaraZ.Visuals.Label(parent, alignY)
    return xDTaraZ.Visuals.New("TextLabel", {
        BackgroundTransparency = 1,
        AnchorPoint = Vector2.new(0.5, alignY),
        Size = UDim2.fromOffset(200, 16),
        Font = Enum.Font.GothamBold,
        TextColor3 = Color3.new(1, 1, 1),
        TextStrokeTransparency = 0.35,
        Visible = false,
        Parent = parent,
    })
end

---@return table  reusable GUI pieces for one ESP target
function xDTaraZ.Visuals.BuildEntry(parent)
    local new = xDTaraZ.Visuals.New
    local entry = {}
    entry.Box = new("Frame", { BackgroundTransparency = 1, Visible = false, Parent = parent })
    entry.BoxStroke = new("UIStroke", { Thickness = 1.5, Parent = entry.Box })
    entry.BoxOutline = new("Frame", { BackgroundTransparency = 1, Position = UDim2.fromOffset(-1, -1), Size = UDim2.new(1, 2, 1, 2), Parent = entry.Box })
    new("UIStroke", { Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.3, Parent = entry.BoxOutline })
    entry.Corners = {}
    for index = 1, 8 do
        entry.Corners[index] = new("Frame", { BorderSizePixel = 0, Visible = false, Parent = parent })
    end
    entry.HealthBack = new("Frame", { BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35, BorderSizePixel = 0, Visible = false, Parent = parent })
    entry.HealthFill = new("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), BorderSizePixel = 0, Parent = entry.HealthBack })
    entry.HealthText = xDTaraZ.Visuals.Label(parent, 0.5)
    entry.Name = xDTaraZ.Visuals.Label(parent, 1)
    entry.Distance = xDTaraZ.Visuals.Label(parent, 0)
    entry.Tracer = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0, BackgroundColor3 = Color3.new(1, 1, 1), Visible = false, Parent = parent })
    entry.Dot = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(6, 6), BorderSizePixel = 0, Visible = false, Parent = parent })
    new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = entry.Dot })
    entry.Arrow = xDTaraZ.Visuals.Label(parent, 0.5)
    entry.Arrow.Text = "▲"
    entry.Arrow.Size = UDim2.fromOffset(20, 20)
    return entry
end

function xDTaraZ.Visuals.HideEntry(entry)
    entry.Box.Visible = false
    for _, corner in ipairs(entry.Corners) do corner.Visible = false end
    entry.HealthBack.Visible, entry.HealthText.Visible = false, false
    entry.Name.Visible, entry.Distance.Visible = false, false
    entry.Tracer.Visible, entry.Dot.Visible, entry.Arrow.Visible = false, false, false
    if entry.Highlight then entry.Highlight.Enabled = false end
end

function xDTaraZ.Visuals.DestroyEntry(entry)
    for _, key in ipairs({ "Box", "HealthBack", "HealthText", "Name", "Distance", "Tracer", "Dot", "Arrow", "Arrow360", "Highlight" }) do
        if entry[key] then pcall(entry[key].Destroy, entry[key]) end
    end
    for _, corner in ipairs(entry.Corners) do pcall(corner.Destroy, corner) end
end

function xDTaraZ.Visuals.SetLine(line, from, to, thickness)
    local delta = to - from
    line.Position = UDim2.fromOffset((from.X + to.X) / 2, (from.Y + to.Y) / 2)
    line.Size = UDim2.fromOffset(delta.Magnitude, thickness)
    line.Rotation = math.deg(math.atan2(delta.Y, delta.X))
    line.Visible = true
end

---Places the 2D box, bars and labels from a screen rect.
function xDTaraZ.Visuals.Layout(entry, x, y, w, h, info, color, origin)
    local settings = xDTaraZ.Visuals.Settings
    local full = settings.Box and settings.BoxStyle ~= "Corner"
    entry.Box.Visible = settings.Box and (full or settings.BoxFill)
    entry.BoxStroke.Enabled = full
    entry.BoxOutline.Visible = full
    if entry.Box.Visible then
        entry.Box.Position, entry.Box.Size = UDim2.fromOffset(x, y), UDim2.fromOffset(w, h)
        entry.BoxStroke.Color = color
        entry.Box.BackgroundTransparency = settings.BoxFill and 0.82 or 1
        entry.Box.BackgroundColor3 = color
    end

    local corner = settings.Box and settings.BoxStyle == "Corner"
    local cw, ch = math.max(w / 4, 3), math.max(h / 5, 3)
    local spots = {
        { x, y, cw, 2 }, { x, y, 2, ch }, { x + w - cw, y, cw, 2 }, { x + w - 2, y, 2, ch },
        { x, y + h - 2, cw, 2 }, { x, y + h - ch, 2, ch }, { x + w - cw, y + h - 2, cw, 2 }, { x + w - 2, y + h - ch, 2, ch },
    }
    for index, piece in ipairs(entry.Corners) do
        piece.Visible = corner
        if corner then
            local spot = spots[index]
            piece.Position, piece.Size, piece.BackgroundColor3 = UDim2.fromOffset(spot[1], spot[2]), UDim2.fromOffset(spot[3], spot[4]), color
        end
    end

    local ratio = math.clamp((info.Health or 0) / math.max(info.MaxHealth or 100, 1), 0, 1)
    entry.HealthBack.Visible = settings.Health
    if settings.Health then
        entry.HealthBack.Position, entry.HealthBack.Size = UDim2.fromOffset(x - 6, y), UDim2.fromOffset(3, h)
        entry.HealthFill.Size = UDim2.fromScale(1, ratio)
        entry.HealthFill.BackgroundColor3 = Color3.fromRGB(232, 88, 76):Lerp(Color3.fromRGB(96, 214, 110), ratio)
    end
    entry.HealthText.Visible = settings.HealthText
    if settings.HealthText then
        local hp = math.floor(info.Health or 0)
        if entry.LastHp ~= hp then
            entry.LastHp = hp
            entry.HealthText.Text = tostring(hp)
        end
        entry.HealthText.TextSize = settings.TextSize - 2
        entry.HealthText.Position = UDim2.fromOffset(x - 20, y + h * (1 - ratio))
    end

    entry.Name.Visible = settings.Name
    if settings.Name then
        local name = info.Name or ""
        if entry.LastName ~= name then
            entry.LastName = name
            entry.Name.Text = name
        end
        entry.Name.TextSize, entry.Name.TextColor3 = settings.TextSize, color
        entry.Name.Position = UDim2.fromOffset(x + w / 2, y - 2)
    end
    entry.Distance.Visible = settings.Distance and info.Distance ~= nil
    if entry.Distance.Visible then
        local distance = math.floor(info.Distance)
        if entry.LastDist ~= distance then
            entry.LastDist = distance
            entry.Distance.Text = distance .. "m"
        end
        entry.Distance.TextSize = settings.TextSize - 1
        entry.Distance.Position = UDim2.fromOffset(x + w / 2, y + h + 2)
    end

    entry.Dot.Visible = settings.HeadDot
    if settings.HeadDot then
        entry.Dot.Position, entry.Dot.BackgroundColor3 = UDim2.fromOffset(x + w / 2, y + h * 0.1), color
    end

    if settings.Tracer and origin then
        entry.Tracer.BackgroundColor3 = color
        xDTaraZ.Visuals.SetLine(entry.Tracer, origin, Vector2.new(x + w / 2, y + h), 1.5)
    else
        entry.Tracer.Visible = false
    end
end

function xDTaraZ.Visuals.TracerOrigin(viewport)
    local mode = xDTaraZ.Visuals.Settings.TracerOrigin
    if mode == "Center" then return viewport / 2 end
    if mode == "Mouse" then return UserInputService:GetMouseLocation() end
    return Vector2.new(viewport.X / 2, viewport.Y)
end

function xDTaraZ.Visuals.Chams(entry, model, color, on)
    if not on then
        if entry.Highlight then entry.Highlight.Enabled = false end
        return
    end
    if not entry.Highlight then
        entry.Highlight = xDTaraZ.Visuals.New("Highlight", { DepthMode = Enum.HighlightDepthMode.AlwaysOnTop, FillTransparency = 0.55, OutlineTransparency = 0, Parent = xDTaraZ.Visuals.EnsureGui() })
    end
    entry.Highlight.Adornee = model
    entry.Highlight.FillColor, entry.Highlight.OutlineColor = color, color
    entry.Highlight.Enabled = true
end

function xDTaraZ.Visuals.Arrow(entry, screen, viewport, color)
    if xDTaraZ.Panic and xDTaraZ.Panic.Panicked then entry.Arrow.Visible = false return end
    local center = viewport / 2
    local dir = Vector2.new(screen.X, screen.Y) - center
    if screen.Z < 0 then dir = -dir end
    if dir.Magnitude < 1 then return end
    local unit = dir.Unit
    local radius = math.min(viewport.X, viewport.Y) / 2 - 40
    local pos = center + unit * radius
    entry.Arrow.Position = UDim2.fromOffset(pos.X, pos.Y)
    entry.Arrow.Rotation = math.deg(math.atan2(unit.Y, unit.X)) + 90
    entry.Arrow.TextColor3 = color
    entry.Arrow.TextSize = 18
    entry.Arrow.Visible = true
end

function xDTaraZ.Visuals.Scan()
    local visuals = xDTaraZ.Visuals
    local now = osClock()
    if now - visuals.LastScan < visuals.ScanInterval then return end
    visuals.LastScan = now
    local ok, list = pcall(xDTaraZ.Esp.Targets)
    visuals.Targets = ok and type(list) == "table" and list or {}
end

function xDTaraZ.Visuals.Render()
    local visuals = xDTaraZ.Visuals
    local settings = visuals.Settings
    if not settings.Enabled then return end
    visuals.Scan()
    local cam = Workspace.CurrentCamera
    if not cam then return end
    local gui = visuals.EnsureGui()
    local viewport = cam.ViewportSize
    local origin = visuals.TracerOrigin(viewport)
    local camPos = cam.CFrame.Position
    local seen = {}

    for _, info in ipairs(visuals.Targets) do
        local model = info.Model
        if typeof(model) ~= "Instance" or not model.Parent then continue end
        if settings.TeamCheck and info.Friendly then continue end
        local root = info.Root or model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
        if not root then continue end
        local distance = (root.Position - camPos).Magnitude
        if distance > settings.MaxDistance then continue end

        seen[model] = true
        local entry = visuals.Entries[model]
        if not entry then
            entry = visuals.BuildEntry(gui)
            visuals.Entries[model] = entry
        end
        local color = info.Color or (info.Friendly and settings.FriendColor or settings.EnemyColor)
        visuals.Chams(entry, info.Adornee or model, color, settings.Chams and (info.Adornee ~= false))

        local top, onTop = cam:WorldToViewportPoint(root.Position + Vector3.new(0, 3, 0))
        local bottom, onBottom = cam:WorldToViewportPoint(root.Position - Vector3.new(0, 3.5, 0))
        if not (onTop and onBottom) then
            visuals.HideEntry(entry)
            if settings.Chams and entry.Highlight and info.Adornee ~= false then entry.Highlight.Enabled = true end
            if settings.Arrows then visuals.Arrow(entry, cam:WorldToViewportPoint(root.Position), viewport, color) end
            continue
        end
        entry.Arrow.Visible = false
        local h = math.max(bottom.Y - top.Y, 4)
        local w = h * 0.55
        info.Distance = distance
        visuals.Layout(entry, top.X - w / 2, top.Y, w, h, info, color, origin)
    end

    for model, entry in pairs(visuals.Entries) do
        if not seen[model] then
            if model.Parent then
                visuals.HideEntry(entry)
            else
                visuals.DestroyEntry(entry)
                visuals.Entries[model] = nil
            end
        end
    end
end

function xDTaraZ.Visuals.ClearAll()
    local visuals = xDTaraZ.Visuals
    for model, entry in pairs(visuals.Entries) do
        visuals.DestroyEntry(entry)
        visuals.Entries[model] = nil
    end
end

local VS=xDTaraZ.Visuals.Settings
VS.HeadDotSize      = 8
VS.HeadDotVisCheck  = true
VS.HeadDot360       = false
VS.Dot360Color      = Color3.fromRGB(255, 75, 85)
VS.Dot360Size       = 22
VS.Dot360Radius     = 150

-- ─────────────────────────────────────────────────────────────────────────
--  SECTION 2 — 360° arrow helper (creates one label per ESP entry lazily)
-- ─────────────────────────────────────────────────────────────────────────

function xDTaraZ.Visuals.Draw360Arrow(entry, worldPos, camCF, center)
    if xDTaraZ.Panic and xDTaraZ.Panic.Panicked then
        if entry.Arrow360 then entry.Arrow360.Visible = false end
        return
    end
    local settings = xDTaraZ.Visuals.Settings
    if not entry.Arrow360 then
        local gui = xDTaraZ.Visuals.EnsureGui()
        entry.Arrow360 = xDTaraZ.Visuals.New("TextLabel", {
            BackgroundTransparency  = 1,
            Text                    = "▲",
            AnchorPoint             = Vector2.new(0.5, 0.5),
            Size                    = UDim2.fromOffset(24, 24),
            Font                    = Enum.Font.GothamBold,
            TextStrokeTransparency  = 0.1,
            Visible                 = false,
            ZIndex                  = 16,
            Parent                  = gui,
        })
    end
    local lbl = entry.Arrow360
    local dX  = worldPos.X - camCF.Position.X
    local dZ  = worldPos.Z - camCF.Position.Z
    if math.abs(dX) <= 0.01 and math.abs(dZ) <= 0.01 then
        lbl.Visible = false
        return
    end
    local flat  = Vector3.new(dX, 0, dZ).Unit
    local angle = math.atan2(flat:Dot(camCF.RightVector), flat:Dot(camCF.LookVector))
    local r     = settings.Dot360Radius or 150
    lbl.Position             = UDim2.fromOffset(
        center.X + math.sin(angle) * r,
        center.Y - math.cos(angle) * r
    )
    lbl.Rotation             = math.deg(angle)
    lbl.TextColor3           = settings.Dot360Color or Color3.fromRGB(255, 75, 85)
    lbl.TextSize             = settings.Dot360Size  or 22
    lbl.Visible              = true
end

-- ─────────────────────────────────────────────────────────────────────────
--  SECTION 3 — Replace Visuals.Render
--              • head dot uses real WorldToViewportPoint(head.Position)
--              • HeadDotVisCheck wired to xDTaraZ.Target.Visible
--              • HeadDotSize respected
--              • 360° arrows drawn for every tracked enemy (on- or off-screen)
-- ─────────────────────────────────────────────────────────────────────────

xDTaraZ.Visuals.Render = function()
    local visuals  = xDTaraZ.Visuals
    local settings = visuals.Settings
    if not settings.Enabled then return end
    visuals.Scan()
    local cam     = Workspace.CurrentCamera
    if not cam then return end
    local gui      = visuals.EnsureGui()
    local viewport = cam.ViewportSize
    local center   = viewport / 2
    local origin   = visuals.TracerOrigin(viewport)
    local camPos   = cam.CFrame.Position
    local camCF    = cam.CFrame
    local seen     = {}

    for _, info in ipairs(visuals.Targets) do
        local model = info.Model
        if typeof(model) ~= "Instance" or not model.Parent then continue end
        if settings.TeamCheck and info.Friendly then continue end
        local root = info.Root or model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
        if not root then continue end
        local distance = (root.Position - camPos).Magnitude
        if distance > settings.MaxDistance then continue end

        seen[model] = true
        local entry = visuals.Entries[model]
        if not entry then
            entry = visuals.BuildEntry(gui)
            visuals.Entries[model] = entry
        end
        local color = info.Color or (info.Friendly and settings.FriendColor or settings.EnemyColor)
        visuals.Chams(entry, info.Adornee or model, color, settings.Chams and (info.Adornee ~= false))

        local top,    onTop    = cam:WorldToViewportPoint(root.Position + Vector3.new(0, 3,   0))
        local bottom, onBottom = cam:WorldToViewportPoint(root.Position - Vector3.new(0, 3.5, 0))

        -- ── off-screen ──────────────────────────────────────────────────
        if not (onTop and onBottom) then
            visuals.HideEntry(entry)
            if settings.Chams and entry.Highlight and info.Adornee ~= false then
                entry.Highlight.Enabled = true
            end
            if settings.Arrows then
                visuals.Arrow(entry, cam:WorldToViewportPoint(root.Position), viewport, color)
            end
            if settings.HeadDot360 then
                xDTaraZ.Visuals.Draw360Arrow(entry, root.Position, camCF, center)
            elseif entry.Arrow360 then
                entry.Arrow360.Visible = false
            end
            continue
        end

        -- ── on-screen ───────────────────────────────────────────────────
        entry.Arrow.Visible = false
        local h = math.max(bottom.Y - top.Y, 4)
        local w = h * 0.55
        info.Distance = distance
        visuals.Layout(entry, top.X - w / 2, top.Y, w, h, info, color, origin)

        -- head dot: same targeting pipeline as box / healthbar / name ESP.
        -- info.Model is always the ghost stand-in (fake; no Head child).
        -- info.Adornee = real character Model, or false for ghost-only entries.
        -- info.Root    = live HumanoidRootPart or ghost root (what the box uses).
        if settings.HeadDot then
            local realModel = info.Adornee          -- real char Model, or false
            local head      = realModel and realModel:FindFirstChild("Head")
            -- ghost-only: estimate head ~1.5 studs above root (same root the box draws from)
            local headPos   = head and head.Position or (root.Position + Vector3.new(0, 1.5, 0))
            local hs, hOn   = cam:WorldToViewportPoint(headPos)
            if hOn and hs.Z > 0 then
                local show = true
                if settings.HeadDotVisCheck then
                    -- filter the real model, not the invisible ghost stand-in in CurrentCamera
                    show = xDTaraZ.Target.Visible(camPos, realModel or model, headPos)
                end
                if show then
                    local sz = math.max(settings.HeadDotSize or 8, 2)
                    entry.Dot.Position         = UDim2.fromOffset(hs.X, hs.Y)
                    entry.Dot.Size             = UDim2.fromOffset(sz, sz)
                    entry.Dot.BackgroundColor3 = color
                    entry.Dot.Visible          = true
                else
                    entry.Dot.Visible          = false
                end
            else
                entry.Dot.Visible = false
            end
        end

        -- 360° marker for on-screen enemies
        if settings.HeadDot360 then
            xDTaraZ.Visuals.Draw360Arrow(entry, root.Position, camCF, center)
        elseif entry.Arrow360 then
            entry.Arrow360.Visible = false
        end
    end

    -- clean up entries whose models are gone
    for model, entry in pairs(visuals.Entries) do
        if not seen[model] then
            if entry.Arrow360 then
                if model.Parent then
                    entry.Arrow360.Visible = false
                else
                    pcall(entry.Arrow360.Destroy, entry.Arrow360)
                end
            end
            if model.Parent then
                visuals.HideEntry(entry)
            else
                visuals.DestroyEntry(entry)
                visuals.Entries[model] = nil
            end
        end
    end
end

-- ─────────────────────────────────────────────────────────────────────────
local FPSettings = {
    Enabled          = false,
    TeamCheck        = true,
    Method           = "3D Box Adornment",
    Color            = Color3.fromRGB(255, 50, 50),
    Lifetime         = 5,
    StepDistance     = 2.5,
    Size             = 1.0,
    MaxDistance      = 1500,
    IndicatorEnabled = false,
    IndicatorColor   = Color3.fromRGB(255, 50, 50),
    IndicatorSize    = 22,
    IndicatorRadius  = 150,
}

local FPGui_ref, FPOverlay_ref

local function GetFPOverlay()
    if FPGui_ref and FPGui_ref.Parent then return FPOverlay_ref end
    local gui = Instance.new("ScreenGui")
    gui.Name              = "CybrionFootprintESP"
    gui.ResetOnSpawn      = false
    gui.IgnoreGuiInset    = true
    gui.DisplayOrder      = 6
    gui.ZIndexBehavior    = Enum.ZIndexBehavior.Sibling
    local ok, hui = pcall(gethui)
    local mounted = ok and hui and pcall(function() gui.Parent = hui end)
    if not mounted then mounted = pcall(function() gui.Parent = game:GetService("CoreGui") end) end
    if not mounted then gui.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") end
    local overlay = Instance.new("Frame")
    overlay.Name                 = "FPOverlay"
    overlay.BackgroundTransparency = 1
    overlay.Size                 = UDim2.fromScale(1, 1)
    overlay.Parent               = gui
    FPGui_ref, FPOverlay_ref = gui, overlay
    return overlay
end

local function FPNew(cls, props, parent)
    local obj = Instance.new(cls)
    for k, v in pairs(props or {}) do obj[k] = v end
    if parent then obj.Parent = parent end
    return obj
end

-- resolve char from Workspace.Characters first (Z86 canonical), fall back to player.Character
local function FPGetChar(player)
    local chars = Workspace:FindFirstChild("Characters")
    return (chars and chars:FindFirstChild(player.Name)) or player.Character
end

local function FPIsEnemy(player)
    local char = FPGetChar(player)
    if not char then return false end
    -- dead check: skip dead players
    if tostring(char:GetAttribute("Dead")) == "true" then return false end
    -- team check with "uncertain = show" fallback, matching OG IsEnemyForVisuals.
    -- xDTaraZ.Target.IsEnemy has "uncertain = not enemy" (aimbot safe-default) which
    -- silently skips everyone when MyTeam() returns nil — wrong for footstep ESP.
    if xDTaraZ.Target.FreeForAll() then return true end
    local mine = xDTaraZ.Target.MyTeam()
    if mine == nil then return true end          -- can't resolve teams → show footprint
    local theirs = xDTaraZ.Target.TeamOf(char)
    if theirs == nil then return true end        -- can't resolve their team → show footprint
    return theirs ~= mine
end

local function FPGetRoot(char)
    if not char then return nil end
    return char:FindFirstChild("HumanoidRootPart")
        or char:FindFirstChild("UpperTorso")
        or char:FindFirstChild("Torso")
        or char.PrimaryPart
end

local FP_Footprints2D = {}
local FP_Footprints3D = {}
local FP_LastPos      = {}
local FP_LatestStep   = {}
local FP_IndCache     = {}

local function FP_GetIndicator(player)
    if not FP_IndCache[player] then
        FP_IndCache[player] = FPNew("TextLabel", {
            BackgroundTransparency  = 1,
            Text                    = "▲",
            TextColor3              = FPSettings.IndicatorColor,
            TextStrokeTransparency  = 0.1,
            TextSize                = FPSettings.IndicatorSize,
            Font                    = Enum.Font.GothamBold,
            AnchorPoint             = Vector2.new(0.5, 0.5),
            Visible                 = false,
            ZIndex                  = 14,
        }, GetFPOverlay())
    end
    return FP_IndCache[player]
end

-- panic: hard-clear every footstep 360° indicator arrow
xDTaraZ.Panic.ClearFootstepArrows = function()
    FPSettings.IndicatorEnabled = false
    for player, ind in pairs(FP_IndCache) do
        if ind then pcall(ind.Destroy, ind) end
        FP_IndCache[player] = nil
    end
    table.clear(FP_LatestStep)
end

local function FP_ClearAll()
    for _, fp in ipairs(FP_Footprints2D) do
        if fp.Frame then fp.Frame:Destroy() end
    end
    table.clear(FP_Footprints2D)
    for _,part in ipairs(FP_Footprints3D) do pcall(function() part:Destroy() end) end
    table.clear(FP_Footprints3D)
    table.clear(FP_LatestStep)
    table.clear(FP_LastPos)      -- OG clears lastPositions on disable; stale coords from a
                                 -- prior session land the first new step at the wrong place
    for _, ind in pairs(FP_IndCache) do
        if ind then ind.Visible = false end
    end
end

-- ── 2D footprint ────────────────────────────────────────────
local function FP_Spawn2D(pos)
    local overlay = GetFPOverlay()
    local frame = FPNew("Frame", {
        AnchorPoint      = Vector2.new(0.5, 0.5),
        BackgroundColor3 = FPSettings.Color,
        BorderSizePixel  = 0,
        Visible          = false,
        ZIndex           = 5,
    }, overlay)
    FPNew("UIStroke", { Color = FPSettings.Color, Transparency = 0.3, Thickness = 1.5, Parent = frame })
    FPNew("UICorner", { CornerRadius = UDim.new(0, 3), Parent = frame })
    if #FP_Footprints2D>=160 then
        local old=table.remove(FP_Footprints2D,1)
        if old and old.Frame then old.Frame:Destroy() end
    end
    table.insert(FP_Footprints2D, {
        Position  = pos,
        SpawnTime = tick(),
        Lifetime  = FPSettings.Lifetime,
        Size      = FPSettings.Size,
        Color     = FPSettings.Color,
        Frame     = frame,
    })
end

local function FP_Update2D()
    local now    = tick()
    local Camera = Workspace.CurrentCamera
    if not Camera then return end
    for i = #FP_Footprints2D, 1, -1 do
        local fp  = FP_Footprints2D[i]
        local age = now - fp.SpawnTime
        if age >= fp.Lifetime or not FPSettings.Enabled or FPSettings.Method ~= "2D ScreenGui Overlay" then
            if fp.Frame then fp.Frame:Destroy() end
            table.remove(FP_Footprints2D, i)
        else
            local sp, onS = Camera:WorldToViewportPoint(fp.Position)
            if onS and sp.Z > 0 and sp.Z <= FPSettings.MaxDistance then
                local alpha     = 1 - (age / fp.Lifetime)
                local distScale = math.clamp(450 / sp.Z, 6, 35)
                fp.Frame.Position               = UDim2.fromOffset(sp.X, sp.Y)
                fp.Frame.Size                   = UDim2.fromOffset(distScale * 0.7 * fp.Size, distScale * 1.1 * fp.Size)
                fp.Frame.BackgroundColor3       = fp.Color
                fp.Frame.BackgroundTransparency = 1 - (0.65 * alpha)
                fp.Frame.Visible                = true
            else
                fp.Frame.Visible = false
            end
        end
    end
end

-- ── 3D box adornment ────────────────────────────────────────
local TS_FP = game:GetService("TweenService")

local function FP_Spawn3D(pos, normal, hrpCF)
    local sz   = Vector3.new(0.8 * FPSettings.Size, 0.15, 1.2 * FPSettings.Size)
    local step = Instance.new("Part")
    step.Size, step.Transparency, step.Anchored = sz, 1, true
    step.CanCollide, step.CanQuery = false, false
    step.CFrame = CFrame.lookAt(
        pos + Vector3.new(0, 0.08, 0),
        pos + hrpCF.LookVector,
        normal
    )
    step.Parent = Workspace.Terrain
    for i=#FP_Footprints3D,1,-1 do if not FP_Footprints3D[i].Parent then table.remove(FP_Footprints3D,i) end end
    if #FP_Footprints3D>=160 then local old=table.remove(FP_Footprints3D,1);old:Destroy() end
    table.insert(FP_Footprints3D,step)

    local function mkAdorn(extra, z, t)
        local a = Instance.new("BoxHandleAdornment")
        a.Size, a.Color3, a.AlwaysOnTop = sz + extra, FPSettings.Color, true
        a.ZIndex, a.Adornee, a.Transparency, a.Parent = z, step, t, step
        return a
    end
    local core  = mkAdorn(Vector3.zero, 6, 0)
    local glow  = mkAdorn(Vector3.new(0.6, 0.2, 0.6), 4, 0.25)
    local light = Instance.new("PointLight")
    light.Color, light.Range, light.Brightness, light.Parent = FPSettings.Color, 6 * FPSettings.Size, 3.5, step

    local ti = TweenInfo.new(FPSettings.Lifetime, Enum.EasingStyle.Linear)
    local t1 = TS_FP:Create(core,  ti, { Transparency = 1 })
    local t2 = TS_FP:Create(glow,  ti, { Transparency = 1 })
    local t3 = TS_FP:Create(light, ti, { Brightness = 0, Range = 0 })
    t1:Play() t2:Play() t3:Play()
    t1.Completed:Connect(function() step:Destroy() end)
end

-- ── 360° footstep indicator ──────────────────────────────────
local function FP_UpdateIndicators()
    if xDTaraZ.Panic.Panicked then
        for _, ind in pairs(FP_IndCache) do if ind then ind.Visible = false end end
        return
    end
    if not FPSettings.IndicatorEnabled or not FPSettings.Enabled then
        for _, ind in pairs(FP_IndCache) do if ind then ind.Visible = false end end
        return
    end
    local Camera = Workspace.CurrentCamera
    if not Camera then return end
    local now    = tick()
    local camCF  = Camera.CFrame
    local center = Camera.ViewportSize / 2
    local rp     = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude

    for player, data in pairs(FP_LatestStep) do
        local indicator = FP_GetIndicator(player)
        if now - data.SpawnTime >= FPSettings.Lifetime then
            indicator.Visible     = false
            FP_LatestStep[player] = nil
            continue
        end
        local sp, onS = Camera:WorldToViewportPoint(data.Position)
        local obscured = false
        if onS and sp.Z > 0 then
            rp.FilterDescendantsInstances = { LocalPlayer.Character }
            obscured = Workspace:Raycast(
                camCF.Position,
                data.Position + Vector3.new(0, 1, 0) - camCF.Position,
                rp
            ) ~= nil
        end
        if not onS or obscured or sp.Z <= 0 then
            local dX = data.Position.X - camCF.Position.X
            local dZ = data.Position.Z - camCF.Position.Z
            if math.abs(dX) > 0.01 or math.abs(dZ) > 0.01 then
                local flat  = Vector3.new(dX, 0, dZ).Unit
                local angle = math.atan2(flat:Dot(camCF.RightVector), flat:Dot(camCF.LookVector))
                local alpha = 1 - ((now - data.SpawnTime) / FPSettings.Lifetime)
                local r     = FPSettings.IndicatorRadius
                indicator.Position               = UDim2.fromOffset(
                    center.X + math.sin(angle) * r,
                    center.Y - math.cos(angle) * r
                )
                indicator.Rotation               = math.deg(angle)
                indicator.TextColor3             = FPSettings.IndicatorColor
                indicator.TextTransparency       = 1 - alpha
                indicator.TextStrokeTransparency = 1 - (alpha * 0.9)
                indicator.TextSize               = FPSettings.IndicatorSize
                indicator.Visible                = true
            else
                indicator.Visible = false
            end
        else
            indicator.Visible = false
        end
    end
end

-- ── step tracking loop ───────────────────────────────────────
task.spawn(function()
    while gui.Parent and xDTaraZ.State.Alive do
        task.wait(0.08)
        if not FPSettings.Enabled then continue end
        local localChar = FPGetChar(LocalPlayer)
        local localHrp  = FPGetRoot(localChar)

        for _, player in ipairs(Players:GetPlayers()) do
            if player == LocalPlayer then continue end
            if FPSettings.TeamCheck and not FPIsEnemy(player) then continue end

            local char = FPGetChar(player)
            if not char then continue end
            local hrp = FPGetRoot(char)
            if not hrp then continue end

            local curPos = hrp.Position
            if localHrp and (curPos - localHrp.Position).Magnitude > FPSettings.MaxDistance then
                continue
            end

            local lastPos = FP_LastPos[player]
            if not lastPos then
                FP_LastPos[player] = curPos
                continue
            end

            local hDist = (
                Vector3.new(curPos.X, 0, curPos.Z) -
                Vector3.new(lastPos.X, 0, lastPos.Z)
            ).Magnitude

            if hDist >= FPSettings.StepDistance then
                FP_LastPos[player] = curPos
                local rp = RaycastParams.new()
                rp.FilterDescendantsInstances = { char }
                rp.FilterType  = Enum.RaycastFilterType.Exclude
                rp.IgnoreWater = true
                local hit = Workspace:Raycast(curPos, Vector3.new(0, -15, 0), rp)
                if hit then
                    local pos = hit.Position + Vector3.new(0, 0.05, 0)
                    FP_LatestStep[player] = { Position = pos, SpawnTime = tick() }
                    if FPSettings.Method == "2D ScreenGui Overlay" then
                        FP_Spawn2D(pos)
                    else
                        FP_Spawn3D(pos, hit.Normal, hrp.CFrame)
                    end
                end
            end
        end
    end
end)

RunService.RenderStepped:Connect(function()
    if not FPSettings.Enabled then return end
    if FPSettings.Method == "2D ScreenGui Overlay" then FP_Update2D() end
    if FPSettings.IndicatorEnabled then FP_UpdateIndicators() end
end)

Players.PlayerRemoving:Connect(function(player)
    FP_LastPos[player]    = nil
    FP_LatestStep[player] = nil
    if FP_IndCache[player] then
        FP_IndCache[player]:Destroy()
        FP_IndCache[player] = nil
    end
end)

-- ─────────────────────────────────────────────────────────────────────────
    state.stageVisuals=xDTaraZ
    state.footsteps={Settings=FPSettings,Clear=FP_ClearAll}
    function state.footsteps.SetIndicator(value)
        FPSettings.IndicatorEnabled=value
        if not value then for _,ind in pairs(FP_IndCache) do ind.Visible=false end end
    end
    local Lighting=game:GetService("Lighting")
    local world={Fullbright=false,CameraFov=false,CameraFovValue=100}
    state.visualWorld=world
    local savedLight,savedCamera,savedFov
    local lastVisual,lastSound,lastRetry,lastWarn=0,0,0,0
    local visualConnection
    visualConnection=RunService.Heartbeat:Connect(function()
        local now=os.clock()
        if not gui.Parent then
            visualConnection:Disconnect()
            RunService:UnbindFromRenderStep("NoirVisualFov")
            xDTaraZ.State.Alive=false
            FPSettings.Enabled=false
            xDTaraZ.Visuals.ClearAll();FP_ClearAll();xDTaraZ.Sound.Uninstall()
            if xDTaraZ.Esp.Folder then xDTaraZ.Esp.Folder:Destroy() end
            if xDTaraZ.Sound.Folder then xDTaraZ.Sound.Folder:Destroy() end
            if xDTaraZ.Visuals.Gui then xDTaraZ.Visuals.Gui:Destroy() end
            if FPGui_ref then FPGui_ref:Destroy() end
            if savedLight then Lighting.Brightness,Lighting.ClockTime,Lighting.FogEnd,Lighting.GlobalShadows,Lighting.Ambient=table.unpack(savedLight);savedLight=nil end
            if savedCamera and savedFov then pcall(function() savedCamera.FieldOfView=savedFov end);savedCamera,savedFov=nil,nil end
            return
        end
        if now-lastVisual>=0.05 then
            lastVisual=now
            local ok,err=pcall(xDTaraZ.Visuals.Render)
            if not ok and now-lastWarn>5 then lastWarn=now;warn("[NOIR / Stage ESP] "..tostring(err)) end
        end
        if now-lastRetry>=2 then
            lastRetry=now
            xDTaraZ.GameLib.Net=state.net or getModule("Database","Security","Remotes")
            if xDTaraZ.Options.SoundEsp or (xDTaraZ.Visuals.Settings.Enabled and xDTaraZ.Options.EspMemory>0) then
                local ok,ready=pcall(xDTaraZ.Sound.Install)
                xDTaraZ.Sound.Ready=ok and ready==true
                if not xDTaraZ.Sound.Ready and xDTaraZ.Options.SoundEsp and now-(xDTaraZ.Sound.LastWarning or -math.huge)>10 then
                    xDTaraZ.Sound.LastWarning=now;warn("[NOIR / Sound ESP] Listener или getupvalues недоступен; повторяем поиск")
                end
            else
                if xDTaraZ.Sound.Entry then xDTaraZ.Sound.Uninstall() end
                xDTaraZ.Sound.Ready=false
            end
        end
        if now-lastSound>=0.1 then lastSound=now;pcall(xDTaraZ.Sound.Step) end
        if world.Fullbright then
            savedLight=savedLight or {Lighting.Brightness,Lighting.ClockTime,Lighting.FogEnd,Lighting.GlobalShadows,Lighting.Ambient}
            Lighting.Brightness,Lighting.ClockTime,Lighting.FogEnd,Lighting.GlobalShadows,Lighting.Ambient=2,14,1e6,false,Color3.fromRGB(178,178,178)
        elseif savedLight then
            Lighting.Brightness,Lighting.ClockTime,Lighting.FogEnd,Lighting.GlobalShadows,Lighting.Ambient=table.unpack(savedLight);savedLight=nil
        end
    end)
    RunService:BindToRenderStep("NoirVisualFov",Enum.RenderPriority.Camera.Value+3,function()
        local camera=Workspace.CurrentCamera
        if savedCamera and (not world.CameraFov or savedCamera~=camera) then
            pcall(function() savedCamera.FieldOfView=savedFov end);savedCamera,savedFov=nil,nil
        end
        if world.CameraFov and camera then
            if not savedCamera then savedCamera,savedFov=camera,camera.FieldOfView end
            if LocalPlayer:GetAttribute("IsSniperScoped")~=true then camera.FieldOfView=world.CameraFovValue end
        end
    end)
end


-- Опции из stage 7 и Shitaro; работают независимо от окна AirFlow.
do
    local opt={AntiAfk=false,InfiniteJump=false,Crosshair=false,ScopeCrosshair=false,CrosshairColor=Color3.fromRGB(170,255,195),CrosshairLength=10,CrosshairGap=5,CrosshairThickness=2}
    state.extraFeatures=opt
    local okVU,virtualUser=pcall(game.GetService,game,"VirtualUser")
    localPlayer.Idled:Connect(function()
        if not (gui.Parent and opt.AntiAfk and okVU and virtualUser) then return end
        local ok,err=pcall(function() virtualUser:CaptureController();virtualUser:ClickButton2(Vector2.new(0,0)) end)
        if not ok and not opt.afkWarned then opt.afkWarned=true;warn("[NOIR / Anti AFK] "..tostring(err)) end
    end)
    UserInputService.JumpRequest:Connect(function()
        if not (gui.Parent and opt.InfiniteJump) then return end
        -- Stage 7 разрешает эту функцию только вне раунда: если контроллер
        -- не найден, не предполагаем, что игрок в лобби.
        local controller=getModule("Controllers","CharacterController")
        if not controller or type(controller.getCurrentCharacter)~="function" then return end
        local ok,body=pcall(controller.getCurrentCharacter)
        if not ok or body then return end
        local char=localPlayer.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health>0 then pcall(hum.ChangeState,hum,Enum.HumanoidStateType.Jumping) end
    end)
    local cross=Instance.new("Frame")
    cross.Name="NoirCrosshair";cross.BackgroundTransparency=1
    cross.Position=UDim2.fromScale(0.5,0.5);cross.Size=UDim2.fromOffset(0,0)
    cross.Visible=false;cross.ZIndex=5;cross.Parent=overlay
    local pieces={}
    for i=1,4 do
        local p=Instance.new("Frame");p.BorderSizePixel=0;p.AnchorPoint=Vector2.new(0.5,0.5)
        p.ZIndex=6;p.Parent=cross;pieces[i]=p
        local stroke=Instance.new("UIStroke");stroke.Color=Color3.new(0,0,0);stroke.Thickness=1;stroke.Transparency=0.3;stroke.Parent=p
    end
    local function draw()
        cross.Visible=opt.Crosshair or (opt.ScopeCrosshair and localPlayer:GetAttribute("IsSniperScoped")==true)
        local len,gap,thick=opt.CrosshairLength,opt.CrosshairGap,opt.CrosshairThickness
        local half=gap+len/2
        for _,p in ipairs(pieces) do p.BackgroundColor3=opt.CrosshairColor end
        pieces[1].Position=UDim2.fromOffset(-half,0);pieces[2].Position=UDim2.fromOffset(half,0)
        pieces[3].Position=UDim2.fromOffset(0,-half);pieces[4].Position=UDim2.fromOffset(0,half)
        pieces[1].Size=UDim2.fromOffset(len,thick);pieces[2].Size=UDim2.fromOffset(len,thick)
        pieces[3].Size=UDim2.fromOffset(thick,len);pieces[4].Size=UDim2.fromOffset(thick,len)
    end
    opt.UpdateCrosshair=draw
    localPlayer:GetAttributeChangedSignal("IsSniperScoped"):Connect(draw)
    draw()
end

-- Самостоятельные адаптации функций Shitaro; данные попадания берутся только из локального луча игры.
do
    local Lighting=game:GetService("Lighting")
    local Debris=game:GetService("Debris")
    local q={Time=false,Hour=12,Fog=false,FogStart=0,FogEnd=500,FogColor=Color3.fromRGB(190,200,195),
        Ambient=false,AmbientColor=Color3.fromRGB(190,200,195),Exposure=false,ExposureValue=0,NoShadows=false,
        Bloom=false,BloomIntensity=1,BloomSize=24,BloomThreshold=2,
        ColorCorrection=false,Tint=Color3.new(1,1,1),Saturation=0,Brightness=0,Contrast=0,
        Tracers=false,TracerColor=Color3.fromRGB(120,255,170),TracerWidth=0.05,TracerLife=1.2,
        Impacts=false,ImpactColor=Color3.fromRGB(255,180,90),ImpactLife=3,
        Triggerbot=false,TriggerPart="Any",TriggerDelay=0.12,TriggerRange=2000,
        TriggerMulti=false,TriggerParts={Head=true,Chest=true,Stomach=true,Arms=true},TriggerReaction=0,TriggerScoped=false}
    state.shitaro=q
    local original={}
    local bloom,correction
    local function change(prop,value,suspended)
        if suspended then return end
        local old=original[prop]
        if value~=nil then
            if not old then original[prop]={Lighting[prop]} end
            Lighting[prop]=value
        elseif old then Lighting[prop]=old[1];original[prop]=nil end
    end
    local function cleanup()
        for prop,old in pairs(original) do pcall(function()Lighting[prop]=old[1]end);original[prop]=nil end
        if bloom then bloom:Destroy();bloom=nil end
        if correction then correction:Destroy();correction=nil end
    end
    local function lighting()
        -- При Fullbright не конфликтуем с его собственным сохранением и восстановлением.
        local full=state.visualWorld.Fullbright
        change("ClockTime",q.Time and q.Hour or nil,full)
        change("FogStart",q.Fog and q.FogStart or nil,false)
        change("FogEnd",q.Fog and q.FogEnd or nil,full)
        change("FogColor",q.Fog and q.FogColor or nil,false)
        change("Ambient",q.Ambient and q.AmbientColor or nil,full)
        change("ExposureCompensation",q.Exposure and q.ExposureValue or nil,false)
        local shadowValue=nil;if q.NoShadows then shadowValue=false end
        change("GlobalShadows",shadowValue,full)
        if q.Bloom then
            if not bloom then bloom=Instance.new("BloomEffect");bloom.Name="NoirBloom";bloom.Parent=Lighting end
            bloom.Enabled=true;bloom.Intensity=q.BloomIntensity;bloom.Size=q.BloomSize;bloom.Threshold=q.BloomThreshold
        elseif bloom then bloom:Destroy();bloom=nil end
        if q.ColorCorrection then
            if not correction then correction=Instance.new("ColorCorrectionEffect");correction.Name="NoirColorCorrection";correction.Parent=Lighting end
            correction.Enabled=true;correction.TintColor=q.Tint;correction.Saturation=q.Saturation;correction.Brightness=q.Brightness;correction.Contrast=q.Contrast
        elseif correction then correction:Destroy();correction=nil end
    end
    local oldNote=state.noteLocalRay
    local made={}
    local function marker(part,life)
        part.Anchored=true;part.CanCollide=false;part.CanTouch=false;part.CanQuery=false;part.CastShadow=false
        part.Material=Enum.Material.Neon;part.Parent=Workspace
        table.insert(made,part)
        if #made>120 then local old=table.remove(made,1);if old then old:Destroy() end end
        Debris:AddItem(part,life)
    end
    local function tracer(a,b)
        local length=(b-a).Magnitude;if length<0.05 then return end
        local part=Instance.new("Part");part.Name="NoirBulletTracer";part.Color=q.TracerColor
        part.Size=Vector3.new(q.TracerWidth,q.TracerWidth,length)
        part.CFrame=CFrame.lookAt((a+b)/2,b)
        marker(part,q.TracerLife)
    end
    local function impact(pos)
        local part=Instance.new("Part");part.Name="NoirBulletImpact";part.Color=q.ImpactColor
        part.Shape=Enum.PartType.Ball;part.Size=Vector3.new(0.22,0.22,0.22);part.CFrame=CFrame.new(pos)
        marker(part,q.ImpactLife)
    end
    state.noteLocalRay=function(result)
        if oldNote then pcall(oldNote,result) end
        if not (q.Tracers or q.Impacts) or type(result)~="table" then return end
        local cam=Workspace.CurrentCamera
        local pos=typeof(result.Origin)=="Vector3" and result.Origin or (cam and cam.CFrame.Position)
        if not pos then return end
        local hits=type(result.Hits)=="table" and result.Hits or {}
        local count=0
        for _,hit in ipairs(hits) do
            if type(hit)=="table" and typeof(hit.Position)=="Vector3" then
                count+=1;if q.Tracers then tracer(pos,hit.Position) end
                if q.Impacts and not hit.Exit then impact(hit.Position) end
                pos=hit.Position
                if count>=12 then break end
            end
        end
        if count==0 and q.Tracers and typeof(result.Direction)=="Vector3" and type(result.Distance)=="number" and result.Distance>0 then
            tracer(pos,pos+result.Direction*math.min(result.Distance,5000))
        end
    end
    local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Exclude;params.IgnoreWater=true
    local lastShot,lastStep,lastWarn=0,0,0
    local triggerTarget,triggerSince
    local function clearTrigger()triggerTarget=nil;triggerSince=nil end
    local function partGroup(name)
        if name=="Head" then return "Head" end
        if name=="LowerTorso" then return "Stomach" end
        if name=="UpperTorso" or name=="Torso" or name=="HumanoidRootPart" then return "Chest" end
        if name:find("Arm",1,true) or name:find("Hand",1,true) then return "Arms" end
        if name:find("Leg",1,true) or name:find("Foot",1,true) then return "Legs" end
        return nil
    end
    local function triggerStep(now)
        if not q.Triggerbot then clearTrigger();return end
        if q.TriggerScoped and localPlayer:GetAttribute("IsSniperScoped")~=true then clearTrigger();return end
        local cam=Workspace.CurrentCamera
        local characters=Workspace:FindFirstChild("Characters")
        local own=characters and characters:FindFirstChild(localPlayer.Name) or localPlayer.Character
        local controller=state.rapid and state.rapid.controller
        if not (cam and characters and own and controller and type(controller.peekCurrentEquippedForMovement)=="function") then clearTrigger();return end
        params.FilterDescendantsInstances={cam,own}
        local hit=Workspace:Raycast(cam.CFrame.Position,cam.CFrame.LookVector*q.TriggerRange,params)
        local part=safeHitInstance(hit)
        if not part then clearTrigger();return end
        local target
        for _,model in ipairs(characters:GetChildren()) do
            if part:IsDescendantOf(model) then target=model;break end
        end
        local mine=localPlayer:GetAttribute("Team") or teamOf(own)
        local ffa=string.find(tostring(Workspace:GetAttribute("Gamemode")),"Deathmatch",1,true)~=nil
        if not (target and isEnemy(target,own,ffa,mine)) then clearTrigger();return end
        if q.TriggerMulti then
            local group=partGroup(part.Name)
            if not group or not q.TriggerParts[group] then clearTrigger();return end
        elseif (q.TriggerPart=="Head" and part.Name~="Head") or (q.TriggerPart=="Torso" and not string.find(part.Name,"Torso",1,true)) then
            clearTrigger();return
        end
        if target~=triggerTarget then triggerTarget=target;triggerSince=now end
        if now-(triggerSince or now)<math.clamp(tonumber(q.TriggerReaction) or 0,0,2) or now-lastShot<q.TriggerDelay then return end
        local ok,weapon=pcall(controller.peekCurrentEquippedForMovement)
        if not ok or type(weapon)~="table" or weapon.Player~=localPlayer or weapon.IsDestroyed or weapon.IsReloading or weapon.IsShooting or type(weapon.shoot)~="function" or (tonumber(weapon.Rounds) or 1)<=0 then return end
        local props=weapon.Properties;local modes=type(props)=="table" and props.FireModes
        local primary=type(modes)=="table" and modes.Primary
        local fireRate=tonumber(type(primary)=="table" and primary.FireRate) or tonumber(type(props)=="table" and props.FireRate) or 0.12
        lastShot=now+math.max(0,math.clamp(fireRate,1/19,2)-q.TriggerDelay)
        local fired,err=pcall(weapon.shoot,weapon,"Primary")
        if not fired and now-lastWarn>5 then lastWarn=now;warn("[NOIR / Triggerbot] "..tostring(err)) end
    end

    local con
    con=RunService.Heartbeat:Connect(function()
        if not gui.Parent then
            con:Disconnect();cleanup();for _,p in ipairs(made) do pcall(p.Destroy,p) end;table.clear(made);return
        end
        local now=os.clock()
        if now-lastStep>=0.1 then
            lastStep=now
            local ok,err=pcall(lighting)
            if not ok and now-lastWarn>5 then lastWarn=now;warn("[NOIR / Lighting] "..tostring(err)) end
        end
        triggerStep(now)
    end)
end

-- Покупка выбранного снаряжения через локальный BuyMenu из Shitaro.
-- Отключено по умолчанию, не покупает ничего за Robux и не обходит проверки игры.
do
    local q=state.shitaro
    q.AutoBuy=false;q.BuyPrimary="none";q.BuySecondary="none";q.BuyGrenade="none";q.BuyGrenades={};q.BuyZeus=false
    q.BuyRevision=0
    function q.ResetBuy()q.BuyRevision+=1 end
    local function buyArea()
        local node=ReplicatedStorage
        for _,name in ipairs({"Database","Components","Common","IsInBuyArea"}) do
            node=node and node:FindFirstChild(name)
        end
        if not node or not node:IsA("ModuleScript") then return nil end
        local ok,result=pcall(require,node)
        return ok and type(result)=="function" and result or nil
    end
    local alternatives={{"AK-47","M4A1-S","M4A4"},{"Galil AR","FAMAS"},{"SG 553","AUG"},{"MAC-10","MP9"},{"Sawed-Off","MAG-7"},{"Glock-18","USP-S","P2000"},{"Tec-9","Five-SeveN"},{"Molotov","Incendiary Grenade"}}
    local function loadout(inventory)
        local paths={}
        if not inventory or type(inventory.GetEquippedInventoryItem)~="function" then return paths end
        for _,category in ipairs({"Pistols","Mid Tier","Rifles","Grenades"}) do
            for i=1,8 do
                local path=("Loadout.%s.Options.%d"):format(category,i)
                local ok,item=pcall(inventory.GetEquippedInventoryItem,localPlayer,path)
                if ok and (type(item)=="table" or typeof(item)=="Instance") and type(item.Name)=="string" then paths[item.Name]=path end
            end
        end
        local path="Equipped.Equipped Zeus x27"
        local ok,item=pcall(inventory.GetEquippedInventoryItem,localPlayer,path)
        if ok and (type(item)=="table" or typeof(item)=="Instance") and item.Name=="Zeus x27" then paths[item.Name]=path end
        return paths
    end
    local function resolve(name,paths)
        if name=="none" then return end
        if paths[name] then return name,paths[name] end
        for _,group in ipairs(alternatives) do
            if table.find(group,name) then
                for _,alternative in ipairs(group) do if paths[alternative] then return alternative,paths[alternative] end end
            end
        end
    end
    local function ownedItems(inventory)
        local owned={}
        if type(inventory.getCurrentInventory)=="function" then
            local ok,data=pcall(inventory.getCurrentInventory)
            if ok and type(data)=="table" then
                for _,slot in pairs(data) do
                    if type(slot)=="table" and type(slot._items)=="table" then
                        for _,item in pairs(slot._items) do
                            if type(item)=="table" and item.IsDestroyed~=true and type(item.Name)=="string" then owned[item.Name]=true end
                        end
                    end
                end
            end
        end
        local getter=inventory.peekCurrentEquippedForMovement
        if type(getter)=="function" then
            local ok,item=pcall(getter)
            if ok and type(item)=="table" and type(item.Name)=="string" and item.IsDestroyed~=true then owned[item.Name]=true end
        end
        return owned
    end
    local function alreadyOwned(name,owned)
        if owned[name] then return true end
        for _,group in ipairs(alternatives) do
            if table.find(group,name) then
                for _,equivalent in ipairs(group) do if owned[equivalent] then return true end end
            end
        end
        return false
    end
    task.spawn(function()
        local previousToken,queue,queued=nil,{},{}
        local attempted,activeBuy={},false
        local nextPurchase,lastWarning=0,0
        while gui.Parent do
            task.wait(0.25)
            local phase=Workspace:GetAttribute("GameState")
            local gameMode=Workspace:GetAttribute("Gamemode")
            local team=localPlayer:GetAttribute("Team")
            if not (phase=="Buy Period" or localPlayer:GetAttribute("BuyMenu")==true) or
                not (gameMode=="Bomb Defusal" or gameMode=="Hostage Rescue") or
                not (team=="Terrorists" or team=="Counter-Terrorists") then
                previousToken=nil;activeBuy=false;table.clear(queue);table.clear(attempted);continue
            end
            if not activeBuy then activeBuy=true;table.clear(attempted) end
            if not q.AutoBuy then previousToken=nil;table.clear(queue);continue end
            local menu=getModule("Interface","Screens","Gameplay","Middle","BuyMenu")
            local inventory=getModule("Controllers","InventoryController")
            local zone=buyArea()
            if not (menu and type(menu.purchase)=="function" and inventory and zone) then
                if os.clock()-lastWarning>15 then lastWarning=os.clock();warn("[NOIR / Auto buy] Ждём BuyMenu, инвентарь и зону покупки") end
                continue
            end
            local okInside,inside=pcall(zone,localPlayer)
            if not okInside or inside~=true then continue end
            local token=table.concat({tostring(phase),tostring(localPlayer:GetAttribute("CharacterGeneration")),tostring(team),tostring(q.BuyRevision)},"|")
            if previousToken~=token then
                previousToken=token;table.clear(queue);table.clear(queued)
                local paths=loadout(inventory);local owned=ownedItems(inventory)
                local requestedItems={q.BuyPrimary,q.BuySecondary,q.BuyGrenade,q.BuyZeus and "Zeus x27" or "none"}
                for _,name in ipairs(q.BuyGrenades) do table.insert(requestedItems,name) end
                for _,requested in ipairs(requestedItems) do
                    local name,path=resolve(requested,paths)
                    if name and path and not queued[name] and not attempted[name] and not alreadyOwned(name,owned) then queued[name]=true;table.insert(queue,{name,path}) end
                end
            end
            if #queue>0 and os.clock()>=nextPurchase then
                local item=table.remove(queue,1);nextPurchase=os.clock()+0.4
                attempted[item[1]]=true
                local ok,err=pcall(menu.purchase,item[1],item[2],false)
                if not ok then warn("[NOIR / Auto buy] "..tostring(err)) end
            end
        end
    end)
end

-- Дополнительные адаптации Shitaro: feedback, материалы своей модели, прогноз гранаты.
do
    local q={HitMarker=false,KillMarker=false,HitFlash=false,KillFlash=false,
        HitColor=Color3.fromRGB(230,255,235),KillColor=Color3.fromRGB(255,100,100),
        MarkerSize=14,MarkerFade=0.8,FlashPower=0.15,
        Body=false,Hands=false,Weapon=false,BodyColor=Color3.fromRGB(130,255,170),HandsColor=Color3.fromRGB(130,255,170),WeaponColor=Color3.fromRGB(130,255,170),
        BodyMaterial="ForceField",HandsMaterial="ForceField",WeaponMaterial="Neon",
        GrenadePath=false,GrenadeColor=Color3.fromRGB(130,255,170),GrenadeWidth=2,GrenadeMode="Far",
        GrenadeRadius=false,GrenadeRadiusColor=Color3.fromRGB(150,230,200)}
    state.shitaroMore=q
    function state.feedbackEnabled()return q.HitMarker or q.KillMarker or q.HitFlash or q.KillFlash end
    local cross=Instance.new("Frame");cross.Name="NoirHitMarker";cross.Size=UDim2.fromOffset(0,0);cross.Position=UDim2.fromScale(0.5,0.5)
    cross.BackgroundTransparency=1;cross.Visible=false;cross.ZIndex=7;cross.Parent=overlay
    local lines={}
    for i=1,4 do local line=Instance.new("Frame");line.BorderSizePixel=0;line.AnchorPoint=Vector2.new(0.5,0.5);line.ZIndex=8;line.Parent=cross;lines[i]=line end
    local flash=Instance.new("Frame");flash.Name="NoirHitFlash";flash.Size=UDim2.fromScale(1,1);flash.BackgroundTransparency=1;flash.BorderSizePixel=0;flash.ZIndex=2;flash.Parent=gui
    local startTime,showMark,showFlash,lastColor=0,false,false,q.HitColor
    function state.showHitFeedback(_,before,after)
        local killed=after<=0
        showMark=killed and q.KillMarker or (not killed and q.HitMarker)
        showFlash=killed and q.KillFlash or (not killed and q.HitFlash)
        if not showMark and not showFlash then return end
        lastColor=killed and q.KillColor or q.HitColor
        startTime=os.clock();cross.Visible=showMark
    end
    local saved=setmetatable({},{__mode="k"})
    local mats={ForceField=Enum.Material.ForceField,Neon=Enum.Material.Neon,Metal=Enum.Material.Metal,Glass=Enum.Material.Glass}
    local skip={HumanoidRootPart=true,Camera=true,CameraPart=true,ViewmodelLight=true,MuzzlePart=true}
    local function isHand(part,model)
        local p=part
        while p and p~=model do
            local name=p.Name
            if name=="Left Arm" or name=="Right Arm" or name=="Arms" or name=="Glove" or name=="Sleeve" or name:find("Hand",1,true) then return true end
            p=p.Parent
        end
        return false
    end
    local function applyModel(model,body,seen)
        if not model or not model.Parent or type(model.GetDescendants)~="function" then return end
        for _,part in ipairs(model:GetDescendants()) do
            if part:IsA("BasePart") and not skip[part.Name] then
                local hand=not body and isHand(part,model)
                local enabled=body and q.Body or (not body and (hand and q.Hands or (not hand and q.Weapon)))
                if enabled then
                    seen[part]=true
                    if not saved[part] then saved[part]={part.Color,part.Material,part.Reflectance} end
                    local color=body and q.BodyColor or (hand and q.HandsColor or q.WeaponColor)
                    local style=body and q.BodyMaterial or (hand and q.HandsMaterial or q.WeaponMaterial)
                    part.Color=color;part.Material=mats[style] or Enum.Material.ForceField
                    part.Reflectance=style=="Glass" and 0.3 or 0
                end
            end
        end
    end
    local function restoreUnseen(seen)
        for part,values in pairs(saved) do
            if not seen[part] then
                pcall(function()part.Color=values[1];part.Material=values[2];part.Reflectance=values[3]end)
                saved[part]=nil
            end
        end
    end
    local linePool={}
    for i=1,160 do local line=Instance.new("Frame");line.Name="GrenadeSegment";line.AnchorPoint=Vector2.new(0.5,0.5);line.BorderSizePixel=0;line.Visible=false;line.ZIndex=4;line.Parent=overlay;linePool[i]=line end
    local radiusLines={}
    for i=1,16 do local line=Instance.new("Frame");line.Name="GrenadeRadiusSegment";line.AnchorPoint=Vector2.new(0.5,0.5);line.BorderSizePixel=0;line.Visible=false;line.ZIndex=4;line.Parent=overlay;radiusLines[i]=line end
    local path,ring={},{ };local computing=false;local generation=0
    local grenadeInfo={
        ["HE Grenade"]={0.497488707304,1.6},Flashbang={0.61398953199387,1.5},["Smoke Grenade"]={0.56614202260971,0},
        ["Decoy Grenade"]={0.61398953199387,1.5},["Incendiary Grenade"]={0.56614208221436,2.4},Molotov={0.92103540897369,2.4}}
    local rp=RaycastParams.new();rp.FilterType=Enum.RaycastFilterType.Exclude;rp.IgnoreWater=true;rp.RespectCanCollide=false
    local function computePath(serial)
        local controller=state.rapid and state.rapid.controller
        local getter=controller and controller.peekCurrentEquippedForMovement
        local ok,weapon=pcall(getter or function()end)
        local cam,character=Workspace.CurrentCamera,localPlayer.Character
        if not ok or type(weapon)~="table" or not grenadeInfo[weapon.Name] or not cam or not character then return nil end
        local root=character.PrimaryPart or character:FindFirstChild("HumanoidRootPart")
        if not root or not root:IsA("BasePart") then return nil end
        local sim=getModule("Shared","GrenadeSimulator")
        if not (sim and type(sim.calculateThrowParameters)=="function" and type(sim.createInitialState)=="function" and type(sim.createConfig)=="function" and type(sim.step)=="function") then return nil end
        local opts=grenadeInfo[weapon.Name]
        local scale=math.max(0.01,(tonumber(weapon.Properties and weapon.Properties.Range) or 60)/40)
        if localPlayer:GetAttribute("IsCrouching")==true then scale*=0.8 end
        local mode=q.GrenadeMode
        if mode=="Auto" then
            local ok,near=pcall(UserInputService.IsMouseButtonPressed,UserInputService,Enum.UserInputType.MouseButton2)
            mode=ok and near and "Near" or "Far"
        end
        local spawnPos,velocity=sim.calculateThrowParameters(root.Position,cam.CFrame.LookVector,mode,scale)
        if typeof(spawnPos)~="Vector3" or typeof(velocity)~="Vector3" then return nil end
        local speed=root.AssemblyLinearVelocity or Vector3.zero
        local time=Workspace:GetServerTimeNow()
        local body=sim.createInitialState(spawnPos,velocity,mode,speed,scale,time)
        local incendiary=weapon.Name=="Molotov" or weapon.Name=="Incendiary Grenade"
        local cfg=sim.createConfig(opts[1],scale,mode=="Near",opts[2]>0 and opts[2] or nil,incendiary and 0.1 or nil,incendiary or nil)
        if type(body)~="table" or type(cfg)~="table" or typeof(body.position)~="Vector3" then return nil end
        cfg.restitution=0.4;cfg.maxBounces=20
        local debris=Workspace:FindFirstChild("Debris")
        rp.FilterDescendantsInstances=debris and {debris,character} or {character}
        pcall(function() local team=localPlayer:GetAttribute("Team");rp.CollisionGroup=team=="Terrorists" and "TGrenade" or (team=="Counter-Terrorists" and "CTGrenade" or "Default") end)
        local constants=sim.Constants or {}
        local dt=math.clamp(tonumber(constants.FIXED_TIMESTEP) or 0.0078125,0.001,0.1)
        local steps=math.min(1600,math.ceil(math.clamp(tonumber(constants.MAX_SIMULATION_TIME) or 10,0.1,10)/dt)+2)
        local stride=math.max(1,math.floor(0.0625/dt+0.5))
        local points={body.position}
        for i=1,steps do
            if not gui.Parent or not q.GrenadePath or serial~=generation then return nil end
            local nextBody,event=sim.step(body,cfg,rp,dt)
            if type(nextBody)~="table" or typeof(nextBody.position)~="Vector3" then return nil end
            body=nextBody
            if i%stride==0 or event or body.isAtRest then table.insert(points,body.position) end
            if (event and (type(event)~="table" or event.type~="bounce")) or body.isAtRest or #points>=160 then break end
            if i%24==0 then task.wait() end
        end
        if #points<2 then return nil end
        local ringPoints={}
        local radius=weapon.Name=="Smoke Grenade" and 14.7 or ((weapon.Name=="Molotov" or weapon.Name=="Incendiary Grenade") and 17.6 or nil)
        if q.GrenadeRadius and radius then
            local ok,value=pcall(function()
                pcall(function()rp.CollisionGroup="Default"end)
                local center=points[#points]
                local floor=Workspace:Raycast(center+Vector3.new(0,7,0),Vector3.new(0,-20,0),rp)
                if floor then center=floor.Position+floor.Normal*0.06 end
                local result={}
                for i=1,16 do
                    local angle=2*math.pi*(i-1)/16;local direction=Vector3.new(math.cos(angle),0,math.sin(angle))
                    local hit=Workspace:Raycast(center+Vector3.new(0,1.25,0),direction*radius,rp)
                    local length=hit and math.abs(hit.Normal.Y)<0.65 and math.clamp(hit.Distance-0.12,0.35,radius) or radius
                    local p=center+direction*length
                    local ground=Workspace:Raycast(p+Vector3.new(0,7,0),Vector3.new(0,-20,0),rp)
                    result[i]=ground and ground.Position+ground.Normal*0.06 or p+Vector3.new(0,0.08,0)
                end
                return result
            end)
            if ok then ringPoints=value end
        end
        return points,ringPoints
    end
    local lastModel,lastPath,lastWarn=0,0,0
    local heartbeat,renderConnection
    heartbeat=RunService.Heartbeat:Connect(function()
        if not gui.Parent then heartbeat:Disconnect();if renderConnection then renderConnection:Disconnect() end;generation+=1;restoreUnseen({});cross:Destroy();flash:Destroy();for _,v in ipairs(linePool) do v:Destroy() end;for _,v in ipairs(radiusLines) do v:Destroy() end;return end
        local now=os.clock()
        if now-lastModel>=0.25 then
            lastModel=now
            local ok,err=pcall(function()
                local seen={};local own=localPlayer.Character
                if q.Body then applyModel(own,true,seen) end
                if q.Hands or q.Weapon then
                    local controller=state.rapid and state.rapid.controller
                    local getter=controller and controller.peekCurrentEquippedForMovement
                    local okGet,weapon=pcall(getter or function()end)
                    local model=okGet and type(weapon)=="table" and weapon.Viewmodel and weapon.Viewmodel.Model
                    applyModel(model,false,seen)
                end
                restoreUnseen(seen)
            end)
            if not ok and now-lastWarn>5 then lastWarn=now;warn("[NOIR / Local materials] "..tostring(err)) end
        end
        if not q.GrenadePath then
            if #path>0 then table.clear(path) end
            if #ring>0 then table.clear(ring) end
            if computing then generation+=1;computing=false end
        elseif not computing and now-lastPath>=0.3 then
            lastPath=now;computing=true;generation+=1;local serial=generation
            task.spawn(function()
                local ok,points,radiusPoints=pcall(computePath,serial)
                if generation==serial then path=ok and points or {};ring=ok and radiusPoints or {};computing=false end
                if not ok and os.clock()-lastWarn>8 then lastWarn=os.clock();warn("[NOIR / Grenade path] "..tostring(points)) end
            end)
        end
    end)
    renderConnection=RunService.RenderStepped:Connect(function()
        if not gui.Parent then return end
        local age=os.clock()-startTime
        local alpha=math.clamp(1-age/math.max(0.1,q.MarkerFade),0,1)
        cross.Visible=showMark and alpha>0
        flash.BackgroundTransparency=showFlash and (1-alpha*q.FlashPower) or 1;flash.BackgroundColor3=lastColor
        if cross.Visible then
            local d=q.MarkerSize*0.45
            for i,ln in ipairs(lines) do
                local x=(i%2==0) and d or -d;local y=(i<=2) and -d or d
                ln.Position=UDim2.fromOffset(x,y);ln.Size=UDim2.fromOffset(q.MarkerSize,2);ln.Rotation=(x*y>0) and 45 or -45
                ln.BackgroundColor3=lastColor;ln.BackgroundTransparency=1-alpha
            end
        end
        local cam=Workspace.CurrentCamera
        for i,line in ipairs(linePool) do
            local a,b=path[i],path[i+1]
            line.Visible=false
            if q.GrenadePath and cam and a and b then
                local p1=cam:WorldToViewportPoint(a);local p2=cam:WorldToViewportPoint(b)
                if p1.Z>0 and p2.Z>0 then
                    local dx,dy=p2.X-p1.X,p2.Y-p1.Y
                    line.Position=UDim2.fromOffset((p1.X+p2.X)/2,(p1.Y+p2.Y)/2)
                    line.Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),q.GrenadeWidth)
                    line.Rotation=math.deg(math.atan2(dy,dx));line.BackgroundColor3=q.GrenadeColor;line.Visible=true
                end
            end
        end
        for i,line in ipairs(radiusLines) do
            line.Visible=false
            local a,b=ring[i],ring[i%#radiusLines+1]
            if q.GrenadePath and q.GrenadeRadius and cam and a and b then
                local p1=cam:WorldToViewportPoint(a);local p2=cam:WorldToViewportPoint(b)
                if p1.Z>0 and p2.Z>0 then
                    local dx,dy=p2.X-p1.X,p2.Y-p1.Y
                    line.Position=UDim2.fromOffset((p1.X+p2.X)/2,(p1.Y+p2.Y)/2)
                    line.Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),q.GrenadeWidth)
                    line.Rotation=math.deg(math.atan2(dy,dx));line.BackgroundColor3=q.GrenadeRadiusColor;line.Visible=true
                end
            end
        end
    end)
end

-- Адаптация настроек мира и модели из Shitaro к Noir. Всё выключено по умолчанию.
do
    local Lighting=game:GetService("Lighting")
    local q={Sky=false,SkyPreset="Jungle",Weather=false,WeatherType="Snow",WeatherColor=Color3.fromRGB(235,255,245),WeatherRate=250,
        ViewOffset=false,ViewX=0,ViewY=0,ViewZ=0}
    state.shitaroWorld=q
    local names={"SkyboxBk","SkyboxDn","SkyboxFt","SkyboxLf","SkyboxRt","SkyboxUp"}
    local presets={
        Jungle={214399891,214399887,214399894,214405668,214399899,214399889},
        Blossom={271042516,271077243,271042556,271042310,271042467,271077958},
        ["Red night"]={401664839,401664862,401664960,401664881,401664936},
        Purple={13694952867,13694968325,13694980654,13694998113,13695002700,13695007103},
        Foggy={1370717244,1370717336,1370717438,1370717567,1370717698,1370717782}}
    local customSkyAssets={Galaxy=15983996673,Anime=13107361022,Minecraft=2758029221}
    local hiddenSkies={};local sky,skyPreset
    local requests,responses={},{};local loading=0;local closed=false;local closedAt=0;local lastSkyWarning=0
    local function hideOriginalSkies()
        for _,child in ipairs(Lighting:GetChildren()) do
            if child~=sky and child:IsA("Sky") then hiddenSkies[child]=child.Parent;child.Parent=nil end
        end
    end
    local function restoreSky()
        if sky then sky:Destroy();sky=nil;skyPreset=nil end
        for object,parent in pairs(hiddenSkies) do
            pcall(function() if object.Parent==nil and parent then object.Parent=parent end end)
            hiddenSkies[object]=nil
        end
    end
    local function cleanupLoaded(objects)
        if type(objects)~="table" then return end
        for _,object in ipairs(objects) do
            if typeof(object)=="Instance" then pcall(function()object:Destroy()end) end
        end
    end
    local function processSkyResponses()
        local pending=responses;responses={}
        for _,response in ipairs(pending) do
            loading=math.max(0,loading-1)
            local selected=not closed and q.Sky and q.SkyPreset==response.name and gui.Parent
            local newSky
            if selected and response.ok and type(response.objects)=="table" then
                for _,object in ipairs(response.objects) do
                    if typeof(object)=="Instance" then
                        local ok,result=pcall(function()
                            local found=object:IsA("Sky") and object or object:FindFirstChildWhichIsA("Sky",true)
                            return found and found:Clone()
                        end)
                        if ok and result and result:IsA("Sky") then newSky=result;break end
                    end
                end
            end
            cleanupLoaded(response.objects)
            if newSky then
                -- Копируем только Sky, не импортируем скрипты и прочие объекты asset.
                local ok=pcall(function()
                    hideOriginalSkies()
                    newSky.Name="NoirCustomSky";newSky.Parent=Lighting
                    if sky then sky:Destroy() end
                    sky=newSky;skyPreset=response.name
                end)
                if not ok then pcall(function()newSky:Destroy()end);restoreSky() end
            elseif selected and os.clock()-lastSkyWarning>10 then
                lastSkyWarning=os.clock();warn("[NOIR / Sky] Asset недоступен или не содержит Sky: "..response.name)
            end
        end
    end
    local function requestSky(name,id,now)
        local last=requests[name]
        if loading>=2 or (last and now-last<12) then return end
        requests[name]=now;loading+=1
        task.spawn(function()
            -- После GetObjects поток может потерять права: только кладём ответ в Lua-очередь.
            local ok,objects=pcall(function()return game:GetObjects("rbxassetid://"..tostring(id))end)
            responses[#responses+1]={name=name,ok=ok,objects=objects}
        end)
    end
    local function updateSky()
        if not q.Sky then restoreSky();return end
        local id=customSkyAssets[q.SkyPreset]
        if id then
            if sky and sky.Parent and skyPreset==q.SkyPreset then hideOriginalSkies();return end
            requestSky(q.SkyPreset,id,os.clock());return
        end
        local ids=presets[q.SkyPreset] or presets.Jungle
        hideOriginalSkies()
        if not sky or not sky.Parent or skyPreset~=q.SkyPreset then
            if sky then sky:Destroy() end
            sky=Instance.new("Sky");sky.Name="NoirCustomSky"
            for i,property in ipairs(names) do sky[property]="rbxassetid://"..tostring(ids[i]) end
            sky.Parent=Lighting;skyPreset=q.SkyPreset
        end
    end
    local part,emitter,weatherType,weatherColor,weatherRate
    local function stopWeather()
        if part then part:Destroy();part=nil;emitter=nil end
        weatherType=nil;weatherColor=nil;weatherRate=nil
    end
    local function updateWeather()
        if not q.Weather then stopWeather();return end
        local cam=Workspace.CurrentCamera
        if not cam then return end
        if not part or not part.Parent then
            if part then part:Destroy() end
            part=Instance.new("Part");part.Name="NoirWeather";part.Anchored=true;part.CanCollide=false;part.CanTouch=false;part.CanQuery=false;part.Transparency=1
            part.Size=Vector3.new(260,1,260);part.Parent=Workspace
            emitter=Instance.new("ParticleEmitter");emitter.Name="NoirWeatherEmitter";emitter.Parent=part
            emitter.EmissionDirection=Enum.NormalId.Bottom;emitter.LightInfluence=0;emitter.LightEmission=0.4
            pcall(function()emitter.Shape=Enum.ParticleEmitterShape.Box;emitter.ShapeStyle=Enum.ParticleEmitterShapeStyle.Volume end)
            weatherType=nil
        end
        part.CFrame=CFrame.new(cam.CFrame.Position+Vector3.new(0,60,0))
        if weatherType~=q.WeatherType or weatherColor~=q.WeatherColor or weatherRate~=q.WeatherRate then
            weatherType=q.WeatherType;weatherColor=q.WeatherColor;weatherRate=q.WeatherRate
            emitter.Color=ColorSequence.new(q.WeatherColor)
            emitter.Texture=q.WeatherType=="Stars" and "rbxasset://textures/particles/sparkles_main.dds" or "rbxasset://textures/particles/smoke_main.dds"
            emitter.Rate=q.WeatherType=="Stars" and math.max(10,q.WeatherRate*0.4) or q.WeatherRate
            if q.WeatherType=="Stars" then
                emitter.Lifetime=NumberRange.new(6,9);emitter.Speed=NumberRange.new(4,8);emitter.Acceleration=Vector3.new(1,-3,0.6)
                emitter.SpreadAngle=Vector2.new(16,16);emitter.Rotation=NumberRange.new(0,360);emitter.RotSpeed=NumberRange.new(-14,14)
                emitter.Size=NumberSequence.new(0.5);emitter.Transparency=NumberSequence.new(0);emitter.LightEmission=0.15
            elseif q.WeatherType=="Sakura" then
                emitter.Lifetime=NumberRange.new(5,10);emitter.Speed=NumberRange.new(5,10);emitter.Acceleration=Vector3.new(4,-5,2)
                emitter.SpreadAngle=Vector2.new(40,40);emitter.Rotation=NumberRange.new(0,360);emitter.RotSpeed=NumberRange.new(-80,80)
                emitter.Size=NumberSequence.new(0.5);emitter.Transparency=NumberSequence.new(0.15);emitter.LightEmission=0.4
            else
                emitter.Lifetime=NumberRange.new(4,6);emitter.Speed=NumberRange.new(6,12);emitter.Acceleration=Vector3.new(2,-6,1)
                emitter.SpreadAngle=Vector2.new(35,35);emitter.Rotation=NumberRange.new(0,360);emitter.RotSpeed=NumberRange.new(-40,40)
                emitter.Size=NumberSequence.new(0.55);emitter.Transparency=NumberSequence.new(0.2);emitter.LightEmission=0.4
            end
        end
    end
    local offsets,offsetOriginal,offsetApplied
    local function restoreOffsets()
        if offsets and offsetOriginal then
            for _,key in ipairs({"X Offset","Y Offset","Z Offset"}) do
                if offsets[key]==offsetApplied[key] then offsets[key]=offsetOriginal[key] end
            end
        end
        offsets=nil;offsetOriginal=nil;offsetApplied=nil
    end
    local function updateOffsets()
        if not q.ViewOffset then restoreOffsets();return end
        local data=getModule("Controllers","DataController")
        if not data or type(data.Get)~="function" then restoreOffsets();return end
        local ok,current=pcall(data.Get,localPlayer,"Settings.Game.Viewmodel")
        if not ok or type(current)~="table" then restoreOffsets();return end
        if offsets~=current then
            restoreOffsets();offsets=current
            offsetOriginal={["X Offset"]=current["X Offset"],["Y Offset"]=current["Y Offset"],["Z Offset"]=current["Z Offset"]}
            offsetApplied={}
        end
        local values={["X Offset"]=q.ViewX,["Y Offset"]=q.ViewY,["Z Offset"]=q.ViewZ}
        for key,value in pairs(values) do current[key]=value;offsetApplied[key]=value end
    end
    local last,lastWarn=0,0;local con
    con=RunService.Heartbeat:Connect(function()
        if not gui.Parent and not closed then
            closed=true;closedAt=os.clock();pcall(restoreSky);pcall(stopWeather);pcall(restoreOffsets)
        end
        pcall(processSkyResponses)
        if closed then
            if loading==0 or os.clock()-closedAt>30 then con:Disconnect() end
            return
        end
        local now=os.clock();if now-last<0.2 then return end;last=now
        for _,fn in ipairs({updateSky,updateWeather,updateOffsets}) do
            local ok,err=pcall(fn)
            if not ok and now-lastWarn>5 then lastWarn=now;warn("[NOIR / World] "..tostring(err)) end
        end
    end)
end

-- Отображение активных гранат по реплицированным объектам и игровым событиям.
do
    local CollectionService=game:GetService("CollectionService")
    local q={Flying=false,Zones=false,Fill=false,Timer=false,HEThreat=false,FillOpacity=25,FlyingColor=Color3.fromRGB(220,255,230),SmokeColor=Color3.fromRGB(185,210,220),FireColor=Color3.fromRGB(255,135,75),Width=2}
    state.grenadeWorld=q
    local allowed={["HE Grenade"]=true,Flashbang=true,["Smoke Grenade"]=true,["Decoy Grenade"]=true,["Incendiary Grenade"]=true,Molotov=true}
    local rp=RaycastParams.new();rp.FilterType=Enum.RaycastFilterType.Exclude;rp.IgnoreWater=true;rp.RespectCanCollide=false
    local zones,projectiles={},{}
    local lines,labels={},{}
    local function line(i)
        local l=lines[i]
        if not l then
            l=Instance.new("Frame");l.Name="NoirGrenadeZoneSegment";l.AnchorPoint=Vector2.new(0.5,0.5);l.BorderSizePixel=0;l.BackgroundTransparency=0.15;l.Visible=false;l.ZIndex=4;l.Parent=overlay;lines[i]=l
        end
        return l
    end
    local function label(i)
        local l=labels[i]
        if not l then
            l=Instance.new("TextLabel");l.Name="NoirGrenadeLabel";l.AnchorPoint=Vector2.new(0.5,0.5);l.BackgroundTransparency=1
            l.Size=UDim2.fromOffset(180,22);l.Font=Enum.Font.GothamBold;l.TextSize=13;l.TextStrokeTransparency=0.3;l.Visible=false;l.ZIndex=5;l.Parent=overlay;labels[i]=l
        end
        return l
    end
    local function positionOf(item)
        if not item or not item.Parent then return nil end
        if item:IsA("BasePart") then return item.Position end
        if item:IsA("Model") and item.PrimaryPart then return item.PrimaryPart.Position end
        local ok,pivot=pcall(item.GetPivot,item)
        if ok and typeof(pivot)=="CFrame" then return pivot.Position end
        return nil
    end
    -- Пакеты VFX используются, если соответствующая реплицированная зона недоступна.
    local eventZones={}
    local function zoneId(v)
        if (type(v)~="string" and type(v)~="number") or #tostring(v)>100 then return nil end
        return tostring(v)
    end
    local function finite(v)
        return type(v)=="number" and v==v and math.abs(v)<=1000000
    end
    local function zoneVoxels(kind,voxels)
        if type(voxels)~="table" then return nil end
        local samples={}
        for index,voxel in ipairs(voxels) do
            if index>1024 then break end
            if type(voxel)=="table" and typeof(voxel.Position)=="Vector3" then
                local p=voxel.Position
                if finite(p.X) and finite(p.Y) and finite(p.Z) then
                    local sx=tonumber(kind=="smoke" and voxel.Size or voxel.SizeX) or 0
                    local sz=tonumber(kind=="smoke" and voxel.Size or voxel.SizeZ) or 0
                    if not finite(sx) then sx=0 end;if not finite(sz) then sz=0 end
                    samples[#samples+1]={pos=p,hx=math.clamp(sx,0,80)*0.5,hz=math.clamp(sz,0,80)*0.5}
                    if #samples>=256 then break end
                end
            end
        end
        if #samples==0 then return nil end
        return samples
    end
    local function upsertZone(kind,packet,update)
        if type(packet)~="table" then return end
        local id=zoneId(kind=="smoke" and packet.SmokeId or packet.FireId)
        if not id then return end
        local samples=zoneVoxels(kind,packet.Voxels);if not samples then return end
        local key=kind..":"..id;local now=os.clock();local old=eventZones[key]
        if not old then
            local count,oldKey,oldTime=0,nil,nil
            for k,v in pairs(eventZones) do
                count+=1;if not oldTime or v.created<oldTime then oldKey,oldTime=k,v.created end
            end
            if count>=48 and oldKey then eventZones[oldKey]=nil end
        end
        local duration=tonumber(packet.Duration)
        if not finite(duration) or duration<=0 then duration=20 end
        local expires=(update and old and old.expires) or (now+math.clamp(duration,0.1,120))
        local center=kind=="fire" and packet.Position or nil
        if typeof(center)~="Vector3" or not (finite(center.X) and finite(center.Y) and finite(center.Z)) then center=update and old and old.center or nil end
        eventZones[key]={key=key,id=id,kind=kind,samples=samples,center=center,created=old and old.created or now,expires=expires}
    end
    local function destroyZone(kind,id)
        id=zoneId(id);if id then eventZones[kind..":"..id]=nil end
    end

    local function makeZone(container,kind,event)
        local samples={}
        if event then
            samples=event.samples
        else
        for _,part in ipairs(container:GetChildren()) do
            if part:IsA("BasePart") then
                local p=part.Position;local size=part.Size
                samples[#samples+1]={pos=p,hx=math.max(0,size.X)*0.5,hz=math.max(0,size.Z)*0.5}
                if #samples>=256 then break end
            end
        end
        end
        if #samples==0 then return nil end
        local sum=Vector3.zero
        for _,sample in ipairs(samples) do sum+=sample.pos end
        local center=event and event.center or sum/#samples;local radius=0
        for _,sample in ipairs(samples) do
            local dx=math.abs(sample.pos.X-center.X)+sample.hx
            local dz=math.abs(sample.pos.Z-center.Z)+sample.hz
            radius=math.max(radius,math.sqrt(dx*dx+dz*dz))
        end
        radius=math.clamp(radius,2,40)
        local floor=Workspace:Raycast(center+Vector3.new(0,7,0),Vector3.new(0,-20,0),rp)
        if floor then center=floor.Position+floor.Normal*0.06 end
        local points={};local segments=16
        for i=1,segments do
            local angle=math.pi*2*(i-1)/segments
            local dir=Vector3.new(math.cos(angle),0,math.sin(angle))
            local wall=Workspace:Raycast(center+Vector3.new(0,1.25,0),dir*radius,rp)
            local length=wall and math.abs(wall.Normal.Y)<0.65 and math.clamp(wall.Distance-0.12,0.35,radius) or radius
            local p=center+dir*length
            local ground=Workspace:Raycast(p+Vector3.new(0,7,0),Vector3.new(0,-20,0),rp)
            points[i]=ground and ground.Position+ground.Normal*0.06 or p+Vector3.new(0,0.08,0)
        end
        return {instance=container,event=event,kind=kind,center=center,points=points,samples=samples}
    end
    -- Приближённая локальная заливка по выбранным voxel-образцам, не физика игры.
    local fills={}
    local function hideFills(destroy)
        for _,part in ipairs(fills) do
            if destroy then part:Destroy() else part.Parent=nil end
        end
        if destroy then table.clear(fills) end
    end
    local function drawFills(current)
        if not q.Zones or not q.Fill then hideFills(false);return end
        local used=0
        for _,zone in ipairs(current) do
            local seen={};local samples=zone.samples
            local stride=math.max(1,math.ceil(#samples/16))
            for index=1,#samples,stride do
                local sample=samples[index];local pos=sample.pos
                local key=math.floor(pos.X+0.5)..":"..math.floor(pos.Z+0.5)
                if not seen[key] then
                    seen[key]=true
                    local hit=Workspace:Raycast(pos+Vector3.new(0,7,0),Vector3.new(0,-20,0),rp)
                    if hit and hit.Normal.Y>0.85 then
                        used+=1
                        local part=fills[used]
                        if not part then
                            part=Instance.new("Part");part.Name="NoirGrenadeZoneFill";part.Anchored=true
                            part.CanCollide=false;part.CanTouch=false;part.CanQuery=false;part.CastShadow=false
                            part.Material=Enum.Material.Neon;fills[used]=part
                        end
                        part.Color=zone.kind=="smoke" and q.SmokeColor or q.FireColor
                        part.Transparency=1-math.clamp(tonumber(q.FillOpacity) or 25,10,90)/100
                        part.Size=Vector3.new(math.clamp(sample.hx*2,0.5,12),0.04,math.clamp(sample.hz*2,0.5,12))
                        part.CFrame=CFrame.new(hit.Position+hit.Normal*0.04)
                        part.Parent=Workspace
                        if used>=96 then break end
                    end
                end
            end
            if used>=96 then break end
        end
        for i=used+1,#fills do fills[i].Parent=nil end
    end

    local function scan()
        local debris=Workspace:FindFirstChild("Debris")
        local ignore={};if debris then table.insert(ignore,debris) end
        if localPlayer.Character then table.insert(ignore,localPlayer.Character) end
        rp.FilterDescendantsInstances=ignore
        local nextZones,nextFlying,seenZones={},{},{}
        if q.Zones and debris then
            for _,item in ipairs(debris:GetChildren()) do
                local name=item.Name
                local kind=name:sub(1,11)=="VoxelSmoke_" and "smoke" or (name:sub(1,10)=="VoxelFire_" and "fire" or nil)
                if kind then
                    local z=makeZone(item,kind)
                    if z then
                        local id=name:sub(kind=="smoke" and 12 or 11)
                        z.timerEvent=eventZones[kind..":"..id]
                        table.insert(nextZones,z);seenZones[name]=true
                    end
                    if #nextZones>=6 then break end
                end
            end
        end
        if q.Zones and #nextZones<6 then
            local now=os.clock()
            for _,event in pairs(eventZones) do
                local name=(event.kind=="smoke" and "VoxelSmoke_" or "VoxelFire_")..event.id
                if event.expires>now and not seenZones[name] then
                    local z=makeZone(nil,event.kind,event)
                    if z then table.insert(nextZones,z) end
                    if #nextZones>=6 then break end
                end
            end
        end
        if q.Flying then
            for _,item in ipairs(CollectionService:GetTagged("Grenade")) do
                if item:IsA("Model") and item.Parent and allowed[item:GetAttribute("GrenadeName")] and item:GetAttribute("SimulationFinished")~=true then
                    table.insert(nextFlying,item)
                    if #nextFlying>=32 then break end
                end
            end
        end
        zones,projectiles=nextZones,nextFlying
        drawFills(nextZones)
    end
    -- Spawn/Bounce/Resolve дополняют модели; позиции из пакетов помечаются LAST, не интерполируются.
    local eventTracks,subscriptions,unmanaged={},{},setmetatable({},{__mode="k"})
    local eventLast=0
    local function validId(v)
        if (type(v)~="string" and type(v)~="number") or #tostring(v)>100 then return nil end
        return tostring(v)
    end
    local function spawnEvent(packet)
        if type(packet)~="table" or not allowed[packet.Weapon] or type(packet.State)~="table" then return end
        local id=validId(packet.Id);local pos=packet.State.Position
        if not id or typeof(pos)~="Vector3" then return end
        local n=0;local oldest,oldTime
        for key,record in pairs(eventTracks) do
            n+=1;if not oldTime or record.created<oldTime then oldest,oldTime=key,record.created end
        end
        if not eventTracks[id] and n>=64 then eventTracks[oldest]=nil end
        local now=os.clock();local physics=type(packet.Physics)=="table" and packet.Physics or nil
        local function timestampValid(v)return type(v)=="number" and v==v and math.abs(v)<=1e12 end
        local start=tonumber(packet.State.StartTime)
        if not timestampValid(start) then local ok,value=pcall(Workspace.GetServerTimeNow,Workspace);start=ok and tonumber(value) or 0 end
        if not timestampValid(start) then start=0 end
        eventTracks[id]={id=id,weapon=packet.Weapon,pos=pos,at=now,created=now,velocity=packet.State.Velocity,
            physics=physics,group=physics and physics.CollisionGroup,starttime=start,elapsed=0,bounces=0,
            jump=packet.State.IsJumpThrow==true,revision=1}
    end
    local function bounceEvent(packet)
        if type(packet)~="table" then return end
        local id=validId(packet.Id);local track=id and eventTracks[id]
        if track then
            if typeof(packet.Position)=="Vector3" then track.pos=packet.Position;track.at=os.clock() end
            if typeof(packet.Velocity)=="Vector3" then track.velocity=packet.Velocity end
            local count=tonumber(packet.BounceIndex);if finite(count) then track.bounces=math.clamp(math.floor(count),0,40) end
            local stamp=tonumber(packet.Timestamp)
            if stamp and stamp==stamp and math.abs(stamp)<=1e12 and track.starttime>0 then track.elapsed=math.clamp(stamp-track.starttime,0,10) end
            track.revision+=1;track.endpoint=nil;track.predictedRevision=nil;track.lastAttempt=nil;track.damage=nil;track.damageAt=nil
        end
    end
    local function resolveEvent(packet)
        if type(packet)~="table" then return end
        local id=validId(packet.Id);if id then eventTracks[id]=nil end
    end
    -- Оценка точки взрыва и урона от HE. Это локальный прогноз, не серверный урон.
    local predictBusy=0
    local damageRay=RaycastParams.new();damageRay.FilterType=Enum.RaycastFilterType.Exclude
    damageRay.IgnoreWater=true;damageRay.RespectCanCollide=false
    local function targetEnemy(track)
        if track.weapon~="HE Grenade" or type(track.group)~="string" then return false end
        if Workspace:GetAttribute("Gamemode")=="Deathmatch" or Workspace:GetAttribute("VIPFriendlyFireEnabled")==true then return true end
        local team=localPlayer:GetAttribute("Team")
        if team=="Terrorists" then return track.group=="CTGrenade" end
        if team=="Counter-Terrorists" then return track.group=="TGrenade" end
        return false
    end
    local function validVector(v)
        return typeof(v)=="Vector3" and finite(v.X) and finite(v.Y) and finite(v.Z)
    end
    local function calculateEndpoint(track,revision)
        local sim=getModule("Shared","GrenadeSimulator")
        if type(sim)~="table" or type(sim.createConfig)~="function" or type(sim.step)~="function" then return nil end
        local physics=track.physics
        if type(physics)~="table" or not validVector(track.pos) or not validVector(track.velocity) then return nil end
        local radius=tonumber(physics.Radius);if not finite(radius) then radius=0.5 end
        local fuse=tonumber(physics.FuseTime);if not finite(fuse) or fuse<=0 then fuse=nil else fuse=math.clamp(fuse,0.05,10) end
        local cfg=sim.createConfig(math.clamp(radius,0.05,4),1,false,fuse,nil,nil)
        if type(cfg)~="table" then return nil end
        local restitution=tonumber(physics.Restitution);if not finite(restitution) then restitution=0.4 end
        local maxBounces=tonumber(physics.MaxBounces);if not finite(maxBounces) then maxBounces=20 end
        cfg.restitution=math.clamp(restitution,0,1);cfg.maxBounces=math.clamp(math.floor(maxBounces),0,40)
        local rp=RaycastParams.new();rp.FilterType=Enum.RaycastFilterType.Exclude;rp.IgnoreWater=true;rp.RespectCanCollide=false
        local exclude={};local debris=Workspace:FindFirstChild("Debris")
        if debris then table.insert(exclude,debris) end
        if localPlayer.Character then table.insert(exclude,localPlayer.Character) end
        rp.FilterDescendantsInstances=exclude;pcall(function()rp.CollisionGroup=track.group or "Default" end)
        local constants=type(sim.Constants)=="table" and sim.Constants or {}
        local dt=tonumber(physics.Step) or tonumber(constants.FIXED_TIMESTEP) or 0.0078125
        if not finite(dt) then dt=0.0078125 end;dt=math.clamp(dt,0.001,0.05)
        local elapsed=tonumber(track.elapsed) or 0;if not finite(elapsed) then return nil end
        elapsed=math.clamp(elapsed,0,10)
        local stateBody={simulationTime=elapsed,bounceCount=track.bounces or 0,isGrounded=false,isAtRest=false,
            hasTouched=(track.bounces or 0)>0,accumulatedTime=0,position=track.pos,velocity=track.velocity,
            angularVelocity=Vector3.zero,timestamp=track.starttime,isJumpThrow=track.jump==true}
        local maxTime=tonumber(constants.MAX_SIMULATION_TIME) or 10;if not finite(maxTime) then maxTime=10 end
        local steps=math.min(1600,math.ceil(math.max(0,math.clamp(maxTime,0.1,10)-elapsed)/dt)+2)
        for i=1,steps do
            if not gui.Parent or not q.Flying or not q.HEThreat or eventTracks[track.id]~=track or track.revision~=revision then return nil end
            local nextBody,event=sim.step(stateBody,cfg,rp,dt)
            if type(nextBody)~="table" or not validVector(nextBody.position) then return nil end
            stateBody=nextBody
            if stateBody.isAtRest or (event and (type(event)~="table" or event.type~="bounce")) then return stateBody.position end
            if i%32==0 then task.wait() end
        end
        -- При превышении лимита шагов не называем промежуточную точку точкой взрыва.
        return nil
    end
    local function schedulePrediction(track,now)
        if predictBusy>=2 or track.running or not targetEnemy(track) or type(track.physics)~="table" or not validVector(track.velocity) then return end
        if track.predictedRevision==track.revision or now-(track.lastAttempt or -100)<2 then return end
        track.running=true;track.lastAttempt=now;predictBusy+=1;local revision=track.revision
        task.spawn(function()
            local ok,result=pcall(calculateEndpoint,track,revision)
            predictBusy=math.max(0,predictBusy-1);track.running=false
            if ok and validVector(result) and eventTracks[track.id]==track and track.revision==revision and q.Flying and q.HEThreat and gui.Parent then
                track.endpoint=result;track.predictedRevision=revision
            end
        end)
    end
    local function estimateDamage(track)
        if not targetEnemy(track) or not validVector(track.endpoint) then return nil end
        local character=localPlayer.Character
        if not character or not character:IsDescendantOf(Workspace) or character:GetAttribute("Dead")==true then return nil end
        local root=character.PrimaryPart or character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso")
        if not root or not root:IsA("BasePart") or not validVector(root.Position) then return nil end
        local delta=root.Position-track.endpoint;local distance=delta.Magnitude
        if not finite(distance) then return nil end
        local sim=getModule("Shared","GrenadeSimulator")
        local scale=type(sim)=="table" and type(sim.Constants)=="table" and tonumber(sim.Constants.SOURCE_TO_STUDS) or nil
        if not finite(scale) or scale<=0 then scale=0.0763888888888889 end
        local sourceDistance=distance/scale;if sourceDistance>350 then return nil end
        if distance>0.3 then
            local origin=track.endpoint+delta.Unit*0.2;local direction=root.Position-origin
            local exclude={character};local debris=Workspace:FindFirstChild("Debris");if debris then table.insert(exclude,debris) end
            damageRay.FilterDescendantsInstances=exclude
            local hit=Workspace:Raycast(origin,direction,damageRay)
            if hit and hit.Distance<direction.Magnitude-0.2 then return nil end
        end
        local raw=math.min(98,105*math.exp(-(((sourceDistance-25)/140)^2)))
        local armor=localPlayer:GetAttribute("Armor")
        if type(armor)=="string" then
            local ok,data=pcall(function()return game:GetService("HttpService"):JSONDecode(armor)end)
            armor=ok and type(data)=="table" and data.Health or nil
        end
        if type(armor)~="number" then armor=character:GetAttribute("Armor") end
        armor=tonumber(armor) or 0;if not finite(armor) then armor=0 end;armor=math.max(0,armor)
        if armor>0 then
            local reduced=raw*0.5
            raw=(raw-reduced)*0.5>armor and raw-armor/0.5 or reduced
        end
        local result=math.floor(raw+0.5)
        return result>=1 and result or nil
    end

    local eventHandlers={
        {"Projectile","Spawn",spawnEvent},{"Projectile","Bounce",bounceEvent},{"Projectile","Resolve",resolveEvent},
        {"VFX","CreateVoxelSmoke",function(p)upsertZone("smoke",p,false)end},
        {"VFX","DestroyVoxelSmoke",function(id)destroyZone("smoke",id)end},
        {"VFX","CreateVoxelFire",function(p)upsertZone("fire",p,false)end},
        {"VFX","UpdateVoxelFire",function(p)upsertZone("fire",p,true)end},
        {"VFX","DestroyVoxelFire",function(id)destroyZone("fire",id)end},
    }
    local function isConnection(v)
        return typeof(v)=="RBXScriptConnection" or (type(v)=="table" and type(v.Disconnect)=="function")
    end
    local function detach(name)
        local sub=subscriptions[name];if not sub then return end
        sub.active=false
        local stop=sub.stop
        if type(stop)=="function" then pcall(stop) elseif isConnection(stop) then pcall(stop.Disconnect,stop) end
        subscriptions[name]=nil
    end
    local function refreshEvents()
        local net=getModule("Database","Security","Remotes")
        for _,entry in ipairs(eventHandlers) do
            local group,name,handler=entry[1],entry[2],entry[3]
            local key=group.."."..name
            local category=net and net[group]
            local endpoint=type(category)=="table" and category[name] or nil
            local old=subscriptions[key]
            if old and old.endpoint~=endpoint then detach(key);old=nil end
            if not old and type(endpoint)=="table" and type(endpoint.Listen)=="function" and not unmanaged[endpoint] then
                local sub={endpoint=endpoint,active=false}
                local ok,stop=pcall(endpoint.Listen,function(packet)
                    if sub.active then state.enqueueGameEvent(handler,packet,function()return sub.active end) end
                end)
                if ok and (type(stop)=="function" or isConnection(stop)) then
                    sub.stop=stop;sub.active=true;subscriptions[key]=sub
                elseif ok then unmanaged[endpoint]=true end
            end
        end
    end
    local function stopEvents()
        for _,entry in ipairs(eventHandlers) do detach(entry[1].."."..entry[2]) end
        table.clear(eventTracks);table.clear(eventZones)
    end

    local last,lastWarn=0,0;local heartbeat,render
    heartbeat=RunService.Heartbeat:Connect(function()
        if not gui.Parent then
            heartbeat:Disconnect();if render then render:Disconnect() end;stopEvents();hideFills(true)
            for _,v in ipairs(lines) do v:Destroy() end;for _,v in ipairs(labels) do v:Destroy() end;return
        end
        local now=os.clock()
        if now-eventLast>=2 then eventLast=now;pcall(refreshEvents) end
        for id,track in pairs(eventTracks) do if now-track.created>12 then eventTracks[id]=nil end end
        for key,event in pairs(eventZones) do if now>=event.expires then eventZones[key]=nil end end
        if q.Flying and q.HEThreat then
            local damageBudget=4
            for _,track in pairs(eventTracks) do
                schedulePrediction(track,now)
                if damageBudget>0 and track.endpoint and track.predictedRevision==track.revision and now-(track.damageAt or -100)>=0.25 then
                    damageBudget-=1;local ok,value=pcall(estimateDamage,track)
                    track.damage=ok and value or nil;track.damageAt=now
                end
            end
        end
        if not q.Zones or not q.Fill then hideFills(false) end
        if not q.Flying and not q.Zones then table.clear(zones);table.clear(projectiles);return end
        if now-last<1 then return end;last=now
        local ok,err=pcall(scan)
        if not ok then table.clear(zones);table.clear(projectiles);hideFills(false);if now-lastWarn>5 then lastWarn=now;warn("[NOIR / Grenades] "..tostring(err)) end end
    end)
    render=RunService.RenderStepped:Connect(function()
        if not gui.Parent then return end
        local cam=Workspace.CurrentCamera;local usedLines,usedLabels=0,0
        local function text(pos,value,color)
            if not cam or typeof(pos)~="Vector3" then return end
            local p,onScreen=cam:WorldToViewportPoint(pos)
            if p.Z<=0 or not onScreen then return end
            usedLabels+=1;local l=label(usedLabels);l.Position=UDim2.fromOffset(p.X,p.Y);l.Text=value;l.TextColor3=color;l.Visible=true
        end
        if cam and q.Zones then
            for _,zone in ipairs(zones) do
                if (zone.instance and zone.instance.Parent) or (zone.event and eventZones[zone.event.key]==zone.event and zone.event.expires>os.clock()) then
                    local color=zone.kind=="smoke" and q.SmokeColor or q.FireColor
                    for i,a in ipairs(zone.points) do
                        local b=zone.points[i%#zone.points+1]
                        local p1=cam:WorldToViewportPoint(a);local p2=cam:WorldToViewportPoint(b)
                        if p1.Z>0 and p2.Z>0 then
                            usedLines+=1;local l=line(usedLines);local dx,dy=p2.X-p1.X,p2.Y-p1.Y
                            l.Position=UDim2.fromOffset((p1.X+p2.X)/2,(p1.Y+p2.Y)/2);l.Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),q.Width)
                            l.Rotation=math.deg(math.atan2(dy,dx));l.BackgroundColor3=color;l.Visible=true
                        end
                    end
                    local title=zone.kind=="smoke" and "SMOKE" or "FIRE"
                    local timed=zone.event or zone.timerEvent
                    if q.Timer and timed and eventZones[timed.key]==timed and timed.expires>os.clock() then
                        title=title..string.format(" · %.1fs",timed.expires-os.clock())
                    end
                    text(zone.center+Vector3.new(0,1.35,0),title,color)
                end
            end
        end
        if q.Flying then
            local seen={}
            for _,item in ipairs(projectiles) do
                local p=positionOf(item)
                if p then seen[item.Name]=true;text(p,tostring(item:GetAttribute("GrenadeName")),q.FlyingColor) end
            end
            local now=os.clock()
            for id,track in pairs(eventTracks) do
                if not seen[id] and now-track.at<=1.5 then text(track.pos,track.weapon.." · LAST",q.FlyingColor) end
                if q.HEThreat and track.endpoint and track.predictedRevision==track.revision then
                    local damage=track.damage
                    if damage and track.damageAt and now-track.damageAt<0.75 then text(track.endpoint,"HE LAND · ~"..tostring(damage).." DMG",q.FlyingColor) end
                end
            end
        end
        for i=usedLines+1,#lines do lines[i].Visible=false end
        for i=usedLabels+1,#labels do labels[i].Visible=false end
    end)
end

-- Knife/Zeus: только доступное локальное оружие, в пределах дистанции и при прямой видимости.
do
    local q={Knife=false,KnifeRange=3.5,KnifeHeavy=true,Zeus=false,ZeusRange=12}
    state.closeRange=q
    local ray=RaycastParams.new();ray.FilterType=Enum.RaycastFilterType.Exclude;ray.IgnoreWater=true
    pcall(function()ray.CollisionGroup="Bullet"end)
    local nextAttempt,lastWarn=0,0
    local function shootAt(weapon,cam,point,heavy,isKnife)
        local original=cam.CFrame
        local aimed=CFrame.lookAt(original.Position,point)
        if (point-original.Position).Magnitude<0.05 then return end
        local token={};state.closeRangeShot=token;cam.CFrame=aimed
        local function finish()
            if state.closeRangeShot~=token then return end
            state.closeRangeShot=nil
            pcall(function() if cam.Parent and cam.CFrame==aimed then cam.CFrame=original end end)
        end
        -- Если игровой shoot уступил управление, не держим камеру и блокировку бесконечно.
        task.delay(0.15,finish)
        local ok,err
        if isKnife then ok,err=pcall(weapon.shoot,weapon,heavy) else ok,err=pcall(weapon.shoot,weapon) end
        finish()
        if not ok and os.clock()-lastWarn>5 then lastWarn=os.clock();warn("[NOIR / Close range] "..tostring(err)) end
    end
    local connection
    connection=RunService.Heartbeat:Connect(function()
        if not gui.Parent then connection:Disconnect();return end
        local now=os.clock()
        if now<nextAttempt or state.closeRangeShot or state.redirected then return end
        if not q.Knife and not q.Zeus then return end
        if state.movement and state.movement.third then return end -- не меняем позицию камеры третьего лица
        local own=localPlayer.Character;local cam=Workspace.CurrentCamera;local characters=Workspace:FindFirstChild("Characters")
        local controller=state.rapid and state.rapid.controller
        if not (own and own.Parent and cam and characters and controller and type(controller.peekCurrentEquippedForMovement)=="function") then return end
        if own:GetAttribute("Dead")==true or localPlayer:GetAttribute("IsDefusingBomb")==true or localPlayer:GetAttribute("IsLocallyDefusingBomb")==true then return end
        local health=tonumber(own:GetAttribute("Health"));if health and health<=0 then return end
        local ok,weapon=pcall(controller.peekCurrentEquippedForMovement)
        if not ok or type(weapon)~="table" or weapon.Player~=localPlayer or weapon.IsDestroyed or weapon.IsShooting or weapon.IsReloading or type(weapon.shoot)~="function" then return end
        local props=weapon.Properties
        if type(props)~="table" then return end
        local knife=q.Knife and props.Class=="Melee"
        local zeus=q.Zeus and weapon.Name=="Zeus x27"
        if not knife and not zeus then return end
        if zeus and type(weapon.Rounds)=="number" and weapon.Rounds<=0 then return end
        local equippedAt=tonumber(weapon.WeaponEquippedTick)
        if equippedAt and tick()-equippedAt<=1 then return end
        local origin=cam.CFrame.Position
        local mine=localPlayer:GetAttribute("Team") or teamOf(own)
        local ffa=string.find(tostring(Workspace:GetAttribute("Gamemode")),"Deathmatch",1,true)~=nil
        ray.FilterDescendantsInstances={own,cam}
        local nearest,nearestPart,nearestDistance
        local limit=knife and q.KnifeRange or q.ZeusRange
        local weaponRange=tonumber(props.Range)
        if knife and weaponRange and weaponRange>0 then limit=math.min(limit,weaponRange) end
        for _,model in ipairs(characters:GetChildren()) do
            if isEnemy(model,own,ffa,mine) then
                local hp=tonumber(model:GetAttribute("Health"))
                local target=model:FindFirstChild("Head") or model:FindFirstChild("UpperTorso") or model.PrimaryPart
                if (not hp or hp>0) and target and target:IsA("BasePart") then
                    local delta=target.Position-origin;local distance=delta.Magnitude
                    if distance>0.05 and distance<=limit and (not nearestDistance or distance<nearestDistance) then
                        local hit=Workspace:Raycast(origin,delta,ray)
                        local hitPart=safeHitInstance(hit)
                        if not hit or (hitPart and hitPart:IsDescendantOf(model)) then nearest,nearestPart,nearestDistance=model,target,distance end
                    end
                end
            end
        end
        if not nearestPart then return end
        local heavy=false
        if knife and q.KnifeHeavy then
            local root=nearest.PrimaryPart or nearest:FindFirstChild("HumanoidRootPart")
            local ownRoot=own.PrimaryPart or own:FindFirstChild("HumanoidRootPart")
            if root and ownRoot and root:IsA("BasePart") and ownRoot:IsA("BasePart") then
                local delta=ownRoot.Position-root.Position
                if delta.Magnitude>0.05 then heavy=root.CFrame.LookVector:Dot(delta.Unit)<math.cos(math.rad(100)) end
            end
        end
        local delay=knife and 0.6 or 1.5
        local timing=getModule("Components","Common","WeaponTimings")
        if timing and type(timing.MinShotInterval)=="function" then
            local valid,value=pcall(timing.MinShotInterval,props)
            if valid and type(value)=="number" and value>0 and value<math.huge then delay=math.max(delay,value) end
        end
        nextAttempt=now+math.clamp(delay,0.15,5)
        task.spawn(shootAt,weapon,cam,nearestPart.Position,heavy,knife)
    end)
end

-- Упрощённый Anti Aim Shitaro: меняет команды MovementV2, не CFrame камеры.
do
    local q={Enabled=false,Yaw="Backward",Jitter=45,SpinSpeed=360,Pitch="Off",AirSpin=false,AirSpeed=450,AirPitch="Off",FakeDuck=false,DuckRate=4,Manual="Off",ManualAngle=90,FaceEnemy=false,Freestanding=false}
    state.antiAim=q
    local epoch=os.clock()
    local grenades={["HE Grenade"]=true,Flashbang=true,["Smoke Grenade"]=true,["Decoy Grenade"]=true,["Incendiary Grenade"]=true,Molotov=true,C4=true}
    -- Доступ к Instance только из Heartbeat, не из SampleInput на игровом потоке.
    local context={alive=false,allowed=false,reason="waiting for context",character=nil}
    -- Выбираем направление по ближайшему врагу; проверка укрытия выполняется вне SampleInput.
    local coverRay=RaycastParams.new();coverRay.FilterType=Enum.RaycastFilterType.Exclude
    coverRay.IgnoreWater=true;coverRay.RespectCanCollide=false
    local lastCover,lastSwitch=0,0
    local function updateCover(now)
        if not q.FaceEnemy and not q.Freestanding then context.enemyYaw=nil;context.coverSide=0;return end
        if now-lastCover<0.15 then return end;lastCover=now
        local own=context.character
        local root=own and (own.PrimaryPart or own:FindFirstChild("HumanoidRootPart"))
        if not root or not root:IsA("BasePart") then context.enemyYaw=nil;context.coverSide=0;return end
        local pos=root.Position;local myTeam=localPlayer:GetAttribute("Team")
        local ffa=Workspace:GetAttribute("Gamemode")=="Deathmatch"
        local nearest,best,enemyRoot=nil,math.huge,nil
        for _,player in ipairs(Players:GetPlayers()) do
            if player~=localPlayer then
                local team=player:GetAttribute("Team");local model=player.Character
                if (ffa or (myTeam~=nil and team~=nil and myTeam~=team)) and model and model:IsDescendantOf(Workspace) and model:GetAttribute("Dead")~=true then
                    local part=model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
                    if part and part:IsA("BasePart") then
                        local distance=(part.Position-pos).Magnitude
                        if distance<best and distance<1000 then nearest,best,enemyRoot=model,distance,part end
                    end
                end
            end
        end
        if not enemyRoot then context.enemyYaw=nil;context.coverSide=0;return end
        local delta=enemyRoot.Position-pos
        if delta.Magnitude<0.05 then context.enemyYaw=nil;context.coverSide=0;return end
        local yaw=math.atan2(delta.X,delta.Z);context.enemyYaw=yaw
        if not q.Freestanding then context.coverSide=0;return end
        local head=nearest:FindFirstChild("Head")
        local from=head and head:IsA("BasePart") and head.Position or enemyRoot.Position+Vector3.new(0,1.8,0)
        local origin=pos+Vector3.new(0,1.8,0);local side=Vector3.new(-math.cos(yaw),0,math.sin(yaw))
        local excluded={own,nearest};local characters=Workspace:FindFirstChild("Characters")
        if characters then table.insert(excluded,characters) end
        coverRay.FilterDescendantsInstances=excluded
        local function clear(a,b)
            local direction=b-a
            if direction.Magnitude<0.01 then return true end
            return Workspace:Raycast(a,direction,coverRay)==nil
        end
        local choice=0
        for _,distance in ipairs({2,4.5}) do
            local l=clear(from,origin-side*distance);local r=clear(from,origin+side*distance)
            if l~=r then choice=l and 1 or -1;break end
            if l and r then break end
        end
        if choice==0 then
            local leftBlocked=not clear(origin,origin-side*3.5)
            local rightBlocked=not clear(origin,origin+side*3.5)
            if leftBlocked~=rightBlocked then choice=leftBlocked and -1 or 1 end
        end
        local old=context.coverSide or 0
        if choice==0 or old==0 or choice==old or now-lastSwitch>=0.25 then
            if choice~=old then lastSwitch=now end
            context.coverSide=choice
        end
    end

    local function updateContext()
        if not gui.Parent then context.alive=false;context.allowed=false;return end
        context.alive=true;context.character=localPlayer.Character
        if not q.Enabled then context.allowed=false;context.reason="disabled";return end
        if not context.character then context.allowed=false;context.reason="waiting for character";return end
        if localPlayer:GetAttribute("IsDefusingBomb")==true or localPlayer:GetAttribute("IsLocallyDefusingBomb")==true or localPlayer:GetAttribute("IsPlantingBomb")==true then
            context.allowed=false;context.reason="plant / defuse";return
        end
        if localPlayer:GetAttribute("IsSniperScoped")==true then context.allowed=false;context.reason="scoped";return end
        local getter=state.rapid and state.rapid.controller and state.rapid.controller.peekCurrentEquippedForMovement
        if type(getter)~="function" then context.allowed=false;context.reason="waiting for inventory";return end
        local ok,weapon=pcall(getter)
        if not ok or type(weapon)~="table" or weapon.IsDestroyed then context.allowed=false;context.reason="waiting for weapon";return end
        if weapon.IsShooting or weapon.IsReloading then context.allowed=false;context.reason="firing / reloading";return end
        if grenades[weapon.Name] then context.allowed=false;context.reason="grenade / bomb";return end
        context.allowed=true;context.reason="ready"
        local ok=pcall(updateCover,os.clock())
        if not ok then context.enemyYaw=nil;context.coverSide=0 end
    end
    local lastContext=0;local ctxConnection
    ctxConnection=RunService.Heartbeat:Connect(function()
        if not gui.Parent then context.alive=false;context.allowed=false;ctxConnection:Disconnect();return end
        local now=os.clock();if now-lastContext<0.05 then return end;lastContext=now
        local ok=pcall(updateContext)
        if not ok then context.allowed=false;context.reason="context unavailable" end
    end)
    q.GetStatus=function()
        if not q.Enabled then return "Anti Aim: off" end
        local movement=state.movement
        if not movement or not movement.bhopReady then return "Anti Aim: input hook unavailable" end
        local now=os.clock()
        if not movement.lastInputAt or now-movement.lastInputAt>2 then return "Anti Aim: waiting for SampleInput" end
        if not context.allowed then return "Anti Aim: "..context.reason end
        if q.LastError and now-(q.LastErrorAt or 0)<3 then return "Anti Aim: input error" end
        if not q.LastApplied or now-q.LastApplied>2 then return "Anti Aim: input not applied" end
        return "Anti Aim: commands applied ("..tostring(movement.hookKind or "hook")..")"
    end

    function state.applyAntiAim(character,command)
        if not q.Enabled or not context.alive or not context.allowed or type(character)~="table" or type(command)~="table" then return end
        if character.Player and character.Player~=localPlayer then return end
        if character.Character and context.character and character.Character~=context.character then return end
        if state.closeRangeShot or state.redirected then return end
        local yaw=tonumber(command.LookYaw);if not yaw then return end
        local ms=type(character.MovementState)=="table" and character.MovementState or nil
        if ms and ms.MovementMode and ms.MovementMode~="Walking" then return end
        local airborne=ms and ms.OnGround==false
        local mode=airborne and q.AirSpin and "Spin" or q.Yaw
        local pitch=airborne and q.AirSpin and q.AirPitch or q.Pitch
        local output=yaw;local now=os.clock()
        local base=(q.FaceEnemy and context.enemyYaw) or yaw+math.pi
        local autoSide=q.Freestanding and context.coverSide or 0
        if q.Manual~="Off" and not (airborne and q.AirSpin) then
            output=base+math.rad(math.clamp(q.ManualAngle,0,180))*(q.Manual=="Left" and -1 or 1)
        elseif autoSide~=0 and not (airborne and q.AirSpin) then
            output=(context.enemyYaw or base)+math.rad(math.clamp(q.ManualAngle,0,180))*autoSide
        elseif mode=="Backward" then output=base
        elseif mode=="Spin" then output=yaw+math.rad((now-epoch)*(airborne and q.AirSpin and q.AirSpeed or q.SpinSpeed)%360)
        elseif mode=="Jitter" then
            local side=math.floor(now*10)%2==0 and 1 or -1
            output=base+math.rad(math.clamp(q.Jitter,0,180)*side)
        end
        command.LookYaw=math.atan2(math.sin(output),math.cos(output))
        if pitch=="Up" then command.VerticalLook=1
        elseif pitch=="Down" then command.VerticalLook=-1
        elseif pitch=="Jitter" then command.VerticalLook=math.floor(now*10)%2==0 and 1 or -1 end
        if typeof(command.Move)=="Vector2" then
            local delta=output-yaw;local c,s=math.cos(delta),math.sin(delta);local m=command.Move
            command.Move=Vector2.new(m.X*c-m.Y*s,m.X*s+m.Y*c)
        end
        if q.FakeDuck and type(command.Buttons)=="number" then
            local phase=math.floor(now*2*math.clamp(q.DuckRate,1,12))%2==1
            command.Buttons=phase and bit32.bor(command.Buttons,2) or bit32.band(command.Buttons,bit32.bnot(2))
        end
        q.LastApplied=now
    end
end

-- Локальное скрытие отдельных элементов viewmodel / прицела; не меняет модели других игроков.
do
    local q={HideHands=false,HideScope=false};state.removals=q
    local hidden=setmetatable({},{__mode="k"});local scope,scopeProperty,scopeOriginal
    local function isHand(part,model)
        local p=part
        while p and p~=model do
            local name=p.Name
            if name=="Left Arm" or name=="Right Arm" or name=="Arms" or name=="Glove" or name=="Sleeve" or name:find("Hand",1,true) then return true end
            p=p.Parent
        end
        return false
    end
    local function restoreParts(seen)
        for part,value in pairs(hidden) do
            if not seen[part] then
                pcall(function()if part.LocalTransparencyModifier==1 then part.LocalTransparencyModifier=value end end)
                hidden[part]=nil
            end
        end
    end
    local function updateHands()
        local seen={}
        if q.HideHands and not (state.movement and state.movement.third) then
            local ctrl=state.rapid and state.rapid.controller;local get=ctrl and ctrl.peekCurrentEquippedForMovement
            local ok,weapon=pcall(get or function()end)
            local model=ok and type(weapon)=="table" and weapon.Viewmodel and weapon.Viewmodel.Model
            if model and model.Parent then
                for _,part in ipairs(model:GetDescendants()) do
                    if part:IsA("BasePart") and isHand(part,model) then
                        seen[part]=true
                        if hidden[part]==nil then hidden[part]=part.LocalTransparencyModifier end
                        part.LocalTransparencyModifier=1
                    end
                end
            end
        end
        restoreParts(seen)
    end
    local function restoreScope()
        if scope and scopeProperty and scopeOriginal~=nil then
            pcall(function()
                if scope.Parent and scope[scopeProperty]==false then
                    scope[scopeProperty]=scopeOriginal and localPlayer:GetAttribute("IsSniperScoped")==true or false
                end
            end)
        end
        scope,scopeProperty,scopeOriginal=nil,nil,nil
    end
    local function updateScope()
        if not q.HideScope or localPlayer:GetAttribute("IsSniperScoped")~=true then restoreScope();return end
        local node=localPlayer:FindFirstChild("PlayerGui")
        for _,name in ipairs({"MainGui","Gameplay","Middle","SniperScope"}) do node=node and node:FindFirstChild(name) end
        local property=node and (node:IsA("GuiObject") and "Visible" or (node:IsA("LayerCollector") and "Enabled" or nil))
        if node~=scope or property~=scopeProperty then restoreScope();scope=node;scopeProperty=property end
        if scope and scopeProperty and scope[scopeProperty]==true then
            if scopeOriginal==nil then scopeOriginal=true end
            scope[scopeProperty]=false
        end
    end
    local last,lastWarn=0,0;local connection
    connection=RunService.Heartbeat:Connect(function()
        if not gui.Parent then connection:Disconnect();pcall(restoreScope);pcall(restoreParts,{});return end
        local now=os.clock();if now-last<0.1 then return end;last=now
        for _,fn in ipairs({updateHands,updateScope}) do
            local ok,err=pcall(fn)
            if not ok and now-lastWarn>5 then lastWarn=now;warn("[NOIR / Removals] "..tostring(err)) end
        end
    end)
end

-- Звуки и частицы для существующей эвристики локального попадания; это не серверный hit-confirm.
do
    local SoundService=game:GetService("SoundService")
    local Debris=game:GetService("Debris")
    local q={HitSound=false,KillSound=false,HitId="",KillId="",HitVolume=1,KillVolume=1,
        HitParticles=false,KillParticles=false,HitColor=Color3.fromRGB(133,220,255),KillColor=Color3.fromRGB(255,120,100)}
    state.feedbackExtras=q
    local oldEnabled,oldFeedback=state.feedbackEnabled,state.showHitFeedback
    state.feedbackEnabled=function()
        return (oldEnabled and oldEnabled()) or q.HitSound or q.KillSound or q.HitParticles or q.KillParticles
    end
    local lastSound=0
    local function asset(text)
        if type(text)~="string" then text=tostring(text or "") end
        local id=text:match("^%s*(%d+)%s*$") or text:match("^%s*rbxassetid://(%d+)%s*$")
        if not id or #id>20 then return nil end
        return "rbxassetid://"..id
    end
    local function sound(killed)
        local input=killed and q.KillInput or q.HitInput
        local id=killed and q.KillId or q.HitId
        if input and type(input.Get)=="function" then local ok,value=pcall(input.Get,input);if ok then id=value end end
        id=asset(id);if not id or os.clock()-lastSound<0.05 then return end
        lastSound=os.clock()
        local s=Instance.new("Sound");s.Name="NoirHitSound";s.SoundId=id
        s.Volume=math.clamp(killed and q.KillVolume or q.HitVolume,0,3);s.Looped=false;s.Parent=SoundService
        Debris:AddItem(s,6);s:Play()
    end
    local function particles(model,killed,position)
        if typeof(position)~="Vector3" then
            if not model or not model.Parent then return end
            local target=model:FindFirstChild("Head") or model:FindFirstChild("UpperTorso") or model.PrimaryPart
            if not target or not target:IsA("BasePart") then return end
            position=target.Position
        end
        local part=Instance.new("Part");part.Name="NoirHitParticles";part.Anchored=true;part.CanCollide=false;part.CanTouch=false;part.CanQuery=false;part.CastShadow=false;part.Transparency=1
        part.Size=Vector3.new(0.05,0.05,0.05);part.CFrame=CFrame.new(position);part.Parent=Workspace
        local emitter=Instance.new("ParticleEmitter");emitter.Name="NoirHitEmitter";emitter.Enabled=false
        emitter.Texture="rbxassetid://18540695516";emitter.Color=ColorSequence.new(killed and q.KillColor or q.HitColor)
        emitter.Lifetime=NumberRange.new(0.5,1);emitter.Speed=NumberRange.new(12,16);emitter.SpreadAngle=Vector2.new(50,50)
        emitter.Acceleration=Vector3.new(0,-50,0);emitter.LightEmission=1;emitter.Size=NumberSequence.new(0.5);emitter.Parent=part
        Debris:AddItem(part,2);emitter:Emit(24)
    end
    state.showHitFeedback=function(model,before,after,position)
        if oldFeedback then pcall(oldFeedback,model,before,after) end
        if not gui.Parent then return end
        local killed=after<=0
        if killed and q.KillSound or not killed and q.HitSound then pcall(sound,killed) end
        if killed and q.KillParticles or not killed and q.HitParticles then pcall(particles,model,killed,position) end
    end
end

-- MovementV2: одношаговое предсказание аналогично Shitaro, без телепортации и изменения скорости.
do
    local q={EdgeJump=false,JumpBug=false,EdgeBug=false,PixelSurf=false,Ready=false};state.movementPrediction=q
    local captured={};local sim,cloner,settings,serial,runtimeModule
    local advanceOld,advanceWrapper,composeOld,composeWrapper
    local pending=false;local lastCharacter;local lastWarn=0
    local pixelNormal,pixelAt=nil,0
    local function clear()pending=false;lastCharacter=nil;pixelNormal=nil;pixelAt=0 end
    local function restore()
        if runtimeModule then
            pcall(function()if runtimeModule.advance==advanceWrapper then runtimeModule.advance=advanceOld end end)
            pcall(function()if runtimeModule._composeWorld==composeWrapper then runtimeModule._composeWorld=composeOld end end)
        end
        q.Ready=false;clear();table.clear(captured)
    end
    local function install()
        local s=getModule("MovementV2","Simulation")
        local c=getModule("MovementV2","Simulation","State")
        local cfg=getModule("MovementV2","Simulation","RuntimeSettings")
        local ser=getModule("MovementV2","Serial")
        local rt=getModule("MovementV2","Client","Runtime")
        if not (s and c and cfg and ser and rt and type(s.step)=="function" and type(c.clone)=="function" and type(c.cloneSupport)=="function" and type(cfg.getMovementConfig)=="function" and type(ser.addUInt32)=="function" and type(rt.advance)=="function" and type(rt._composeWorld)=="function") then return false end
        local oldAdvance,oldCompose=rt.advance,rt._composeWorld
        local newAdvance=function(self,...)
            captured.runtime=self
            return oldAdvance(self,...)
        end
        local newCompose=function(self,tick,...)
            local result=table.pack(oldCompose(self,tick,...))
            if result[1]~=nil then captured.world=result[1];captured.tick=tick;captured.owner=self end
            return table.unpack(result,1,result.n)
        end
        local installed=pcall(function() rt.advance=newAdvance;rt._composeWorld=newCompose end)
        if not installed or rt.advance~=newAdvance or rt._composeWorld~=newCompose then
            pcall(function() if rt.advance==newAdvance then rt.advance=oldAdvance end end)
            pcall(function() if rt._composeWorld==newCompose then rt._composeWorld=oldCompose end end)
            return false
        end
        sim,cloner,settings,serial,runtimeModule=s,c,cfg,ser,rt
        advanceOld,advanceWrapper,composeOld,composeWrapper=oldAdvance,newAdvance,oldCompose,newCompose
        q.Ready=true;return true
    end
    task.spawn(function()
        while gui.Parent and not q.Ready do
            local ok,result=pcall(install)
            if ok and result then break end
            task.wait(2)
        end
    end)
    local function predict(snapshot,current,cmd,buttons)
        if not q.Ready or type(snapshot)~="table" or type(current)~="table" or type(snapshot.Support)~="table" then return end
        local runtime=captured.runtime
        if type(runtime)~="table" or rawget(runtime,"_started")~=true then return end
        local mapping=rawget(runtime,"_mapping")
        if type(mapping)~="table" or type(snapshot.Mapping)~="table" or mapping.Generation~=snapshot.Mapping.Generation then return end
        local tick=tonumber(snapshot.ServerTick)
        if not tick or captured.owner~=runtime or captured.tick~=tick then return end
        local world=captured.world
        if type(world)~="table" or type(world.Composed)~="table" or type(world.Composed.Query)~="table" then return end
        local hz=tonumber(snapshot.Mapping.SimulationHz);if not hz then return end
        local config=settings.getMovementConfig(hz);if type(config)~="table" then return end
        local stream=rawget(runtime,"_commandStream")
        if type(stream)~="table" or type(stream.lastSampledCommandNumber)~="function" or type(runtime._resolveSupportMotion)~="function" then return end
        local number=serial.addUInt32(stream:lastSampledCommandNumber() or 4294967295,1)
        local cloned=cloner.clone(current);local support=cloner.cloneSupport(snapshot.Support)
        if type(cloned)~="table" or type(support)~="table" then return end
        local step=math.clamp(tonumber(snapshot.StepSeconds) or 0.015625,0.001,0.05)
        local move=typeof(cmd.Move)=="Vector2" and cmd.Move or Vector2.zero
        local yaw=tonumber(cmd.LookYaw) or tonumber(current.LookYaw) or 0
        local vertical=tonumber(cmd.VerticalLook) or tonumber(current.VerticalLook) or 0
        local tau=2*math.pi
        local quantizedYaw=math.round((yaw%tau)/tau*65536)%65536/65536*tau
        if quantizedYaw>=math.pi then quantizedYaw-=tau end
        local packet={CommandNumber=number,Move=Vector2.new(math.round(math.clamp(move.X,-1,1)*127)/127,math.round(math.clamp(move.Y,-1,1)*127)/127),
            LookYaw=quantizedYaw,VerticalLook=math.round(math.clamp(vertical,-1,1)*127)/127,Buttons=buttons}
        local motion=runtime:_resolveSupportMotion(world,cloned,support)
        local nextState,nextSupport,events=sim.step(cloned,support,packet,step,world.Composed.Query,motion,config,nil)
        if type(nextState)~="table" or type(nextSupport)~="table" or type(events)~="table" then return end
        return nextState,events
    end
    -- Как в Shitaro, сначала проверяем вход без прыжка/приседа, затем ограниченный набор направлений.
    local edgeCandidates={Vector2.zero}
    for i=0,15 do local angle=2*math.pi*i/16;edgeCandidates[#edgeCandidates+1]=Vector2.new(math.cos(angle),math.sin(angle)) end
    local function isEdgeBug(before,after,event,gravity,step)
        if event.Landed or event.StartSolid or before.OnGround==true or after.OnGround==true then return false end
        local a,b=before.Velocity,after.Velocity
        if typeof(a)~="Vector3" or typeof(b)~="Vector3" or typeof(before.Position)~="Vector3" or typeof(after.Position)~="Vector3" or a.Y>=-4 then return false end
        if math.abs(b.Y)>math.max(1.25,math.abs(gravity)*step*1.35) or b.Y<=a.Y+4 then return false end
        return after.Position.Y<=before.Position.Y+0.05
    end
    local function findEdgeBug(snapshot,current,command)
        local config=settings.getMovementConfig(tonumber(snapshot.Mapping.SimulationHz))
        if type(config)~="table" then return end
        local gravity=tonumber(config.Gravity) or 60;local step=math.clamp(tonumber(snapshot.StepSeconds) or 0.015625,0.001,0.05)
        local baseMove=typeof(command.Move)=="Vector2" and command.Move or Vector2.zero
        local baseButtons=bit32.band(command.Buttons,bit32.bnot(bit32.bor(1,2)))
        local input=table.clone(command);input.Move=baseMove
        local nextState,event=predict(snapshot,current,input,baseButtons)
        if not nextState then return end
        if isEdgeBug(current,nextState,event,gravity,step) then return baseMove,false end
        if not event.Landed then return end
        local candidates={{move=baseMove,dist=0}}
        for _,move in ipairs(edgeCandidates) do
            local dx,dy=move.X-baseMove.X,move.Y-baseMove.Y
            candidates[#candidates+1]={move=move,dist=math.sqrt(dx*dx+dy*dy)}
        end
        table.sort(candidates,function(a,b)return a.dist<b.dist end)
        local bestMove,bestDuck,bestCost
        for pass=1,2 do
            local duck=pass==2;local buttons=duck and bit32.bor(baseButtons,2) or baseButtons
            for index,item in ipairs(candidates) do
                local cost=item.dist+(duck and 0.25 or 0)
                if bestCost and cost>=bestCost then break end
                if pass~=1 or index~=1 then
                    input.Move=item.move
                    local nextState,event=predict(snapshot,current,input,buttons)
                    if nextState and isEdgeBug(current,nextState,event,gravity,step) then
                        bestMove,bestDuck,bestCost=item.move,duck,cost;break
                    end
                end
            end
        end
        return bestMove,bestDuck
    end
    -- Ограниченный Pixel Surf assist: поддержание движения вдоль края при нахождении на земле.
    -- Захват края в воздухе, как в полной версии Shitaro, здесь не реализован.
    local function pixelRide(snapshot,current,command)
        if current.OnGround~=true or typeof(current.Position)~="Vector3" or typeof(current.Velocity)~="Vector3" or typeof(command.Move)~="Vector2" then pixelNormal=nil;return end
        if bit32.band(command.Buttons,1)~=0 then pixelNormal=nil;return end
        local rt=captured.runtime;local world=captured.world
        if type(snapshot)~="table" or type(snapshot.Mapping)~="table" or captured.owner~=rt or captured.tick~=tonumber(snapshot.ServerTick) or type(world)~="table" or type(world.Composed)~="table" then return end
        local query=world.Composed.Query
        if type(query)~="table" or type(query.IsClear)~="function" or type(query.FindGround)~="function" then return end
        local cfg=settings.getMovementConfig(tonumber(snapshot.Mapping.SimulationHz));if type(cfg)~="table" then return end
        local stance=current.Stance=="Ducking" and "Ducking" or "Standing"
        local size=stance=="Ducking" and cfg.PlayerSizeDucking or cfg.PlayerSizeStanding
        local half=typeof(size)=="Vector3" and size.X*0.5 or 1.2
        local stepHeight=(tonumber(cfg.MaxStepHeight) or 1.35)+0.15
        local now=os.clock()
        if not pixelNormal or now-pixelAt>0.08 then
            pixelAt=now;local x,z=0,0
            for i=0,7 do
                local angle=math.pi*i/4;local dx,dz=math.cos(angle),math.sin(angle)
                local probe=current.Position+Vector3.new(dx,0,dz)*(half*2+0.35)
                local clear=query:IsClear(probe,stance,1)
                if clear==true and query:FindGround(probe,stance,stepHeight,1)==nil then x+=dx;z+=dz end
            end
            local magnitude=math.sqrt(x*x+z*z)
            pixelNormal=magnitude>0.3 and Vector3.new(x/magnitude,0,z/magnitude) or nil
        end
        local normal=pixelNormal;if not normal then return end
        local yaw=tonumber(command.LookYaw) or tonumber(current.LookYaw) or 0
        local sy,cy=math.sin(yaw),math.cos(yaw);local input=command.Move
        local wish=Vector3.new(cy*input.X+sy*input.Y,0,-sy*input.X+cy*input.Y)
        if wish:Dot(normal)<-0.7 then return end
        local tangent=Vector3.new(-normal.Z,0,normal.X)
        local along=wish:Dot(tangent)
        if math.abs(along)<0.05 then along=current.Velocity:Dot(tangent) end
        if math.abs(along)<0.05 then return end
        local dir=tangent*(along>0 and 1 or -1)-normal*0.18
        local localMove=Vector2.new(cy*dir.X-sy*dir.Z,sy*dir.X+cy*dir.Z)
        local simulated=table.clone(command);simulated.Move=localMove
        local nextState,events=predict(snapshot,current,simulated,bit32.band(command.Buttons,bit32.bnot(1)))
        if nextState and nextState.OnGround==true and not events.StartSolid then return localMove end
    end
    local function safeSimulation(fn,...)
        local result=table.pack(pcall(fn,...))
        if not result[1] then
            local message=tostring(result[2])
            if message:find("lacking capability",1,true) or message:find("cannot access",1,true) then q.Blocked=true;q.BlockReason=message end
        end
        return table.unpack(result,1,result.n)
    end
    q.GetStatus=function()
        if q.Blocked then return "Prediction: restricted; turn all prediction toggles off to retry" end
        if not (q.EdgeJump or q.JumpBug or q.EdgeBug or q.PixelSurf) then return "Prediction: off" end
        if not q.Ready then return "Prediction: waiting for MovementV2" end
        return "Prediction: ready (requires compatible input thread)"
    end
    function state.applyMovementPrediction(character,snapshot,command)
        local ctx=state.movement and state.movement.context
        if not (q.EdgeJump or q.JumpBug or q.EdgeBug or q.PixelSurf) or q.Blocked or not ctx or not ctx.alive or ctx.blocked then clear();return end
        if type(character)~="table" or type(command)~="table" then return end
        if character.Player and character.Player~=localPlayer then return end
        if character.Character and ctx.character and character.Character~=ctx.character then return end
        local current=type(snapshot)=="table" and snapshot.State or character.MovementState
        if type(current)~="table" or (current.MovementMode~=nil and current.MovementMode~="Walking") or type(command.Buttons)~="number" then clear();return end
        local identity=character.Character or ctx.character or character
        if identity~=lastCharacter then pending=false;pixelNormal=nil;pixelAt=0;lastCharacter=identity end
        if not q.JumpBug then pending=false end
        if pending then
            pending=false
            if q.JumpBug and current.OnGround==true then
                command.Buttons=bit32.bor(bit32.band(command.Buttons,bit32.bnot(2)),1)
                return
            end
        end
        if not q.Ready then
            local now=os.clock();if now-lastWarn>10 then lastWarn=now;warn("[NOIR / Movement] MovementV2 prediction unavailable; prediction-based movement is inactive") end
            return
        end
        if q.PixelSurf and current.OnGround==true then
            local ok,move=safeSimulation(pixelRide,snapshot,current,command)
            if ok and typeof(move)=="Vector2" then command.Move=move;return end
        else pixelNormal=nil end
        if q.EdgeJump and current.OnGround==true then
            local buttons=bit32.band(command.Buttons,bit32.bnot(1))
            local ok,nextState,events=safeSimulation(predict,snapshot,current,command,buttons)
            if ok and nextState and events.LeftGround and not events.Jumped and nextState.OnGround~=true then
                command.Buttons=bit32.bor(command.Buttons,1)
            end
        elseif current.OnGround==false and typeof(current.Velocity)=="Vector3" and current.Velocity.Y< -4 then
            local found=false
            if q.EdgeBug and type(snapshot)=="table" and type(snapshot.Mapping)=="table" then
                local ok,move,duck=safeSimulation(findEdgeBug,snapshot,current,command)
                if ok and typeof(move)=="Vector2" then
                    command.Move=move
                    command.Buttons=bit32.band(command.Buttons,bit32.bnot(bit32.bor(1,2)))
                    if duck then command.Buttons=bit32.bor(command.Buttons,2) end
                    found=true
                end
            end
            if not found and q.JumpBug then
                local buttons=bit32.bor(bit32.band(command.Buttons,bit32.bnot(1)),2)
                local ok,nextState,events=safeSimulation(predict,snapshot,current,command,buttons)
                if ok and nextState and events.Landed then command.Buttons=buttons;pending=true end
            end
        end
    end
    local reportedBlock=false
    local con;con=RunService.Heartbeat:Connect(function()
        if not gui.Parent then con:Disconnect();restore();return end
        if q.Blocked and not reportedBlock then reportedBlock=true;warn("[NOIR / Movement] Prediction paused: "..tostring(q.BlockReason)) end
        if q.Blocked and not (q.EdgeJump or q.JumpBug or q.EdgeBug or q.PixelSurf) then q.Blocked=false;q.BlockReason=nil;reportedBlock=false end
    end)
end

-- Индикатор оценки пробития по игровым лучам, не является подтверждением сервера.
do
    local q={Enabled=false,YesColor=Color3.fromRGB(50,255,115),NoColor=Color3.fromRGB(255,65,75),Size=12};state.penIndicator=q
    local mark=Instance.new("Frame");mark.Name="NoirPenIndicator";mark.AnchorPoint=Vector2.new(0.5,0.5)
    mark.Position=UDim2.fromScale(0.5,0.5);mark.BorderSizePixel=0;mark.BackgroundTransparency=0.35;mark.ZIndex=6;mark.Visible=false;mark.Parent=overlay
    local last=0;local conn
    conn=RunService.Heartbeat:Connect(function()
        if not gui.Parent then conn:Disconnect();mark:Destroy();return end
        if not q.Enabled then mark.Visible=false;return end
        local now=os.clock();if now-last<0.1 then return end;last=now
        mark.Visible=false
        local ok,result=pcall(function()
            local cam=Workspace.CurrentCamera;local ray,ignoreFn=state.wallRay,state.wallIgnore
            local ctrl=state.rapid and state.rapid.controller;local getter=ctrl and ctrl.peekCurrentEquippedForMovement
            if not (cam and state.wallReady and ray and type(ray.cast)=="function" and type(ray.castThrough)=="function" and type(ignoreFn)=="function" and type(getter)=="function") then return nil end
            local weapon=getter();local props=type(weapon)=="table" and weapon.Properties
            if not (type(props)=="table" and props.Class=="Weapon" and not weapon.IsDestroyed and weapon.IsEquipped~=false) then return nil end
            local range=math.clamp(tonumber(props.Range) or 500,0,5000);if range<=0 then return nil end
            local pen=math.max(0,tonumber(props.Penetration) or 0)
            local ignore=ignoreFn();if type(ignore)~="table" then return nil end
            local origin,dir=cam.CFrame.Position,cam.CFrame.LookVector
            local first=ray.cast(origin,dir*range,nil,ignore)
            if type(first)~="table" or not first.instance or typeof(first.position)~="Vector3" then return nil end
            if pen<=0 then return false end
            local entries=ray.castThrough(first.position-dir*0.001,dir*(pen+0.001),pen,ignore,nil)
            if type(entries)~="table" then return nil end
            return type(entries[1])=="table" and type(entries[2])=="table" and entries[1].instance==first.instance and entries[2].instance==first.instance
        end)
        if ok and type(result)=="boolean" then
            mark.Size=UDim2.fromOffset(q.Size,q.Size);mark.BackgroundColor3=result and q.YesColor or q.NoColor;mark.Visible=true
        end
    end)
end

-- Локальный preview ножа/перчаток только для собственного Viewmodel; инвентарь и сервер не меняются.
do
    local q={Enabled=false,KnifeModel="Stock",GloveModel="Stock",KnifeSkin="Stock",GloveSkin="Stock",Ready=false}
    state.skinPreview=q
    local installed,lib={},nil;local warningAt=0
    local knife={['Butterfly Knife']=true,Karambit=true,['M9 Bayonet']=true,['Flip Knife']=true,['Gut Knife']=true,['Skeleton Knife']=true,['Stiletto Knife']=true,LightSaber=true}
    local glove={['Sports Gloves']=true,['Driver Gloves']=true,['Operator Gloves']=true,['Hand Wraps']=true}
    local mapping={['T Knife']={'Terrorists','Knife'},['CT Knife']={'Counter-Terrorists','Knife'},['T Glove']={'Terrorists','Glove'},['CT Glove']={'Counter-Terrorists','Glove'}}
    local function viewmodelCaller()
        if not (debug and type(debug.info)=="function") then return false end
        for level=3,14 do
            local ok,source=pcall(debug.info,level,"s")
            if not ok or not source then break end
            if type(source)=="string" and source:lower():find("viewmodel",1,true) then return true end
        end
        return false
    end
    -- Значения читаются на Heartbeat, перехваченный игровой поток только использует снимок.
    local previewContext={allowed=false,team=nil,weaponName=nil,knifeSkin="Stock",gloveSkin="Stock"}
    local function chosenSkin(inputValue,listWidget,model)
        local skinName=type(inputValue)=="string" and inputValue:match("^%s*(.-)%s*$") or "Stock"
        if skinName=="" or skinName=="Stock" then
            local ok,value=false,nil
            if listWidget and type(listWidget.Get)=="function" then ok,value=pcall(listWidget.Get,listWidget) end
            skinName=ok and type(value)=="string" and value or "Stock"
        end
        if #skinName>80 then return "Stock" end
        if skinName=="Stock" or skinName=="" then return "Stock" end
        local known=q.ValidSkins and q.ValidSkins[model]
        if type(known)=="table" and not known[skinName] then return "Stock" end
        return skinName
    end
    local function refreshPreviewContext()
        local context=previewContext;context.allowed=false
        if not gui.Parent or not q.Enabled then return end
        local team=localPlayer:GetAttribute("Team")
        local ctrl=state.rapid and state.rapid.controller;local getter=ctrl and ctrl.peekCurrentEquippedForMovement
        if type(getter)~="function" then return end
        local ok,weapon=pcall(getter)
        if not ok or type(weapon)~="table" or weapon.Player~=localPlayer or weapon.IsDestroyed then return end
        context.team=team;context.weaponName=weapon.Name
        context.knifeSkin=chosenSkin(q.KnifeSkin,q.KnifeList,q.KnifeModel)
        context.gloveSkin=chosenSkin(q.GloveSkin,q.GloveList,q.GloveModel)
        context.allowed=true
    end
    local function replacement(item,skin)
        if not q.Enabled or not previewContext.allowed then return item,skin end
        local desc=mapping[item]
        if not desc or previewContext.team~=desc[1] or not viewmodelCaller() then return item,skin end
        if desc[2]=="Knife" and item~=previewContext.weaponName then return item,skin end
        local selected=desc[2]=="Knife" and q.KnifeModel or q.GloveModel
        local allowed=desc[2]=="Knife" and knife or glove
        if not allowed[selected] then return item,skin end
        return selected,desc[2]=="Knife" and previewContext.knifeSkin or previewContext.gloveSkin
    end
    local function restore()
        if lib then
            for name,pair in pairs(installed) do pcall(function()if lib[name]==pair.wrapper then lib[name]=pair.original end end) end
        end
        table.clear(installed);q.Ready=false;lib=nil
    end
    local methods={"GetCameraModel","GetBaseWeaponModel","GetMagazine","GetItemIconImage","GetSkinInformation","GetGloves"}
    local function install()
        if not (debug and type(debug.info)=="function") then return false end
        local target=getModule("Database","Components","Libraries","Skins")
        if not target then return false end
        local staged={}
        for _,name in ipairs(methods) do
            local original=target[name]
            if type(original)=="function" then
                local function wrapped(item,skin,...)
                    local ok,newItem,newSkin=pcall(replacement,item,skin)
                    if ok then return original(newItem,newSkin,...) end
                    return original(item,skin,...)
                end
                local ok=pcall(function()target[name]=wrapped end)
                if not ok or target[name]~=wrapped then
                    for key,pair in pairs(staged) do pcall(function()if target[key]==pair.wrapper then target[key]=pair.original end end) end
                    return false
                end
                staged[name]={original=original,wrapper=wrapped}
            end
        end
        if not (staged.GetCameraModel or staged.GetGloves) then
            for key,pair in pairs(staged) do pcall(function()if target[key]==pair.wrapper then target[key]=pair.original end end) end
            return false
        end
        installed=staged;lib=target;q.Ready=true;return true
    end
    local last=0;local connection
    connection=RunService.Heartbeat:Connect(function()
        if not gui.Parent then previewContext.allowed=false;connection:Disconnect();restore();return end
        local updated=pcall(refreshPreviewContext);if not updated then previewContext.allowed=false end
        local now=os.clock();if now-last<1 then return end;last=now
        if not q.Enabled then if q.Ready then restore() end;return end
        if not q.Ready then
            local ok,done=pcall(install)
            if (not ok or not done) and now-warningAt>12 then warningAt=now;warn("[NOIR / Skin preview] Skins module unavailable or not writable") end
        end
    end)
end

-- Игровые события Shitaro: CreateImpact и UIPlayerKilled. При их отсутствии остаётся HP-эвристика.
do
    local q={HitReady=false,KillReady=false};state.feedbackEvents=q
    local hitEndpoint,killEndpoint,hitStop,killStop
    local attempted=setmetatable({},{__mode="k"})
    local function isConnection(value)
        return typeof(value)=="RBXScriptConnection" or (type(value)=="table" and type(value.Disconnect)=="function")
    end
    local function stop(fn)
        if type(fn)=="function" then pcall(fn)
        elseif isConnection(fn) then pcall(fn.Disconnect,fn) end
    end
    local function playerFor(id)
        id=tonumber(id);if not id or type(Players.GetPlayerByUserId)~="function" then return nil end
        local ok,result=pcall(Players.GetPlayerByUserId,Players,id)
        return ok and result or nil
    end
    local function victimModel(packet,id)
        local player=playerFor(id)
        if player==localPlayer then return nil end
        if player and player.Character then return player.Character end
        local characters=Workspace:FindFirstChild("Characters")
        if player and characters then
            local model=characters:FindFirstChild(player.Name)
            if model then return model end
        end
        local part=packet and packet.Instance
        if typeof(part)=="Instance" then
            local ok,model=pcall(part.FindFirstAncestorOfClass,part,"Model")
            if ok and model~=localPlayer.Character then return model end
        end
        return nil
    end
    local function hit(packet)
        if not gui.Parent or not q.HitReady or type(packet)~="table" or packet.Exit==true then return end
        local attacker=tonumber(packet.AttackerUserId);local mine=tonumber(localPlayer.UserId)
        if not mine or not attacker or attacker~=mine then return end
        local victimId=tonumber(packet.VictimUserId)
        if victimId and victimId==mine then return end
        local model=victimModel(packet,victimId)
        local player=playerFor(victimId)
        if not player and model then player=Players:FindFirstChild(model.Name) end
        if not player or player==localPlayer then return end
        local myTeam=localPlayer:GetAttribute("Team");local targetTeam=player:GetAttribute("Team")
        if Workspace:GetAttribute("Gamemode")~="Deathmatch" and Workspace:GetAttribute("VIPFriendlyFireEnabled")~=true and myTeam~=nil and targetTeam~=nil and myTeam==targetTeam then return end
        if state.noteGameHit then pcall(state.noteGameHit,player,packet) end
        if state.feedbackEnabled and state.feedbackEnabled() and state.showHitFeedback then
            pcall(state.showHitFeedback,model,1,1,packet.Position)
        end
    end
    local function kill(packet)
        if not gui.Parent or not q.KillReady or type(packet)~="table" then return end
        local killer=tonumber(packet.Killer);local mine=tonumber(localPlayer.UserId);local victim=tonumber(packet.Victim)
        if not mine or not killer or not victim or killer~=mine or victim==mine then return end
        if state.noteGameKill then pcall(state.noteGameKill,playerFor(victim),packet) end
        if state.feedbackEnabled and state.feedbackEnabled() and state.showHitFeedback then
            pcall(state.showHitFeedback,victimModel(packet,victim),1,0,packet.DeathPosition)
        end
    end
    local function attach(endpoint,handler)
        if type(endpoint)~="table" or type(endpoint.Listen)~="function" or attempted[endpoint] then return nil end
        local active=false
        local function guarded(packet)
            if active then state.enqueueGameEvent(handler,packet,function()return active end) end
        end
        local ok,disconnect=pcall(endpoint.Listen,guarded)
        if not ok then return nil end
        -- Неподконтрольный callback остаётся неактивным даже после смены endpoint.
        if type(disconnect)=="function" or isConnection(disconnect) then
            active=true
            return function() active=false;stop(disconnect) end
        end
        attempted[endpoint]=true
        return nil
    end
    local last=0;local con
    con=RunService.Heartbeat:Connect(function()
        if not gui.Parent then
            con:Disconnect();q.HitReady=false;q.KillReady=false;stop(hitStop);stop(killStop);return
        end
        local now=os.clock();if now-last<2 then return end;last=now
        local remotes=getModule("Database","Security","Remotes")
        local hitRemote=remotes and remotes.VFX and remotes.VFX.CreateImpact
        local killRemote=remotes and remotes.UI and remotes.UI.UIPlayerKilled
        if hitRemote~=hitEndpoint then stop(hitStop);hitStop=nil;hitEndpoint=hitRemote;q.HitReady=false end
        if killRemote~=killEndpoint then stop(killStop);killStop=nil;killEndpoint=killRemote;q.KillReady=false end
        if not q.HitReady and hitRemote then hitStop=attach(hitRemote,hit);q.HitReady=hitStop~=nil end
        if not q.KillReady and killRemote then killStop=attach(killRemote,kill);q.KillReady=killStop~=nil end
    end)
end

local function LoadAirflow()
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local MarketplaceService = game:GetService("MarketplaceService")
local StatsService = game:GetService("Stats")

local LocalPlayer = Players.LocalPlayer

local Library = {}

Library.Flags = {}
Library.Windows = {}

local function normalize(source, map)
local opts = {}
if type(source) == "string" then
opts.Name = source
elseif type(source) == "table" then
for key, value in pairs(source) do
opts[key] = value
end
end
for from, to in pairs(map or {}) do
if opts[to] == nil and opts[from] ~= nil then
opts[to] = opts[from]
end
end
if opts.Range then
opts.Min = opts.Min or opts.Range[1]
opts.Max = opts.Max or opts.Range[2]
end
return opts
end

local function finishElement(tab, opts, element, frame, kind)
element._type = kind
element._frame = frame
element._listeners = element._listeners or {}
local window = tab and tab.Window
local searchText = opts.Name or opts.Text or opts.Title
element._searchName = type(searchText) == "string" and searchText or ""
element._searchKey = string.lower(element._searchName)
if tab and tab._items then
table.insert(tab._items, element)
end
if opts.Flag then
Library.Flags[opts.Flag] = element
if window then
window:_flagCreated(opts.Flag, element)
end
end
element._userVisible = opts.Visible ~= false
function element:IsVisible()
return element._userVisible
end
function element:_isShown()
return element._userVisible and not (tab and tab._userVisible == false)
end
function element:SetVisible(visible)
visible = visible and true or false
if visible == element._userVisible or element._destroyed then
return
end
element._userVisible = visible
if not visible then
if element._onHide then
element._onHide()
end
if element.Open and type(element.SetOpen) == "function" then
element:SetOpen(false)
end
end
if frame then
frame.Visible = visible
end
if window then
window._controlsDirty = true
end
end
if frame and not element._userVisible then
frame.Visible = false
end
-- Tooltip: a string, or { Title, Text, Icon }. nil, false or "" hides it.
function element:SetTooltip(tip)
element._tooltip = tip
if frame and window and not element._tooltipBound then
element._tooltipBound = true
window:_attachTooltip(element, frame)
end
end
function element:GetTooltip()
return element._tooltip
end
if opts.Tooltip ~= nil and opts.Tooltip ~= false then
element:SetTooltip(opts.Tooltip)
end
function element:Destroy()
if element._destroyed then
return
end
element._destroyed = true
if window and window._tipOwner == element then
window:_hideTooltip()
end
for _, disconnect in ipairs(element._listeners) do
disconnect()
end
element._listeners = {}
if tab and tab._items then
local index = table.find(tab._items, element)
if index then
table.remove(tab._items, index)
end
end
if opts.Flag and Library.Flags[opts.Flag] == element then
Library.Flags[opts.Flag] = nil
end
if window then
window._controlsDirty = true
end
if frame then
frame:Destroy()
end
end
return element
end

Library.Theme = {
Background = Color3.fromRGB(12, 14, 12),
Surface = Color3.fromRGB(16, 20, 17),
Surface2 = Color3.fromRGB(22, 28, 23),
Surface3 = Color3.fromRGB(32, 44, 34),
Stroke = Color3.fromRGB(28, 44, 31),
StrokeHover = Color3.fromRGB(50, 105, 65),
Accent = Color3.fromRGB(50, 230, 150),
AccentDark = Color3.fromRGB(12, 28, 18),
Text = Color3.fromRGB(235, 248, 238),
Muted = Color3.fromRGB(115, 145, 125),
Warning = Color3.fromRGB(240, 190, 75),
Success = Color3.fromRGB(50, 230, 150),
Error = Color3.fromRGB(245, 85, 85),
}

-- Order decides which key wins when two theme colors are identical.
local THEME_KEYS = {
"Accent", "AccentDark", "Background", "Surface", "Surface2", "Surface3",
"Stroke", "StrokeHover", "Text", "Muted", "Warning", "Success", "Error",
}

local function rgb(r, g, b)
return Color3.fromRGB(r, g, b)
end

local function preset(background, surface, surface2, surface3, strokeColor, strokeHover, accent, accentDark, text, muted)
return {
Background = rgb(table.unpack(background)),
Surface = rgb(table.unpack(surface)),
Surface2 = rgb(table.unpack(surface2)),
Surface3 = rgb(table.unpack(surface3)),
Stroke = rgb(table.unpack(strokeColor)),
StrokeHover = rgb(table.unpack(strokeHover)),
Accent = rgb(table.unpack(accent)),
AccentDark = rgb(table.unpack(accentDark)),
Text = rgb(table.unpack(text)),
Muted = rgb(table.unpack(muted)),
}
end

Library.ThemePresets = {
