end
local selectAll = actionButton(opts.SelectAllText or "Select all", UDim2.fromOffset(0, 0))
local clearAll = actionButton(opts.ClearAllText or "Clear all", UDim2.new(0.5, 3, 0, 0))

local list = create("ScrollingFrame", {
