_connections = {},
_controls = {},
_inputListeners = { Began = {}, Changed = {}, Ended = {}, Render = {} },
_frameSteps = {},
_destroyed = false,
_identity = { Names = {}, Avatars = {} },
_pinned = {},
Minimized = false,
_hideName = false,
