applyIcon(minimizeGlyph, "minimize-2")
minimizeButton.MouseEnter:Connect(function()
tween(minimizeGlyph, { ImageColor3 = Theme.Text, Size = UDim2.fromOffset(18, 18) }, 0.2, Enum.EasingStyle.Quint)
