function Tab:SetBadge() end

function Tab:GetBadge()
return nil
end

function Window:Dialog(opts)
opts = normalize(opts, { Text = "Content", Message = "Content" })
if self._dialog then
self._dialog.Close()
end
local WIDTH = 300
local PAD = 18

local overlay = create("TextButton", {
