    -- Panic отключает функции напрямую, без конфигов.
    local panic=left(settingsTab,"Panic","shield")
    local panicEnabled=false
    local panicButton=Instance.new("TextButton")
    panicButton.Name="NoirPanicButton"
    panicButton.Size=UDim2.fromOffset(72,30)
    panicButton.Position=UDim2.new(1,-90,0.5,50)
    panicButton.Text="PANIC"
    panicButton.TextSize=12
    panicButton.Font=Enum.Font.GothamBold
    panicButton.TextColor3=Color3.fromRGB(231,244,234)
    panicButton.BackgroundColor3=Color3.fromRGB(21,40,28)
    panicButton.BorderSizePixel=0
    panicButton.Visible=false
    panicButton.ZIndex=150
    panicButton.Parent=gui
    round(panicButton,8)
    local start,origin,dragged,pointer
    panicButton.InputBegan:Connect(function(input)
        if not start and (input.UserInputType==Enum.UserInputType.Touch or input.UserInputType==Enum.UserInputType.MouseButton1) then
            pointer=input;start=input.Position;origin=panicButton.AbsolutePosition;dragged=false
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if not start then return end
        if pointer.UserInputType==Enum.UserInputType.Touch then
            if input~=pointer then return end
        elseif input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local delta=input.Position-start
        if delta.Magnitude>5 then dragged=true end
        if dragged then
            local camera=Workspace.CurrentCamera
            local size=camera and camera.ViewportSize or Vector2.new(1920,1080)
            panicButton.Position=UDim2.fromOffset(math.clamp(origin.X+delta.X,0,math.max(size.X-72,0)),math.clamp(origin.Y+delta.Y,0,math.max(size.Y-30,0)))
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if pointer and (input==pointer or (pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then start=nil;pointer=nil end
    end)
    local function activatePanic()
        if not panicEnabled then return end
        for _,widget in ipairs(panicControls) do
            if widget and type(widget.Set)=="function" then pcall(widget.Set,widget,false) end
        end
    end
    panicButton.Activated:Connect(function()
        if dragged then dragged=false;return end
        activatePanic()
    end)
    panic:CreateToggle({Name="Enable panic",Desc="Turns features off using the panic key or mobile button",CurrentValue=false,Callback=function(v)
        panicEnabled=v;panicButton.Visible=v and UserInputService.TouchEnabled
    end})
    panic:CreateKeybind({Name="Panic key",CurrentKeybind="RightShift",OnChanged=function()end,Callback=activatePanic})
    settingsTab:CreateConfigManager({Name="Configs",Side="Left"})
    settingsTab:CreateThemeManager({Name="Themes",Side="Right"})
    -- Автозагрузка после создания всех элементов. Без выбора и создания конфигов.
    task.defer(function()
        local selectedOk,selected=pcall(window.GetAutoload,window)
        if not selectedOk then selected=nil end
        local callOk,ok,info
        if selected then
            callOk,ok,info=pcall(window.LoadConfig,window,selected)
            if not callOk or not ok then
                warn("[NOIR] Выбранный автоконфиг недоступен; загружаем последние настройки")
                selected=nil
            end
        end
        if not selected then
            callOk,ok,info=pcall(window.LoadNoirSettings,window)
        end
        if not callOk then info,ok=ok,false end
        autoReady=true
        if ok and (selected or info==true) then
            scheduleSave()
        elseif not ok and info~="настроек пока нет" then
            warn("[NOIR] Автозагрузка настроек: "..tostring(info))
        end
    end)
    return window
end

state.startAirflow=function()
    if state.airflowStarted then return end
    state.airflowStarted=true
    local ok,result=pcall(buildAirflow)
    if not ok then
        warn("[NOIR] AirFlow не загрузился, оставлено прежнее меню: "..tostring(result))
        if state.airflow and state.airflow.Gui then pcall(function() state.airflow.Gui:Destroy() end) end
        state.airflow=nil
        return
    end
    local hidden=Instance.new("Frame")
    hidden.Name,hidden.Visible,hidden.BackgroundTransparency,hidden.Size,hidden.Parent="LegacyBacking",false,1,UDim2.fromScale(1,1),gui
    menu.Parent,reopen.Parent=hidden,hidden
end
if state.introFinished then task.defer(state.startAirflow) end
